INSERT INTO _teaser_card_plan (site_id, column_name, old_value, new_value, change_key, reason, premise, evidence) VALUES
    ('0025b0ba-fd74-4c08-96e3-acc17956aa44'::uuid, 'card_description', 'Ruins of a large Jewish village from the Roman-Byzantine period, with an ancient synagogue and mausoleum. It may be the lost town of Teqoa of Galilee.', NULL, 'teaser-card-s022:0025b0ba-fd74-4c08-96e3-acc17956aa44:card_description', 'teaser-card-s022 (card-clear-unproven-after-verify): card cleared (unproven-after-verify)', '||d656109b8605c184ef1a99a800d9c94f6f9ddb2af2dae53e68ec97018ad4422e', '[{"source": "lane WB run wb-ws-2026-09-27-05: unproven-after-verify", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "The web check could not prove: Horvat Shema is an archaeological site (ruins) in Israel at the foot of Mount Meron; The web check could not prove: The ruins are those of a village; The web check could not prove: The village was Jewish; The web check could not prove: The village dates to the Roman and Byzantine periods; The web check could not prove: Horvat Shema is an archaeological site (village with synagogue and mausoleum) in Israel"}]'::jsonb),
    ('0047ae41-af8e-44e1-b196-4035f5860554'::uuid, 'card_description', 'A fortress city guarding the only two mountain passes into Thessaly from the north. Whoever held Gonnus controlled access to the Thessalian plain.', NULL, 'teaser-card-s022:0047ae41-af8e-44e1-b196-4035f5860554:card_description', 'teaser-card-s022 (card-clear-unproven-after-verify): card cleared (unproven-after-verify)', '||0402574baef52c15ad7def4e353a42a6afa2f70c5c297809acf3e5a2e71cc05b', '[{"source": "lane WB run wb-ws-2026-09-27-05: unproven-after-verify", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "The web check could not prove: Gonnus was a town of the Perrhaebi (ancient Thessaly); The web check could not prove: Gonnus was a town (polis) in ancient Thessaly, in Greece"}]'::jsonb),
    ('0060e6c0-8388-4762-bf51-9a3f88807899'::uuid, 'card_description', 'Several major structures, unearthed across the site and mostly dated to Late Antiquity, bear traces of earthquakes and violent destruction.', 'In the forested foothills of the Greater Caucasus lies Nekresi, a large settlement whose extent remains unknown, with a winery, a Zoroastrian fire temple and early Christian basilicas.', 'teaser-card-s022:0060e6c0-8388-4762-bf51-9a3f88807899:card_description', 'teaser-card-s022 (teaser-card): teaser card, 184 characters, checked PASS, web-verified VERIFIED', '2f2572f41e67334e093152315eab857722d00c7c4798875879d18b0b95cd2917|e14632f64765c15750841641ac52c4689b4ed34adb9b835dd8b69c99d6a76a8c|e14632f64765c15750841641ac52c4689b4ed34adb9b835dd8b69c99d6a76a8c', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "In the forested foothills of the Greater Caucasus lies Nekresi, a large settlement whose extent remains unknown, with a winery, a Zoroastrian fire temple and early Christian basilicas."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-001 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Nekresi lies in the foothills of the Greater Caucasus [S1]; the landscape there is forested [S3]; Nekresi is a large settlement [S3]; the settlement''s extent remains unknown [S3]; the site has a winery [S6]; the site has a Zoroastrian fire temple [S6]; the site has early Christian basilicas [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-001 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Nekresi is a large settlement (historic and archaeological site, ancient town) in Georgia [SUPPORTED: https://en.wikipedia.org/wiki/Nekresi]; Nekresi lies at the foothills of the Greater Caucasus (Kakheti, Georgia) [SUPPORTED: https://en.wikipedia.org/wiki/Nekresi]; The landscape is densely forested [SUPPORTED: https://en.wikipedia.org/wiki/Nekresi]; The extent of the settlement is unknown [SUPPORTED: https://en.wikipedia.org/wiki/Nekresi]; A winery was found at Nekresi [SUPPORTED: https://en.wikipedia.org/wiki/Nekresi]; A Zoroastrian fire temple was found at Nekresi (conventional identification; an alternative Manichean reading exists) [SUPPORTED: https://en.wikipedia.org/wiki/Nekresi]; Early Christian basilicas were found at Nekresi [SUPPORTED: https://en.wikipedia.org/wiki/Nekresi]"}]'::jsonb),
    ('006d81d8-1000-4954-9eb9-9ed2ba8187e5'::uuid, 'card_description', 'A square Roman fort with four corner towers and three additional towers, from the 3rd century AD. Interior spa remains suggest it was more than just a garrison.', 'On the Bürglen hill by the Pfäffikersee shore, Irgenhausen Castrum was built to secure a Roman road. In 1897, its stones, then believed a medieval castle''s, went into a nearby factory.', 'teaser-card-s022:006d81d8-1000-4954-9eb9-9ed2ba8187e5:card_description', 'teaser-card-s022 (teaser-card): teaser card, 184 characters, checked PASS, web-verified VERIFIED', '2f4818e71a35d81b1cbcadf858ac09230c8d948fc112234927c96584f0da2250|24310c9c1cc6d4557d795fc3454772e379a2dedefadf10db4c38233b599c05e3|24310c9c1cc6d4557d795fc3454772e379a2dedefadf10db4c38233b599c05e3', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "On the Bürglen hill by the Pfäffikersee shore, Irgenhausen Castrum was built to secure a Roman road. In 1897, its stones, then believed a medieval castle''s, went into a nearby factory."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-001 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Irgenhausen Castrum is on the Buerglen hill [S3]; it is by the shore of the Pfaeffikersee [S1]; it was built to secure a Roman road [S4, S5]; in 1897 its stones were used for a nearby factory [S6]; at that time the stones were believed to belong to a medieval castle [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-001 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Irgenhausen Castrum is a Roman fort on the Pfäffikersee shore in Switzerland [SUPPORTED: https://en.wikipedia.org/wiki/Irgenhausen_Castrum]; The castrum stands on the Bürglen hill [SUPPORTED: https://en.wikipedia.org/wiki/Irgenhausen_Castrum]; The castrum was built to secure the Roman road along the Pfäffikersee [SUPPORTED: https://en.wikipedia.org/wiki/Irgenhausen_Castrum]; In 1897 stones of the ruin were used for the construction of a nearby factory [SUPPORTED: https://en.wikipedia.org/wiki/Irgenhausen_Castrum]; The stones were at the time believed to be those of a medieval castle [SUPPORTED: https://en.wikipedia.org/wiki/Irgenhausen_Castrum]"}]'::jsonb),
    ('00c2b26f-d007-4c02-a5da-403f14f8daa5'::uuid, 'card_description', 'Pre-Hispanic site in the Yauyos highlands at 3,800 m above sea level. One of many high-altitude communities occupying Lima Region''s mountain ranges before Inca unification of the Andes.', 'Falcon village, the Quechua name says: Wamanmarka, a pre-Hispanic archaeological site in the Carania District of Yauyos Province, set at a height of 3,800 m in the Lima Region.', 'teaser-card-s022:00c2b26f-d007-4c02-a5da-403f14f8daa5:card_description', 'teaser-card-s022 (teaser-card): teaser card, 176 characters, checked PASS, web-verified VERIFIED', '06e39526e5aaaa8c99993796ee580c390332b5821838607bcb3dc6b56fc60e4c|2a75c7328c1c4f3a4e19f50d85ab3f88e1a903673eea9379c5356722c3305808|2a75c7328c1c4f3a4e19f50d85ab3f88e1a903673eea9379c5356722c3305808', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Falcon village, the Quechua name says: Wamanmarka, a pre-Hispanic archaeological site in the Carania District of Yauyos Province, set at a height of 3,800 m in the Lima Region."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-001 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "the Quechua name Wamanmarka means falcon village [S1]; Wamanmarka is a pre-Hispanic archaeological site [S1]; it is in the Carania District of Yauyos Province [S2]; it lies at a height of 3,800 m [S2]; it is in the Lima Region [S1]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-001 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Wamanmarka is a pre-Hispanic archaeological site [SUPPORTED: https://en.wikipedia.org/wiki/Wamanmarka,_Lima]; The site is in the Lima Region of Peru [SUPPORTED: https://en.wikipedia.org/wiki/Wamanmarka,_Lima]; The Quechua name means falcon village (waman falcon, marka village) [SUPPORTED: https://en.wikipedia.org/wiki/Wamanmarka,_Lima]; Wamanmarka is in Yauyos Province [SUPPORTED: https://en.wikipedia.org/wiki/Wamanmarka,_Lima]; Wamanmarka is in the Carania District [SUPPORTED: https://en.wikipedia.org/wiki/Wamanmarka,_Lima]; Carania District belongs to Yauyos Province [SUPPORTED: https://en.wikipedia.org/wiki/Carania_District]; Wamanmarka lies at a height of 3,800 m [SUPPORTED: https://en.wikipedia.org/wiki/Wamanmarka,_Lima]"}]'::jsonb),
    ('00d711e5-2c6b-40c5-9c5c-a0f673cac312'::uuid, 'card_description', NULL, 'When built, Belsar''s Hill would have been an island of firm soil in waterlogged fens. Its place on the Iceni and Catuvellauni boundary and likeness to other hillforts hint at the Iron Age.', 'teaser-card-s022:00d711e5-2c6b-40c5-9c5c-a0f673cac312:card_description', 'teaser-card-s022 (teaser-card): teaser card, 188 characters, checked PASS, web-verified VERIFIED', 'ab4bd6742b1c867ee99b670a757319370ede36b819c717ecb69d6e13c2f08838|171e956a93ff4b36c62b989a80b66e201b9be8f0c956ca24894c5f69d5ebc4e4|171e956a93ff4b36c62b989a80b66e201b9be8f0c956ca24894c5f69d5ebc4e4', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "When built, Belsar''s Hill would have been an island of firm soil in waterlogged fens. Its place on the Iceni and Catuvellauni boundary and likeness to other hillforts hint at the Iron Age."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-001 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "when built, Belsar''s Hill would have been an island of firm soil in waterlogged fens [S3]; it lies on the boundary between the Iceni and Catuvellauni tribal lands [S5]; it is a hillfort resembling other hillforts [S1, S5]; its location and that likeness suggest (hint at) an Iron Age origin [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-002 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Belsar''s Hill is a hillfort (an Iron Age-type fortified enclosure) near Willingham, Cambridgeshire, England [SUPPORTED: https://en.wikipedia.org/wiki/Belsar%27s_Hill]; At the time it was built, Belsar''s Hill would have been an island of firm soil in waterlogged fens [SUPPORTED: https://en.wikipedia.org/wiki/Belsar%27s_Hill]; Belsar''s Hill lies on the boundary between the tribal lands of the Iceni and the Catuvellauni [SUPPORTED: https://en.wikipedia.org/wiki/Belsar%27s_Hill]; Belsar''s Hill resembles other hillforts (Iron Age hillforts such as Arbury Banks or Wandlebury) [SUPPORTED: https://en.wikipedia.org/wiki/Belsar%27s_Hill]; The boundary location and the likeness to other hillforts hint (suggest) an Iron Age date [SUPPORTED: https://en.wikipedia.org/wiki/Belsar%27s_Hill]; The earthwork is considered to rest on an earlier Iron Age camp (Historic England; the scheduled ringwork was adapted from it) [SUPPORTED, no proving quote: https://historicengland.org.uk/listing/the-list/list-entry/1010368]"}]'::jsonb),
    ('01704ebd-c0b1-4c2b-bdd0-7ffb3b6b4370'::uuid, 'card_description', 'At 15 meters tall, this is the largest tumulus on Rügen — the biggest of all prehistoric mounds on that island. Legend says a giant dropped a load of earth while trying to fill a nearby ford.', 'Local legend says a giant, carrying clay to fill a narrow ford, lost it on the way. Near Sagard it rises still: the Dobberworth, about 15 metres tall, the largest tumulus on Rügen.', 'teaser-card-s022:01704ebd-c0b1-4c2b-bdd0-7ffb3b6b4370:card_description', 'teaser-card-s022 (teaser-card): teaser card, 180 characters, checked PASS, web-verified VERIFIED', '874f1cfb3d4a45a4a096d7c37747d07720889c5b5410af10b8617f8c2b998b2f|14f686fc22e287143ea6317279bd50ae5d0d6146af4556f725efc7b8138cb0fc|14f686fc22e287143ea6317279bd50ae5d0d6146af4556f725efc7b8138cb0fc', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Local legend says a giant, carrying clay to fill a narrow ford, lost it on the way. Near Sagard it rises still: the Dobberworth, about 15 metres tall, the largest tumulus on Rügen."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-001 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "according to local legend a giant carrying clay to fill a narrow ford lost it on the way, making the mound [S4]; the Dobberworth is near Sagard [S1]; it is about 15 metres tall [S2]; it is the largest tumulus on Ruegen [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-002 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "The Dobberworth is a prehistoric tumulus (burial mound) on Rügen near Sagard [SUPPORTED: https://en.wikipedia.org/wiki/Dobberworth]; The Dobberworth is about 15 metres tall [SUPPORTED: https://en.wikipedia.org/wiki/Dobberworth]; The Dobberworth is the largest tumulus on Rügen [SUPPORTED: https://en.wikipedia.org/wiki/Dobberworth]; Local legend says a giant, meaning to fill a narrow ford, lost the clay he was carrying on the way, and the mound is what fell [SUPPORTED: https://en.wikipedia.org/wiki/Dobberworth]; The mound stands at the southern edge of Sagard on Rügen (German Wikipedia: a Hügelgrab, one of the largest in northern Germany) [SUPPORTED: https://de.wikipedia.org/wiki/Dobberworth]"}]'::jsonb),
    ('01ba2123-82e2-45eb-acec-199b875dd371'::uuid, 'card_description', 'Stepped across steep Lycian slopes since the 2nd millennium BC, Arykanda''s bathhouse mosaic floor survives near-intact — remote location and early abandonment stopped later stone-robbers.', 'High on a mountain slope, the rich but remote Lycian city of Arykanda was built upon five large terraces, with Greek monuments such as an agora, a small stadium and a beautiful theatre.', 'teaser-card-s022:01ba2123-82e2-45eb-acec-199b875dd371:card_description', 'teaser-card-s022 (teaser-card): teaser card, 185 characters, checked PASS, web-verified VERIFIED', '17b158f03de024c5af88746472711bb3c431698f76f1351e21229168905ce021|64f3bf12cc29227b3095fd6a15c6a498049c5fc9705e1d3900dad18a01e910bb|64f3bf12cc29227b3095fd6a15c6a498049c5fc9705e1d3900dad18a01e910bb', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "High on a mountain slope, the rich but remote Lycian city of Arykanda was built upon five large terraces, with Greek monuments such as an agora, a small stadium and a beautiful theatre."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-001 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Arykanda lies high on a mountain slope [S2]; it was a rich but remote city [S2]; it was a Lycian city [S1]; it was built upon five large terraces [S2]; it had Greek monuments including an agora [S5]; it had a small stadium [S5]; it had a beautiful theatre [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-002 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Arykanda is an ancient Lycian city (in Antalya Province, Türkiye) [SUPPORTED: https://en.wikipedia.org/wiki/Arycanda]; Arykanda was a rich city [SUPPORTED: https://en.wikipedia.org/wiki/Arycanda]; Arykanda was remote [SUPPORTED: https://en.wikipedia.org/wiki/Arycanda]; Arykanda was built upon five large terraces [SUPPORTED: https://en.wikipedia.org/wiki/Arycanda]; Arykanda lies high on a mountain slope [SUPPORTED: https://en.wikipedia.org/wiki/Arycanda]; The city had Greek monuments, such as an agora [SUPPORTED: https://en.wikipedia.org/wiki/Arycanda]; The city had a small stadium [SUPPORTED: https://en.wikipedia.org/wiki/Arycanda]; The city had a beautiful theatre [SUPPORTED: https://en.wikipedia.org/wiki/Arycanda]"}]'::jsonb),
    ('01dee6c5-2bcd-4fe7-9126-755ea3c7a3f7'::uuid, 'card_description', 'The oldest known submerged city in the world, about 5,000 years old. It has a nearly complete town plan with streets, buildings, and tombs visible underwater.', 'In Vatika Bay, Pavlopetri keeps an almost complete town plan: at least 15 buildings lie in 3 to 4 metres of water, the town believed submerged by an earthquake around 1000 BCE.', 'teaser-card-s022:01dee6c5-2bcd-4fe7-9126-755ea3c7a3f7:card_description', 'teaser-card-s022 (teaser-card): teaser card, 176 characters, checked PASS, web-verified VERIFIED', '23fc3b6f3451ed8a2eb673f5d7b2ce08b47caa97d4f1259131ab0ba67463ca36|ad85dbae852399e7e4130602c07da65473e935a3af4253bcbd0e8185f58f46f0|ad85dbae852399e7e4130602c07da65473e935a3af4253bcbd0e8185f58f46f0', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "In Vatika Bay, Pavlopetri keeps an almost complete town plan: at least 15 buildings lie in 3 to 4 metres of water, the town believed submerged by an earthquake around 1000 BCE."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-001 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Pavlopetri is in Vatika Bay [S1]; it has an almost complete town plan [S2]; at least 15 buildings lie in 3 to 4 metres of water [S6]; the town is believed to have been submerged by an earthquake [S5]; the submergence is dated around 1000 BCE [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-002 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Pavlopetri is a submerged ancient town (city) [SUPPORTED: https://en.wikipedia.org/wiki/Pavlopetri]; Pavlopetri lies in Vatika Bay, Greece [SUPPORTED: https://en.wikipedia.org/wiki/Pavlopetri]; Pavlopetri keeps an almost complete town plan [SUPPORTED: https://en.wikipedia.org/wiki/Pavlopetri]; At least 15 buildings are known at the site [SUPPORTED: https://www.nottingham.ac.uk/pavlopetri/background.aspx]; The buildings lie in 3 to 4 metres of water [SUPPORTED: https://en.wikipedia.org/wiki/Pavlopetri]; The town is believed to have been submerged by an earthquake around 1000 BCE [SUPPORTED, no proving quote: https://en.wikipedia.org/wiki/Pavlopetri]"}]'::jsonb),
    ('020bd9f9-8d19-4e19-b869-189f4273707f'::uuid, 'card_description', 'Four Bronze Age barrows in a line on Bow Hill above Kingley Vale''s ancient yew forest. Crossed by a ridgeway trackway, they are among the grandest round barrows surviving on the South Downs.', 'Four aligned barrows on the South Downs, 3 to 4 metres high despite damage from early digs of which no records survive: the Devil''s Humps, believed Late Neolithic or Early Bronze Age.', 'teaser-card-s022:020bd9f9-8d19-4e19-b869-189f4273707f:card_description', 'teaser-card-s022 (teaser-card): teaser card, 183 characters, checked PASS, web-verified VERIFIED', 'a0b4e45653ca7ebf115f404839783842d17c168387dbb05cf8bd645984ffa051|9877bb97692354fa0bc469d69fc3bc86867933a23934b51f5086b965f7fd05b0|9877bb97692354fa0bc469d69fc3bc86867933a23934b51f5086b965f7fd05b0', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Four aligned barrows on the South Downs, 3 to 4 metres high despite damage from early digs of which no records survive: the Devil''s Humps, believed Late Neolithic or Early Bronze Age."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-001 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "the Devil''s Humps are four barrows [S2]; the barrows are aligned [S2]; they are on the South Downs [S1]; they stand 3 to 4 metres high [S2]; they were damaged by early explorations [S2]; no records of those early excavations survive [S3]; they are believed to date from the Late Neolithic or Early Bronze Age [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-002 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "The Devil''s Humps are barrows (burial mounds) on the South Downs near Stoughton [SUPPORTED: https://en.wikipedia.org/wiki/Devil%27s_Humps]; There are four barrows [SUPPORTED: https://en.wikipedia.org/wiki/Devil%27s_Humps]; The four barrows are aligned [SUPPORTED: https://en.wikipedia.org/wiki/Devil%27s_Humps]; The barrows are 3 to 4 metres high [SUPPORTED: https://en.wikipedia.org/wiki/Devil%27s_Humps]; The barrows have been damaged by early digs (explorations) [SUPPORTED: https://en.wikipedia.org/wiki/Devil%27s_Humps]; No records survive from the early digs [SUPPORTED: https://en.wikipedia.org/wiki/Devil%27s_Humps]; Because of that the date of construction is uncertain: the barrows are believed to be Late Neolithic or Early Bronze Age [SUPPORTED: https://en.wikipedia.org/wiki/Devil%27s_Humps]; The barrows are Bronze Age monuments, scheduled on the Sussex Downs (Historic England: Bell barrows date to the Early and Middle Bronze Age) [SUPPORTED, no proving quote: https://historicengland.org.uk/listing/the-list/list-entry/1008371]"}]'::jsonb),
    ('026dfe16-5509-47f2-bede-504b006d704d'::uuid, 'card_description', 'A Sassanian rock relief 4.9 m high and 6.5 m wide, carved into a cliff. Weathering and deliberate vandalism have largely destroyed the imagery.', 'An east-facing natural sandstone cliff bears a relief 4.9 m high and 6.5 m wide, likely carved around the 3rd Century AD. Its local name, Rag-i-Bibi, refers to Fatimah.', 'teaser-card-s022:026dfe16-5509-47f2-bede-504b006d704d:card_description', 'teaser-card-s022 (teaser-card): teaser card, 168 characters, checked PASS, web-verified VERIFIED', '14b799bd5e22da98d030f70cc44c8cf2900fdc20595d499828677ce7ea3f7fb6|9c562b728a8dc1b6e018d0cd6ec50ed79a7b003ab6cf14a5db4a262bc5aebfdc|9c562b728a8dc1b6e018d0cd6ec50ed79a7b003ab6cf14a5db4a262bc5aebfdc', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "An east-facing natural sandstone cliff bears a relief 4.9 m high and 6.5 m wide, likely carved around the 3rd Century AD. Its local name, Rag-i-Bibi, refers to Fatimah."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-001 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "the relief is carved into a natural sandstone cliff [S4]; the cliff faces east [S4]; the relief is 4.9 m high and 6.5 m wide [S3]; it was likely carved around the 3rd century AD [S2]; Rag-i-Bibi is the relief''s local name [S1]; the name refers to Fatimah [S1]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-verify-003 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Rag-i-Bibi is a rock relief carved on a cliff in Afghanistan (central claim: the place is a cliff relief) [SUPPORTED: https://en.wikipedia.org/wiki/Rag-i-Bibi]; The cliff is natural sandstone [SUPPORTED: https://en.wikipedia.org/wiki/Rag-i-Bibi]; The cliff faces east [SUPPORTED: https://en.wikipedia.org/wiki/Rag-i-Bibi]; The relief is 4.9 m high [SUPPORTED: https://en.wikipedia.org/wiki/Rag-i-Bibi]; The relief is 6.5 m wide [SUPPORTED: https://en.wikipedia.org/wiki/Rag-i-Bibi]; The relief was likely carved around the 3rd century AD [SUPPORTED: https://en.wikipedia.org/wiki/Rag-i-Bibi]; Rag-i-Bibi is the local name and refers to Fatimah [SUPPORTED: https://en.wikipedia.org/wiki/Rag-i-Bibi]"}]'::jsonb),
    ('02b17d07-e0f2-44b1-ad98-353810e678fd'::uuid, 'card_description', 'A Minoan settlement from the 2nd millennium BC with a palace, cemetery, and the only Minoan evidence of human sacrifice. The skeleton lay on an altar with a bronze blade.', 'Where the modern town stands, ancient Archanes once spread, likely a Summer Palace for the Knossos kings, Sir Arthur Evans declared. Its springs fed Minoan aqueducts to Kephala Hill.', 'teaser-card-s022:02b17d07-e0f2-44b1-ad98-353810e678fd:card_description', 'teaser-card-s022 (teaser-card): teaser card, 182 characters, checked PASS, web-verified VERIFIED', '1272cc24ab718c985844c133f084e970ab2776451ca2d67a16ff3ce481cc97a9|e137ba53b9f311e6a6c0b5f1dd7c8ac243c3cb5dcc3bed868e32021953431c0f|e137ba53b9f311e6a6c0b5f1dd7c8ac243c3cb5dcc3bed868e32021953431c0f', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Where the modern town stands, ancient Archanes once spread, likely a Summer Palace for the Knossos kings, Sir Arthur Evans declared. Its springs fed Minoan aqueducts to Kephala Hill."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-001 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "ancient Archanes spread over the area of the modern town [S1]; Sir Arthur Evans declared Archanes likely a Summer Palace for the Knossos kings [S2]; in the Minoan era aqueducts carried water from springs at Archanes to Kephala Hill [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-verify-003 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Archanes is an ancient Minoan settlement (archaeological site) in central Crete, Greece (central claim) [SUPPORTED: https://en.wikipedia.org/wiki/Archanes]; Ancient Archanes spread over the same area where the modern town stands [SUPPORTED: https://en.wikipedia.org/wiki/Archanes]; Sir Arthur Evans declared Archanes likely a Summer Palace for the Knossos kings [SUPPORTED: https://en.wikipedia.org/wiki/Archanes]; Archanes'' springs fed Minoan aqueducts [SUPPORTED: https://en.wikipedia.org/wiki/Archanes]; The aqueducts led to Kephala Hill [SUPPORTED: https://en.wikipedia.org/wiki/Archanes]"}]'::jsonb),
    ('02e075bc-19b7-4522-92ff-c07f230b5678'::uuid, 'card_description', 'A Maya city from 550-830 AD in a remote jungle region. Its carved stelae record royal histories and alliances, including ties to the powerful Calakmul dynasty.', 'On the banks of the lower Machaquila River lies Machaquila, a ruined Maya city of abundant sculpted monuments, unusual in its region for lacking both a ballcourt and an E-Group.', 'teaser-card-s022:02e075bc-19b7-4522-92ff-c07f230b5678:card_description', 'teaser-card-s022 (teaser-card): teaser card, 177 characters, checked PASS, web-verified VERIFIED', 'be87a77ecdf3f360fd212093a85d4bb513fee5c3bd62016b57a7922c5a9761ec|165310bdbf02bb12bb1785245b58113a4d9e9dffa2b1d56056a0d00a6c6b1253|165310bdbf02bb12bb1785245b58113a4d9e9dffa2b1d56056a0d00a6c6b1253', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "On the banks of the lower Machaquila River lies Machaquila, a ruined Maya city of abundant sculpted monuments, unusual in its region for lacking both a ballcourt and an E-Group."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-001 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Machaquila lies on the banks of the lower Machaquila River [S2]; it is a ruined Maya city [S1]; it is notable for abundant sculpted monuments [S7]; it is unusual in its region for lacking a ballcourt [S6]; it is unusual in its region for lacking an E-Group [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-verify-003 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Machaquila is a ruined Maya city in Guatemala (central claim) [SUPPORTED: https://en.wikipedia.org/wiki/Machaquila]; It lies on the banks of the lower Machaquila River [SUPPORTED: https://en.wikipedia.org/wiki/Machaquila]; The city is known for abundant sculpted monuments [SUPPORTED: https://en.wikipedia.org/wiki/Machaquila]; Machaquila is unusual in its region for lacking an E-Group [SUPPORTED: https://en.wikipedia.org/wiki/Machaquila]; Machaquila is unusual in its region for lacking a ballcourt [SUPPORTED: https://en.wikipedia.org/wiki/Machaquila]"}]'::jsonb),
    ('03b9c5be-ec62-4fe7-8231-c098a4d2b921'::uuid, 'card_description', 'The Temple of Concordia is an ancient Greek temple of Magna Graecia in the Valle dei Templi in Agrigento on the south coast of Sicily. The temple was built circa 440–430 BC.', 'In the Valley of the Temples stands the Temple of Concordia, built circa 440–430 BC, the largest and best-preserved Doric temple in Sicily, saved as a Christian basilica in the 6th century.', 'teaser-card-s022:03b9c5be-ec62-4fe7-8231-c098a4d2b921:card_description', 'teaser-card-s022 (teaser-card): teaser card, 189 characters, checked PASS, web-verified VERIFIED', 'f5f46afb4f1a6ad7dcb71ab17897d20cadccbeeb172a34f01ad8a665f6907039|898335f52604e97c46f9421f5eb75024a78049ad91c201d2c9859b84bbf4a206|898335f52604e97c46f9421f5eb75024a78049ad91c201d2c9859b84bbf4a206', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "In the Valley of the Temples stands the Temple of Concordia, built circa 440–430 BC, the largest and best-preserved Doric temple in Sicily, saved as a Christian basilica in the 6th century."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-001 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "the Temple of Concordia stands in the Valley of the Temples [S1]; it was built circa 440-430 BC [S4]; it is the largest Doric temple in Sicily [S2]; it is the best-preserved Doric temple in Sicily [S2]; its conversion into a Christian basilica saved it [S6]; the conversion happened in the 6th century [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-verify-003 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "The Temple of Concordia is an ancient Greek (Doric) temple in the Valley of the Temples at Agrigento, Sicily (central claim) [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Concordia]; The temple was built circa 440–430 BC [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Concordia]; It is the largest Doric temple in Sicily [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Concordia]; It is the best-preserved Doric temple in Sicily [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Concordia]; The temple was converted into a Christian basilica in the 6th century [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Concordia]; The conversion saved the temple from the destruction of pagan places of worship [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Concordia]"}]'::jsonb),
    ('043fd021-51f4-4365-9a86-366d834f6ab0'::uuid, 'card_description', 'A megalithic burial site with 69 monuments including hood stones, stone circles, and umbrella-shaped Kudakkal tombs from around 2000 BC.', 'Hood stones and stone circles mark Kudakkallu Parambu, a prehistoric burial site in Kerala: 69 megalithic monuments, built around 2000 BC, says the Archaeological Survey of India.', 'teaser-card-s022:043fd021-51f4-4365-9a86-366d834f6ab0:card_description', 'teaser-card-s022 (teaser-card): teaser card, 179 characters, checked PASS, web-verified VERIFIED', 'ce2f8767d5cfd151efd42cf4b42be9e4682679e1909ee7c2bf13a6d9d61f633c|ab5ec052d420d633afc50658a26025df6f8e4e2f51d9aac6948c12f686ed967b|ab5ec052d420d633afc50658a26025df6f8e4e2f51d9aac6948c12f686ed967b', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Hood stones and stone circles mark Kudakkallu Parambu, a prehistoric burial site in Kerala: 69 megalithic monuments, built around 2000 BC, says the Archaeological Survey of India."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-001 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "hood stones mark the site [S3]; stone circles mark the site [S3]; Kudakkallu Parambu is a prehistoric burial site [S1]; it is in Kerala [S1]; it has 69 megalithic monuments [S2]; the Archaeological Survey of India says the monuments were built around 2000 BC [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-verify-003 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Kudakkallu Parambu is a prehistoric megalithic burial site in Kerala (central claim) [SUPPORTED: https://en.wikipedia.org/wiki/Kudakkallu_Parambu]; Hood stones mark the site [SUPPORTED: https://en.wikipedia.org/wiki/Kudakkallu_Parambu]; Stone circles mark the site [SUPPORTED: https://en.wikipedia.org/wiki/Kudakkallu_Parambu]; The site has 69 megalithic monuments [SUPPORTED: https://en.wikipedia.org/wiki/Kudakkallu_Parambu]; The monuments were built around 2000 BC [SUPPORTED: https://en.wikipedia.org/wiki/Kudakkallu_Parambu]; The date of around 2000 BC is attributed to the Archaeological Survey of India [SUPPORTED: https://en.wikipedia.org/wiki/Kudakkallu_Parambu]"}]'::jsonb),
    ('050ff0e8-d181-4b9a-8c1b-9a5f1a5d48bb'::uuid, 'card_description', 'Hilltop fort at 220 metres above the River Lew near Lydford in Devon. A Norman motte-and-bailey castle was added below it to the northeast -- two fortifications from different eras on one hill.', 'High over the river Lew, some 220 metres above sea level, Burley Wood crowns a hilltop with an Iron Age hill fort, while a Norman motte-and-bailey earthwork lies just below it.', 'teaser-card-s022:050ff0e8-d181-4b9a-8c1b-9a5f1a5d48bb:card_description', 'teaser-card-s022 (teaser-card): teaser card, 176 characters, checked PASS, web-verified VERIFIED', '7837f1741a4fa79f7509f32b743bf6a21fcae83ecdb1728f294b847479dd8d38|2aa2f6f19dc79acbd276c57f706e8ee9895c54f2422eb92b37a9f2681f1a2772|2aa2f6f19dc79acbd276c57f706e8ee9895c54f2422eb92b37a9f2681f1a2772', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "High over the river Lew, some 220 metres above sea level, Burley Wood crowns a hilltop with an Iron Age hill fort, while a Norman motte-and-bailey earthwork lies just below it."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-002 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "the site overlooks the river Lew [S2]; the hilltop is some 220 metres above sea level [S2]; Burley Wood has an Iron Age hill fort [S1]; the hill fort occupies a hilltop [S2]; a Norman motte-and-bailey earthwork lies just below the fort [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-004 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Burley Wood is a hill fort (the site of a hill fort on a hilltop) in Devon, England [SUPPORTED: https://en.wikipedia.org/wiki/Burley_Wood]; The hill fort dates to the Iron Age [SUPPORTED: https://en.wikipedia.org/wiki/Burley_Wood]; The hill fort crowns a hilltop some 220 metres above sea level [SUPPORTED: https://en.wikipedia.org/wiki/Burley_Wood]; The hilltop is high over (overlooks) the river Lew [SUPPORTED: https://en.wikipedia.org/wiki/Burley_Wood]; The site also has a Norman motte-and-bailey earthwork [SUPPORTED: https://en.wikipedia.org/wiki/Burley_Wood]; The Norman motte-and-bailey earthwork lies just below the hill fort [SUPPORTED: https://en.wikipedia.org/wiki/Burley_Wood]"}]'::jsonb),
    ('05d4e028-3cd3-46e8-ad35-aaaf70a3077c'::uuid, 'card_description', 'The Heroon of Trysa is the modern name for an ancient tomb, built around 380 BCE in Trysa.', 'Raised around 380 BCE in ancient Lycia, the Heroon of Trysa was a tomb whose square outer wall bore a figural frieze of circa 152 plates, brought to Vienna in 1882.', 'teaser-card-s022:05d4e028-3cd3-46e8-ad35-aaaf70a3077c:card_description', 'teaser-card-s022 (teaser-card): teaser card, 164 characters, checked PASS, web-verified VERIFIED', '7141eeaa9a51a9156319e02be8606c0dfc9bb4f2f677d234f65b7e969cca9d3a|74823ccefee722fa0f9e5cc0a6c58c6e2bcaf7404ced1955159ffcdf433d27ff|74823ccefee722fa0f9e5cc0a6c58c6e2bcaf7404ced1955159ffcdf433d27ff', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Raised around 380 BCE in ancient Lycia, the Heroon of Trysa was a tomb whose square outer wall bore a figural frieze of circa 152 plates, brought to Vienna in 1882."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-002 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "it was built around 380 BCE [S1]; it is in ancient Lycia [S1]; the Heroon of Trysa is a tomb [S1]; the tomb''s square outer wall bore a figural frieze [S3]; the frieze consisted of circa 152 plates [S3]; the plates were brought to Vienna in 1882 [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-004 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "The Heroon of Trysa was a tomb [SUPPORTED: https://en.wikipedia.org/wiki/Heroon_of_Trysa]; It was built around 380 BCE [SUPPORTED: https://en.wikipedia.org/wiki/Heroon_of_Trysa]; It lay in ancient Lycia [SUPPORTED: https://en.wikipedia.org/wiki/Heroon_of_Trysa]; The tomb''s square outer wall bore a figural frieze [SUPPORTED: https://en.wikipedia.org/wiki/Heroon_of_Trysa]; The figural frieze consisted of circa 152 plates [SUPPORTED: https://en.wikipedia.org/wiki/Heroon_of_Trysa]; The frieze plates were brought to Vienna in 1882 [SUPPORTED: https://en.wikipedia.org/wiki/Heroon_of_Trysa]"}]'::jsonb),
    ('0675d36c-5ce2-40a3-867c-4d2e14069fc6'::uuid, 'card_description', 'Discovered in November 1824 by the archaeologist Antonio Bonucci, the House of the Tragic Poet has interested scholars and writers for generations.', 'Underfoot in the vestibule of the House of the Tragic Poet, Pompeii, a mosaic dog waits, leashed and chained to an arbitrary point. Would you dare step across it?', 'teaser-card-s022:0675d36c-5ce2-40a3-867c-4d2e14069fc6:card_description', 'teaser-card-s022 (teaser-card): teaser card, 162 characters, checked PASS, web-verified VERIFIED', 'bcab8c94bf93d72233dcac2d749519aa5cdaa82b6d3f4ee5add9b39a3ea30183|5382aadd05b12e69038decd41621f6f457dff22fd0ab7ef34c8337d82c86a72d|5382aadd05b12e69038decd41621f6f457dff22fd0ab7ef34c8337d82c86a72d', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-rewrite-v-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Underfoot in the vestibule of the House of the Tragic Poet, Pompeii, a mosaic dog waits, leashed and chained to an arbitrary point. Would you dare step across it?"}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-v-001 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "the mosaic is in the vestibule floor of the House of the Tragic Poet [S7]; the mosaic shows a dog [S7]; the dog is leashed and chained to an arbitrary point [S7]; the question implies the dog mosaic is a warning (Beware of the dog) [S8]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify2-001 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "The House of the Tragic Poet is a Roman house in Pompeii, Italy [SUPPORTED: https://en.wikipedia.org/wiki/House_of_the_Tragic_Poet]; The vestibule floor had a mosaic of a dog leashed and chained to an arbitrary point [SUPPORTED: https://en.wikipedia.org/wiki/House_of_the_Tragic_Poet]; The mosaic is on the floor of the vestibule (underfoot) [SUPPORTED: https://en.wikipedia.org/wiki/House_of_the_Tragic_Poet]; The dog is shown leashed [SUPPORTED: https://en.wikipedia.org/wiki/House_of_the_Tragic_Poet]; The mosaic served as a warning to visitors (implied challenge to step across it) [SUPPORTED: https://en.wikipedia.org/wiki/House_of_the_Tragic_Poet]"}]'::jsonb),
    ('06f6a014-f2c1-423a-8944-17c81374fd02'::uuid, 'card_description', 'Late Pleistocene burials from a former lakeshore, with over 22 individuals. Among the most robust early skeletal remains found on the continent.', 'On the rim of a former wetland, the Kow Swamp Archaeological Site held the largest known single population of late Pleistocene human remains, returned in 1990 to the Yorta Yorta people.', 'teaser-card-s022:06f6a014-f2c1-423a-8944-17c81374fd02:card_description', 'teaser-card-s022 (teaser-card): teaser card, 185 characters, checked PASS, web-verified VERIFIED', 'bf37c6da71bb6bb629cfea18c3ceb5a0d6e6d9b998c60708644ff024858e2a66|55280c443ee17161dc0139efc1aa7a9c230ebd8639be639efc27b6ca6dee52af|55280c443ee17161dc0139efc1aa7a9c230ebd8639be639efc27b6ca6dee52af', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "On the rim of a former wetland, the Kow Swamp Archaeological Site held the largest known single population of late Pleistocene human remains, returned in 1990 to the Yorta Yorta people."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-002 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "the site lies on the rim of a former wetland [S3]; the site held the largest known single population of human skeletal remains [S2]; the remains date from the late Pleistocene [S2]; the remains were returned in 1990 [S5]; they were returned to the Yorta Yorta people [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-004 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "The Kow Swamp Archaeological Site is an archaeological site (Aboriginal place) in Victoria, Australia [SUPPORTED: https://en.wikipedia.org/wiki/Ghow_Swamp_Aboriginal_Place]; The remains lie on the rim of a wetland [SUPPORTED: https://en.wikipedia.org/wiki/Ghow_Swamp_Aboriginal_Place]; The wetland is a former wetland [SUPPORTED: https://en.wikipedia.org/wiki/Ghow_Swamp_Aboriginal_Place]; The site holds the largest known single population of human remains of its kind [SUPPORTED: https://en.wikipedia.org/wiki/Ghow_Swamp_Aboriginal_Place]; The remains date to the late Pleistocene [SUPPORTED: https://en.wikipedia.org/wiki/Ghow_Swamp_Aboriginal_Place]; The remains were returned in 1990 [SUPPORTED: https://en.wikipedia.org/wiki/Ghow_Swamp_Aboriginal_Place]; The remains were returned to the Yorta Yorta people [SUPPORTED: https://en.wikipedia.org/wiki/Ghow_Swamp_Aboriginal_Place]"}]'::jsonb),
    ('07c6a59d-7cb0-469b-936c-3bb984dc30a5'::uuid, 'card_description', '3rd-century BC Thracian burial complex near Sveshtari, where one tomb is linked to Cothelas, king of the Getae. Just metres from this site stands the world-heritage Tomb of Sveshtari.', 'Near Sveshtari, the Getic Burial Complex holds a Thracian tomb from the beginning of the third century BC and the Omurtag mount, a tomb linked to Cothelas, king of the Getae.', 'teaser-card-s022:07c6a59d-7cb0-469b-936c-3bb984dc30a5:card_description', 'teaser-card-s022 (teaser-card): teaser card, 174 characters, checked PASS, web-verified VERIFIED', '0253f29e91e5d6df391b7c2bf37c8b9c4cd8f98b10d9572fc4f81c1472cf7dd3|50fbd7878cfc6aa657df1580e5a4a3bcd6a0b2b112ffe32e2c0bab0f71de62f3|50fbd7878cfc6aa657df1580e5a4a3bcd6a0b2b112ffe32e2c0bab0f71de62f3', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Near Sveshtari, the Getic Burial Complex holds a Thracian tomb from the beginning of the third century BC and the Omurtag mount, a tomb linked to Cothelas, king of the Getae."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-002 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "the complex is near Sveshtari [S1]; it holds a Thracian tomb [S2]; that tomb dates from the beginning of the third century BC [S2]; the Omurtag mount is another tomb of the complex [S3]; the Omurtag mount is linked to Cothelas [S3]; Cothelas was king of the Getae [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-004 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "The Getic Burial Complex is an archaeological site near Sveshtari in Bulgaria [SUPPORTED: https://en.wikipedia.org/wiki/Getic_burial_complex]; The complex holds a Thracian tomb [SUPPORTED: https://en.wikipedia.org/wiki/Getic_burial_complex]; The Thracian tomb dates from the beginning of the third century BC [SUPPORTED: https://en.wikipedia.org/wiki/Getic_burial_complex]; The Omurtag mount is a tomb at the complex [SUPPORTED: https://en.wikipedia.org/wiki/Getic_burial_complex]; The Omurtag mount tomb is linked to Cothelas [SUPPORTED: https://en.wikipedia.org/wiki/Getic_burial_complex]; Cothelas was a king of the Getae [SUPPORTED: https://en.wikipedia.org/wiki/Cothelas]"}]'::jsonb),
    ('07ea80ce-863f-43b9-8f7e-d155a0182f4f'::uuid, 'card_description', 'The layout of the mausoleum is modeled on the layout of Xianyang, the capital of the Qin dynasty, which was divided into inner and outer cities.', 'Under a 76-metre-tall mound shaped like a truncated pyramid lies Qin Shi Huang’s Mausoleum, built over 38 years, its tomb still unexcavated, the Terracotta Army its garrison.', 'teaser-card-s022:07ea80ce-863f-43b9-8f7e-d155a0182f4f:card_description', 'teaser-card-s022 (teaser-card): teaser card, 174 characters, checked PASS, web-verified VERIFIED', '1d6a615f2bc70a6648a3b9663459370157a3ce5b732eb45f83e2e1d7ce415291|e11acea72f3849ca892cc8f934bf28804d384a423fa9071a92d9ba60d48a4cb2|e11acea72f3849ca892cc8f934bf28804d384a423fa9071a92d9ba60d48a4cb2', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Under a 76-metre-tall mound shaped like a truncated pyramid lies Qin Shi Huang’s Mausoleum, built over 38 years, its tomb still unexcavated, the Terracotta Army its garrison."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-002 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "the mausoleum lies under a tomb mound [S3]; the mound is 76 metres tall [S3]; the mound is shaped like a truncated pyramid [S3]; the mausoleum was built over 38 years [S3]; the tomb itself has not yet been excavated [S6]; the Terracotta Army served as the mausoleum''s garrison [S8]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-005 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Qin Shi Huang''s Mausoleum is a tomb complex (a mausoleum) for the first emperor of the Qin dynasty, in China (Lintong District, Xi''an, Shaanxi) [SUPPORTED: https://en.wikipedia.org/wiki/Mausoleum_of_Qin_Shi_Huang]; The mausoleum lies in modern-day Lintong District in Xi''an, Shaanxi (China) [SUPPORTED: https://en.wikipedia.org/wiki/Mausoleum_of_Qin_Shi_Huang]; The mausoleum lies under a 76-metre-tall mound [SUPPORTED: https://en.wikipedia.org/wiki/Mausoleum_of_Qin_Shi_Huang]; The mound is shaped like a truncated pyramid [SUPPORTED: https://en.wikipedia.org/wiki/Mausoleum_of_Qin_Shi_Huang]; The mausoleum was built over 38 years [SUPPORTED: https://en.wikipedia.org/wiki/Mausoleum_of_Qin_Shi_Huang]; The tomb itself is still unexcavated [SUPPORTED: https://en.wikipedia.org/wiki/Mausoleum_of_Qin_Shi_Huang]; The Terracotta Army is the garrison of the mausoleum [SUPPORTED: https://en.wikipedia.org/wiki/Mausoleum_of_Qin_Shi_Huang]"}]'::jsonb),
    ('0a8f4bd4-8115-4b64-b20c-0014b2458106'::uuid, 'card_description', 'A pair of Neolithic cursuses built end to end stretch 10 km across the chalk of Cranborne Chase — the Gussage Cursus to the south predating the Pentridge Cursus to the north. Built around 3300 BC.', 'Across 10 km of chalk downland on Cranborne Chase runs the Dorset Cursus, parallel banks about 82 m apart dating from 3300 BCE, built in an estimated 0.5 million worker-hours.', 'teaser-card-s022:0a8f4bd4-8115-4b64-b20c-0014b2458106:card_description', 'teaser-card-s022 (teaser-card): teaser card, 175 characters, checked PASS, web-verified VERIFIED', '786c6dbea9d97ad95001619cf19cb048a08fa249f289d40d5b1b432036f7d5c3|c735fbd8db5fde7e0a37d1c8f8ab1b9d78a81fb5e3b4e9797fd0d967ec07e4a3|c735fbd8db5fde7e0a37d1c8f8ab1b9d78a81fb5e3b4e9797fd0d967ec07e4a3', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Across 10 km of chalk downland on Cranborne Chase runs the Dorset Cursus, parallel banks about 82 m apart dating from 3300 BCE, built in an estimated 0.5 million worker-hours."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-002 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "the cursus spans 10 km [S1]; it runs across chalk downland on Cranborne Chase [S1]; it consists of parallel banks [S5]; the banks are about 82 m apart [S5]; it dates from 3300 BCE [S3]; its construction took an estimated 0.5 million worker-hours [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-005 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "The Dorset Cursus is a Neolithic cursus monument (a linear earthwork), i.e. an earthwork monument rather than a fort, settlement or tomb [SUPPORTED: https://en.wikipedia.org/wiki/Dorset_Cursus]; The Dorset Cursus is in England (east Dorset) [SUPPORTED: https://en.wikipedia.org/wiki/Dorset]; The Dorset Cursus lies on the chalk downland of Cranborne Chase [SUPPORTED: https://en.wikipedia.org/wiki/Dorset_Cursus]; The Dorset Cursus is 10 km long, spanning 10 km of Cranborne Chase [SUPPORTED: https://cranbornechase.org.uk/the-chase-chalke-projects/the-curious-dorset-cursus/]; The Cursus consists of parallel banks about 82 m apart [SUPPORTED: https://cranbornechase.org.uk/the-chase-chalke-projects/the-curious-dorset-cursus/]; The Dorset Cursus dates from 3300 BCE [SUPPORTED: https://en.wikipedia.org/wiki/Dorset_Cursus]; Construction took an estimated 0.5 million worker-hours [SUPPORTED: https://en.wikipedia.org/wiki/Dorset_Cursus]"}]'::jsonb),
    ('0d1797ca-6a3a-41fc-acbd-73c94d84a285'::uuid, 'card_description', 'The pyramid complex suffered major damage at the end of the New Kingdom as a result of spoliation.', 'At Abusir, the Pyramid of Khentkaus II, attributed to a queen who may have ruled Egypt, is now a ruin just 4 metres high. In it lay fragments of a grey-black granite pyramidion.', 'teaser-card-s022:0d1797ca-6a3a-41fc-acbd-73c94d84a285:card_description', 'teaser-card-s022 (teaser-card): teaser card, 177 characters, checked PASS, web-verified VERIFIED', '28c41a5b28c340e2a54d5f2fb251335e99355271646e091029cc0fa392ed39ac|eae8e3a2b8896ebf4d10b8a060c9edde8e12c358b2bc1d3eae497aa94c19694b|eae8e3a2b8896ebf4d10b8a060c9edde8e12c358b2bc1d3eae497aa94c19694b', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "At Abusir, the Pyramid of Khentkaus II, attributed to a queen who may have ruled Egypt, is now a ruin just 4 metres high. In it lay fragments of a grey-black granite pyramidion."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-002 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "the pyramid is at Abusir [S1]; the pyramid is attributed to a queen [S2]; the queen may have ruled Egypt (hedge kept) [S2]; the pyramid is now a ruin [S3]; the ruin stands just 4 metres high [S3]; fragments of a grey-black granite pyramidion were found in it [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-005 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "The Pyramid of Khentkaus II is a queen''s pyramid, i.e. a pyramid tomb, in Egypt [SUPPORTED: https://en.wikipedia.org/wiki/Pyramid_of_Khentkaus_II]; The pyramid is at Abusir (in the necropolis of Abusir in Egypt) [SUPPORTED: https://en.wikipedia.org/wiki/Pyramid_of_Khentkaus_II]; The pyramid is attributed to a queen, Khentkaus II [SUPPORTED: https://en.wikipedia.org/wiki/Pyramid_of_Khentkaus_II]; The queen may have ruled Egypt [SUPPORTED: https://en.wikipedia.org/wiki/Pyramid_of_Khentkaus_II]; The pyramid is now a ruin [SUPPORTED: https://en.wikipedia.org/wiki/Pyramid_of_Khentkaus_II]; The ruin is just 4 metres high [SUPPORTED: https://en.wikipedia.org/wiki/Pyramid_of_Khentkaus_II]; The pyramid was topped by a grey-black granite pyramidion [SUPPORTED: https://en.wikipedia.org/wiki/Pyramid_of_Khentkaus_II]; Fragments of the pyramidion were found in the ruins of the pyramid [SUPPORTED: https://en.wikipedia.org/wiki/Pyramid_of_Khentkaus_II]"}]'::jsonb),
    ('0dd83b62-fce8-4143-9d25-ed7de89933d8'::uuid, 'card_description', 'Stantonbury Camp is the site of an Iron Age hill fort near Stanton Prior within the parish of Marksbury in Somerset.', 'On an isolated outcrop of Oolitic Limestone on the route of the Wansdyke, Stantonbury Camp was an Iron Age hill fort. Its iron sickle or pruning-hook blades now rest in the British Museum.', 'teaser-card-s022:0dd83b62-fce8-4143-9d25-ed7de89933d8:card_description', 'teaser-card-s022 (teaser-card): teaser card, 188 characters, checked PASS, web-verified VERIFIED', '15269be081ccdc033e4f89c072540c2850775d4c91b6e0bf26a1507c36924f75|fc078999fdbd193720c42abb79003582434d0a4051015aeb129ca5810d22d683|fc078999fdbd193720c42abb79003582434d0a4051015aeb129ca5810d22d683', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "On an isolated outcrop of Oolitic Limestone on the route of the Wansdyke, Stantonbury Camp was an Iron Age hill fort. Its iron sickle or pruning-hook blades now rest in the British Museum."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-002 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "the site is on an isolated outcrop of Oolitic Limestone [S3]; the site is on the route of the Wansdyke [S3]; Stantonbury Camp was an Iron Age hill fort [S1]; iron blades of sickles or pruning hooks come from the site [S4]; those blades are now in the British Museum [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-005 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Stantonbury Camp was an Iron Age hill fort (in Somerset, England) [SUPPORTED: https://en.wikipedia.org/wiki/Stantonbury_Camp]; The hillfort stands on an isolated outcrop of Oolitic Limestone [SUPPORTED: https://en.wikipedia.org/wiki/Stantonbury_Camp]; The hillfort is on the route of the Wansdyke [SUPPORTED: https://en.wikipedia.org/wiki/Stantonbury_Camp]; Iron agricultural implements from the site include blades of sickles or pruning hooks [SUPPORTED: https://en.wikipedia.org/wiki/Stantonbury_Camp]; These iron implements from the site are now in the collection of the British Museum [SUPPORTED: https://en.wikipedia.org/wiki/Stantonbury_Camp]"}]'::jsonb),
    ('0e01dd33-edd6-4259-91af-cd6501cd86ef'::uuid, 'card_description', 'The Smedmore Hill Settlement is an archaeological site about 2 miles south-west of Corfe Castle, in Dorset.', 'On the northern slope of a limestone ridge, the Smedmore Hill Settlement terraces small enclosures into the hillside, thought to be home to subsistence farmers of the Romano-British period.', 'teaser-card-s022:0e01dd33-edd6-4259-91af-cd6501cd86ef:card_description', 'teaser-card-s022 (teaser-card): teaser card, 189 characters, checked PASS, web-verified VERIFIED', 'bd53c4a1c599697f2b536e059738320aa338d3ee71feac5b8647e77a62ae13f8|e07f76f026e9c1c81ed92712e240dc3005a7f6b1af77bcadaafbd39b05ce0d09|e07f76f026e9c1c81ed92712e240dc3005a7f6b1af77bcadaafbd39b05ce0d09', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "On the northern slope of a limestone ridge, the Smedmore Hill Settlement terraces small enclosures into the hillside, thought to be home to subsistence farmers of the Romano-British period."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-002 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "the settlement is on the northern slope of a limestone ridge [S5]; it consists of small enclosures [S6]; the enclosures are terraced into the hillside [S6]; it is thought to have been home to subsistence farmers (hedge kept) [S4]; those farmers lived there in the Romano-British period [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-005 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "The Smedmore Hill Settlement is an archaeological site, a settlement with an associated field system, in Dorset, England [SUPPORTED: https://en.wikipedia.org/wiki/Smedmore_Hill_Settlement]; The site is in Dorset, England (south-west of Corfe Castle) [SUPPORTED: https://en.wikipedia.org/wiki/Smedmore_Hill_Settlement]; The settlement lies on the northern slope of a limestone ridge (Smedmore Hill) [SUPPORTED: https://en.wikipedia.org/wiki/Smedmore_Hill_Settlement]; Small enclosures are terraced into the hillside [SUPPORTED: https://en.wikipedia.org/wiki/Smedmore_Hill_Settlement]; The settlement is regarded as occupied by subsistence farmers [SUPPORTED: https://en.wikipedia.org/wiki/Smedmore_Hill_Settlement]; The occupation dates to the Romano-British period [SUPPORTED: https://en.wikipedia.org/wiki/Smedmore_Hill_Settlement]"}]'::jsonb),
    ('0e12027e-9a65-470f-aca7-2cb1eb408120'::uuid, 'card_description', 'A 500 BC Greek temple long misidentified as dedicated to Ceres. Terracotta figurines of Athena finally corrected the attribution centuries later.', 'Built around 500 BC at Paestum, the Temple of Athena was once thought to honour Ceres, until terracotta statuettes of Athena were found. Here Doric and Ionic orders share one building.', 'teaser-card-s022:0e12027e-9a65-470f-aca7-2cb1eb408120:card_description', 'teaser-card-s022 (teaser-card): teaser card, 184 characters, checked PASS, web-verified VERIFIED', '460dcfd9190b6819f6cf507848d507ec423c5f2f2045e3146e5cb08fa8212456|26aa2b9b98f6cfcc9b1639fbc31a382938fcd3f028185e4588c1e4b5415ab2bb|26aa2b9b98f6cfcc9b1639fbc31a382938fcd3f028185e4588c1e4b5415ab2bb', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Built around 500 BC at Paestum, the Temple of Athena was once thought to honour Ceres, until terracotta statuettes of Athena were found. Here Doric and Ionic orders share one building."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-002 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "the temple was built around 500 BC [S2]; it is at Paestum [S1]; it was once thought to have been dedicated to Ceres [S2]; that view changed after terracotta statuettes of Athena were found [S2]; Doric and Ionic orders co-exist in the one building [S3, S4, S6]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-006 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "The Temple of Athena is a (Greek) temple at Paestum, Italy [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Athena_(Paestum)]; It was built around 500 BC [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Athena_(Paestum)]; It was once thought to honour Ceres [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Athena_(Paestum)]; The attribution to Ceres was dropped after terracotta statuettes of Athena were found [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Athena_(Paestum)]; Doric and Ionic orders share one building (the temple combines both orders) [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Athena_(Paestum)]"}]'::jsonb),
    ('0f1ec894-b1b1-40e9-9e00-bd193b316484'::uuid, 'card_description', 'A Maya city from 600-1050 AD with a palace, altar, and a round structure that may be an oven. About 300 structures spread across a 6 km site.', 'In northeast Yucatan lies Kulubá, a Maya city with a palace 55 metres long, an altar, and a round structure believed to be an oven, amid some 300 smaller structures.', 'teaser-card-s022:0f1ec894-b1b1-40e9-9e00-bd193b316484:card_description', 'teaser-card-s022 (teaser-card): teaser card, 165 characters, checked PASS, web-verified VERIFIED', '927a862eff945a475ced14ec86ce8d13182a81159410da2444afb5a9c9b3fd1b|8e0546fefa9ee50073f9fbdfbf9096e32c03a347d38a1b7e583331e115af7cd5|8e0546fefa9ee50073f9fbdfbf9096e32c03a347d38a1b7e583331e115af7cd5', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "In northeast Yucatan lies Kulubá, a Maya city with a palace 55 metres long, an altar, and a round structure believed to be an oven, amid some 300 smaller structures."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-002 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "the site is in northeast Yucatan [S2]; it is a Maya city [S1]; it has a palace [S3]; the palace is 55 metres long [S4]; it has an altar [S3]; it has a round structure believed to be an oven (hedge kept) [S3]; some 300 smaller structures are at the site [S8]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-006 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Kulubá is a Maya city (archaeological site) [SUPPORTED: https://en.wikipedia.org/wiki/Kulub%C3%A1]; Kulubá lies in northeast Yucatan [SUPPORTED: https://en.wikipedia.org/wiki/Kulub%C3%A1]; The site has a palace that is 55 metres long [SUPPORTED: https://en.wikipedia.org/wiki/Kulub%C3%A1]; The site has an altar [SUPPORTED: https://en.wikipedia.org/wiki/Kulub%C3%A1]; A round structure at the site is believed to be an oven [SUPPORTED: https://en.wikipedia.org/wiki/Kulub%C3%A1]; The site lies amid some 300 smaller structures [SUPPORTED: https://en.wikipedia.org/wiki/Kulub%C3%A1]; Kulubá has a palace [SUPPORTED: https://en.wikipedia.org/wiki/Kulub%C3%A1]"}]'::jsonb),
    ('10096963-03a9-4698-82b9-8c6386759359'::uuid, 'card_description', 'A lake whose Greek name means ''ancient outlet,'' connected to the Black Sea by a narrow channel. Artifacts from the ancient kingdom of Colchis have been recovered from its waters.', 'Near Poti, Lake Paliastomi, its name Greek for ancient mouth, slips to the Black Sea through a narrow channel. In and around its waters, archaeologists found ancient pieces of Colchis.', 'teaser-card-s022:10096963-03a9-4698-82b9-8c6386759359:card_description', 'teaser-card-s022 (teaser-card): teaser card, 184 characters, checked PASS, web-verified VERIFIED', '2ccfa2a881f0895a4a3388266b7473c448c495694c61ca1727626601252607c2|11c5c47c2f254f179ff5344af303b1001993ba2ae2115e0b99b1f52001941047|11c5c47c2f254f179ff5344af303b1001993ba2ae2115e0b99b1f52001941047', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Near Poti, Lake Paliastomi, its name Greek for ancient mouth, slips to the Black Sea through a narrow channel. In and around its waters, archaeologists found ancient pieces of Colchis."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-002 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "the lake is near Poti [S1]; its name is Greek for ancient mouth [S1]; it is connected to the Black Sea [S1]; the connection is a narrow channel [S1]; archaeologists found ancient pieces of Colchis in and near the lake [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-006 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Lake Paliastomi is a lake [SUPPORTED: https://en.wikipedia.org/wiki/Lake_Paliastomi]; The lake is connected to the Black Sea by a narrow channel [SUPPORTED: https://en.wikipedia.org/wiki/Lake_Paliastomi]; Its name is Greek for ancient mouth [SUPPORTED: https://en.wikipedia.org/wiki/Lake_Paliastomi]; Archaeologists found ancient pieces of Colchis in and around the lake [SUPPORTED: https://en.wikipedia.org/wiki/Lake_Paliastomi]; The lake lies near Poti [SUPPORTED: https://en.wikipedia.org/wiki/Lake_Paliastomi]"}]'::jsonb),
    ('113ce1a7-3e6a-49cb-9120-e6e230191646'::uuid, 'card_description', 'A Mesoamerican centre of the Cotzumalhuapa culture from 600-800 AD. Its stone monuments depict human sacrifice, ballgame scenes, and cacao-themed rituals.', 'At Bilbao, a major centre of the Cotzumalhuapa culture, stelae show ballplayers with disembodied heads, and ballgame reliefs blossom with plants symbolic of agricultural fertility.', 'teaser-card-s022:113ce1a7-3e6a-49cb-9120-e6e230191646:card_description', 'teaser-card-s022 (teaser-card): teaser card, 180 characters, checked PASS, web-verified VERIFIED', 'd3e22e1697e7208aae85eb42aecd95f4be9a111cc1a5981c7d0869cfbf78d9e3|765bff59d1f71159262547c58d627808483268a2400c5b958e1d832a5ac2e596|765bff59d1f71159262547c58d627808483268a2400c5b958e1d832a5ac2e596', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "At Bilbao, a major centre of the Cotzumalhuapa culture, stelae show ballplayers with disembodied heads, and ballgame reliefs blossom with plants symbolic of agricultural fertility."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-002 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Bilbao was a major centre [S2]; it belonged to the Cotzumalhuapa culture [S2]; stelae at Bilbao depict ballplayers with disembodied heads [S8]; ballgame reliefs at Bilbao feature blossoming plants [S7]; those plants symbolise agricultural fertility [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-006 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Bilbao is an archaeological site in Guatemala [SUPPORTED: https://en.wikipedia.org/wiki/Bilbao_(Mesoamerican_site)]; Bilbao was a major centre of the Cotzumalhuapa culture [SUPPORTED: https://en.wikipedia.org/wiki/Bilbao_(Mesoamerican_site)]; Stelae at Bilbao show ballplayers with disembodied heads [SUPPORTED: https://en.wikipedia.org/wiki/Bilbao_(Mesoamerican_site)]; Ballgame reliefs at Bilbao show plants symbolic of agricultural fertility [SUPPORTED: https://en.wikipedia.org/wiki/Bilbao_(Mesoamerican_site)]; Bilbao belongs to the Cotzumalhuapa culture [SUPPORTED: https://en.wikipedia.org/wiki/Bilbao_(Mesoamerican_site)]"}]'::jsonb),
    ('11b0139d-eb15-4ea7-9bf2-699a39d2c731'::uuid, 'card_description', 'A twin-headland Iron Age fort of basaltic rock projecting into the Atlantic. Mediterranean pottery finds show trade links reaching far beyond Britain.', 'On a twin headland of hard basaltic rock thrust into the Atlantic, The Rumps holds an Iron Age fort of three ramparts, where the find of an amphora suggests trade with the Mediterranean.', 'teaser-card-s022:11b0139d-eb15-4ea7-9bf2-699a39d2c731:card_description', 'teaser-card-s022 (teaser-card): teaser card, 186 characters, checked PASS, web-verified VERIFIED', '5c4523bc3387f03ca4de46d207af1d4293dade6b8e1b61e138f7b7d93349de2f|7745f89fdc6420d70d5b5dfcfc80121e098484b4fd94632827e99371447603f6|7745f89fdc6420d70d5b5dfcfc80121e098484b4fd94632827e99371447603f6', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "On a twin headland of hard basaltic rock thrust into the Atlantic, The Rumps holds an Iron Age fort of three ramparts, where the find of an amphora suggests trade with the Mediterranean."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-002 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "The Rumps is a twin headland [S1]; it is formed of hard basaltic rock [S2]; it projects into the Atlantic [S2]; it is the site of an Iron Age fort [S3]; the fort has three ramparts [S8]; an amphora was found there [S6]; the amphora suggests trade with the Mediterranean (hedge kept) [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-006 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "The Rumps holds an Iron Age (promontory) fort [SUPPORTED: https://en.wikipedia.org/wiki/The_Rumps]; The Rumps is a twin headland [SUPPORTED: https://en.wikipedia.org/wiki/The_Rumps]; The headland is of hard basaltic rock [SUPPORTED: https://en.wikipedia.org/wiki/The_Rumps]; The headland projects into the Atlantic [SUPPORTED: https://en.wikipedia.org/wiki/The_Rumps]; The fort has three ramparts [SUPPORTED: https://en.wikipedia.org/wiki/The_Rumps]; An amphora was found at the fort [SUPPORTED: https://en.wikipedia.org/wiki/The_Rumps]; The amphora suggests trade with the Mediterranean [SUPPORTED: https://en.wikipedia.org/wiki/The_Rumps]"}]'::jsonb),
    ('1284cb97-6d86-411c-9643-1dc93c1dd47d'::uuid, 'card_description', 'La Roche-aux-Fées is a Neolithic gallery grave, or dolmen, located in the commune of Essé.', 'One of the largest Neolithic dolmens in Brittany, La Roche-aux-Fées is a covered passage of stone blocks roofed with laid stones, its axis aligned with sunrise at the winter solstice.', 'teaser-card-s022:1284cb97-6d86-411c-9643-1dc93c1dd47d:card_description', 'teaser-card-s022 (teaser-card): teaser card, 183 characters, checked PASS, web-verified VERIFIED', 'ac7eb315b61a24c275121e02438b5d78433595f8689cfe05ff7b3c88c37c6076|11391d30463655f0b314eed346e9c046ceb4ea298c8222f2638faac31a8774ba|11391d30463655f0b314eed346e9c046ceb4ea298c8222f2638faac31a8774ba', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-003", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "One of the largest Neolithic dolmens in Brittany, La Roche-aux-Fées is a covered passage of stone blocks roofed with laid stones, its axis aligned with sunrise at the winter solstice."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-003 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "La Roche-aux-Fees is one of the largest Neolithic dolmens in Brittany [S4]; it is a Neolithic dolmen [S1, S4]; it is a covered passage of stone blocks [S5]; it is roofed with stones laid across the blocks [S5]; its axis is aligned with sunrise at the winter solstice [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-verify-007 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "La Roche-aux-Fées is a dolmen (a gallery grave, a tomb) in Brittany, France [SUPPORTED: https://en.wikipedia.org/wiki/La_Roche-aux-F%C3%A9es]; It is a Neolithic monument [SUPPORTED: https://en.wikipedia.org/wiki/La_Roche-aux-F%C3%A9es]; It is one of the largest Neolithic dolmens in Brittany [SUPPORTED: https://en.wikipedia.org/wiki/La_Roche-aux-F%C3%A9es]; It is a covered passage of stone blocks [SUPPORTED: https://en.wikipedia.org/wiki/La_Roche-aux-F%C3%A9es]; The passage is roofed with stones laid across it [SUPPORTED: https://en.wikipedia.org/wiki/La_Roche-aux-F%C3%A9es]; Its axis is aligned with sunrise at the winter solstice [SUPPORTED: https://en.wikipedia.org/wiki/La_Roche-aux-F%C3%A9es]"}]'::jsonb),
    ('14570acc-bcd9-43b4-abca-f7a2a8d9035b'::uuid, 'card_description', 'The mound was about 43 metres long and 17m wide, but cultivation has spread the material and reduced the mound''s height.', 'South Street Barrow rose around wicker partitions in alternate layers of white chalk and darker earth, yet its excavator found no evidence of burials and conjectured a kind of cenotaph.', 'teaser-card-s022:14570acc-bcd9-43b4-abca-f7a2a8d9035b:card_description', 'teaser-card-s022 (teaser-card): teaser card, 185 characters, checked PASS, web-verified VERIFIED', 'aba55a93b58491aaef82225a9a0d02c8a45c57b7ad2e6961be678595023ca60a|caac805b172ef1c61ae2e09ec569518498f787806bea56c1ff205dd5e014a7fa|caac805b172ef1c61ae2e09ec569518498f787806bea56c1ff205dd5e014a7fa', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-003", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "South Street Barrow rose around wicker partitions in alternate layers of white chalk and darker earth, yet its excavator found no evidence of burials and conjectured a kind of cenotaph."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-003 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "the barrow was built around wicker partitions [S5]; it was built in alternate layers of white chalk and darker earth [S5]; its excavator found no evidence of burials [S4]; the excavator conjectured it was a kind of cenotaph [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-verify-007 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "South Street Barrow is a Neolithic long barrow (a burial-mound type of monument) in Wiltshire, England [SUPPORTED: https://en.wikipedia.org/wiki/South_Street_barrow]; It was built around wicker partitions [SUPPORTED: https://en.wikipedia.org/wiki/South_Street_barrow]; It was built in alternate layers of white chalk and darker earth [SUPPORTED: https://en.wikipedia.org/wiki/South_Street_barrow]; Its excavator found no evidence of burials [SUPPORTED: https://en.wikipedia.org/wiki/South_Street_barrow]; Its excavator conjectured that it was a kind of cenotaph [SUPPORTED: https://en.wikipedia.org/wiki/South_Street_barrow]"}]'::jsonb),
    ('14c408ee-cfa0-43cc-8294-a2f8cc0d76bb'::uuid, 'card_description', 'The first formal archaeological excavation was carried out in 1955 by a team led by Hipólito Cabaço.', 'North of Lisbon, the Cave of Pedra Furada held a communal funeral space. Among the finds: flint arrowheads, beads, a polished stone axe and a bone figurine of a rabbit.', 'teaser-card-s022:14c408ee-cfa0-43cc-8294-a2f8cc0d76bb:card_description', 'teaser-card-s022 (teaser-card): teaser card, 168 characters, checked PASS, web-verified VERIFIED', 'f75f72630733f13b18c7900a3ee326fc75467f2f0a83c3d0e62914b7a1a955e6|5acbb93eea8da98bfdfc0ffc24c3421eb5fd36f4f076cabba9daf1c42afa6f7c|5acbb93eea8da98bfdfc0ffc24c3421eb5fd36f4f076cabba9daf1c42afa6f7c', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-003", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "North of Lisbon, the Cave of Pedra Furada held a communal funeral space. Among the finds: flint arrowheads, beads, a polished stone axe and a bone figurine of a rabbit."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-003 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "the cave lies north of Lisbon [S1]; the cave held a communal funeral space [S5]; finds include flint arrowheads [S6]; finds include beads [S6]; finds include a polished stone axe [S6]; finds include a bone figurine of a rabbit [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-verify-007 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "The Cave of Pedra Furada is a cave about 20 km north of Lisbon, Portugal [SUPPORTED: https://en.wikipedia.org/wiki/Cave_of_Pedra_Furada]; The cave held a communal funeral space [SUPPORTED: https://en.wikipedia.org/wiki/Cave_of_Pedra_Furada]; Among the finds are flint arrowheads [SUPPORTED: https://en.wikipedia.org/wiki/Cave_of_Pedra_Furada]; Among the finds are beads [SUPPORTED: https://en.wikipedia.org/wiki/Cave_of_Pedra_Furada]; Among the finds is a polished stone axe [SUPPORTED: https://en.wikipedia.org/wiki/Cave_of_Pedra_Furada]; Among the finds is a bone figurine of a rabbit [SUPPORTED: https://en.wikipedia.org/wiki/Cave_of_Pedra_Furada]"}]'::jsonb),
    ('14eceb81-5819-4fb7-ac10-dfdb26ce63d1'::uuid, 'card_description', 'Iron Age hillfort discovered in 1933 with a ditch-and-bank on two of three sides. In 1956, quarrying at Coles Quarry nearly obliterated it — the site survived, but barely, on the quarry’s edge.', 'Backwell Hillfort, an Iron Age hill fort in Somerset, was first discovered in 1933, guarded by a large ditch and bank on two of its three sides. In 1956, quarrying nearly destroyed it.', 'teaser-card-s022:14eceb81-5819-4fb7-ac10-dfdb26ce63d1:card_description', 'teaser-card-s022 (teaser-card): teaser card, 184 characters, checked PASS, web-verified VERIFIED', 'df0e51ca5aeda702231ebdee4b5f6ba5f770fbfcc03ab904b98f369a0e6125fb|19402ea2557b14df9a1f059f874718869c3888ae0028014c6b20cfb92cba28fd|19402ea2557b14df9a1f059f874718869c3888ae0028014c6b20cfb92cba28fd', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-003", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Backwell Hillfort, an Iron Age hill fort in Somerset, was first discovered in 1933, guarded by a large ditch and bank on two of its three sides. In 1956, quarrying nearly destroyed it."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-003 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Backwell Hillfort is an Iron Age hill fort [S1]; it is in Somerset [S1]; it was first discovered in 1933 [S2]; two of its three sides were protected by a large ditch and bank [S2]; in 1956 quarrying nearly destroyed it [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-verify-007 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Backwell Hillfort is an Iron Age hill fort [SUPPORTED: https://en.wikipedia.org/wiki/Backwell_Hillfort]; It lies in Somerset (North Somerset district), England [SUPPORTED: https://en.wikipedia.org/wiki/Backwell_Hillfort]; It was first discovered in 1933 [SUPPORTED: https://en.wikipedia.org/wiki/Backwell_Hillfort]; Two of its three sides were guarded by a large ditch and bank [SUPPORTED: https://en.wikipedia.org/wiki/Backwell_Hillfort]; In 1956 quarrying nearly destroyed it [SUPPORTED: https://en.wikipedia.org/wiki/Backwell_Hillfort]"}]'::jsonb),
    ('1516a14a-9185-4adb-a7f9-c3b5cb14fa13'::uuid, 'card_description', 'The Frith is a small univallate Iron Age hillfort to the north of Silchester, Calleva Atrebatum.', 'North of Silchester, The Frith is a small Iron Age hillfort whose single bank guards every side but the south east. Close by to the south, a Roman road heads into Calleva Atrebatum.', 'teaser-card-s022:1516a14a-9185-4adb-a7f9-c3b5cb14fa13:card_description', 'teaser-card-s022 (teaser-card): teaser card, 181 characters, checked PASS, web-verified VERIFIED', '794635546105ae3bde41d755bc7b6fe994c7e8afb66d448514967445477430bb|a2da7e9fde4ad763d4c81b9aa68893cbfee5c8233496e77a16881102cdaea71f|a2da7e9fde4ad763d4c81b9aa68893cbfee5c8233496e77a16881102cdaea71f', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-003", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "North of Silchester, The Frith is a small Iron Age hillfort whose single bank guards every side but the south east. Close by to the south, a Roman road heads into Calleva Atrebatum."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-003 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "The Frith lies north of Silchester [S1]; it is a small Iron Age hillfort [S1]; a single bank covers every side except the south east [S2]; close by to the south a Roman road heads into Calleva Atrebatum [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-verify-007 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "The Frith is a small Iron Age hillfort [SUPPORTED: https://en.wikipedia.org/wiki/The_Frith]; It lies north of Silchester [SUPPORTED: https://en.wikipedia.org/wiki/The_Frith]; A single bank guards every side but the south east [SUPPORTED: https://en.wikipedia.org/wiki/The_Frith]; Close by to the south a Roman road heads into Calleva Atrebatum [SUPPORTED: https://en.wikipedia.org/wiki/The_Frith]"}]'::jsonb),
    ('15264f9b-f57b-4562-b577-fbfdec72227f'::uuid, 'card_description', 'A 5.7-km linear earthwork that may date to the Bronze Age and was reactivated in the 4th century AD. A Roman road was cut through it, then the dyke was rebuilt across it.', 'Bokerley Dyke runs 5.75 kilometres across Cranborne Chase. Cut by a Roman road in the 1st century, it was remodelled in the 4th century and the road blocked, shortly after 364 AD.', 'teaser-card-s022:15264f9b-f57b-4562-b577-fbfdec72227f:card_description', 'teaser-card-s022 (teaser-card): teaser card, 179 characters, checked PASS, web-verified VERIFIED', 'da643a7f891fb6721af751b003945bf4efaf45990fb25e9dcc63082bc528854d|4e4586b4717c4526fc96b692920df8f4ec595cb24ee4ff21224e3c2acb2529f5|4e4586b4717c4526fc96b692920df8f4ec595cb24ee4ff21224e3c2acb2529f5', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-003", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Bokerley Dyke runs 5.75 kilometres across Cranborne Chase. Cut by a Roman road in the 1st century, it was remodelled in the 4th century and the road blocked, shortly after 364 AD."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-003 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Bokerley Dyke is 5.75 kilometres long [S1]; it lies on Cranborne Chase [S1]; it was cut by a Roman road in the 1st century [S5]; it was remodelled in the 4th century [S6]; the Roman road was blocked [S6]; this remodelling and blocking dates to shortly after 364 AD [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-008 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Bokerley Dyke is a linear earthwork (a dyke), not a fort or settlement. [SUPPORTED: https://en.wikipedia.org/wiki/Bokerley_Dyke]; It runs 5.75 kilometres. [SUPPORTED: https://en.wikipedia.org/wiki/Bokerley_Dyke]; It lies on Cranborne Chase (Dorset, England). [SUPPORTED: https://en.wikipedia.org/wiki/Bokerley_Dyke]; It was cut through by a Roman road in the 1st century. [SUPPORTED: https://en.wikipedia.org/wiki/Bokerley_Dyke]; In the 4th century it was remodelled. [SUPPORTED: https://en.wikipedia.org/wiki/Bokerley_Dyke]; Excavations show that the Roman road was blocked. [SUPPORTED: https://en.wikipedia.org/wiki/Bokerley_Dyke]; The remodelling and road blocking is dated to shortly after 364 AD. [SUPPORTED: https://en.wikipedia.org/wiki/Bokerley_Dyke]"}]'::jsonb),
    ('15511706-1e3e-4b7f-974d-7464988b0462'::uuid, 'card_description', 'The temple was transferred to the Agora and rededicated to Ares during the reign of Augustus.', 'The Temple of Ares first stood at Pallene for Athena Pallenis, then was moved to the Agora of Athens under Augustus. Around 230 of its marble fragments were found reused across the Agora.', 'teaser-card-s022:15511706-1e3e-4b7f-974d-7464988b0462:card_description', 'teaser-card-s022 (teaser-card): teaser card, 187 characters, checked PASS, web-verified VERIFIED', '7145a2d932b44a14036df5ce7cac0c2586d985b02d3fd7b6461a209aab70f35a|9b75d65bd7984593857348ec775030e9039278991f8849190ecb207d59d09d60|9b75d65bd7984593857348ec775030e9039278991f8849190ecb207d59d09d60', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-003", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "The Temple of Ares first stood at Pallene for Athena Pallenis, then was moved to the Agora of Athens under Augustus. Around 230 of its marble fragments were found reused across the Agora."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-003 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "the temple originally stood at Pallene [S3]; at Pallene it was dedicated to Athena Pallenis [S3]; it was moved to the Agora of Athens [S1, S4]; the move happened under Augustus [S4]; around 230 of its fragments were found reused across the Agora [S5]; the fragments are marble [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-008 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "The Temple of Ares is a temple (a Doric hexastyle peripteral temple dedicated to Ares). [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Ares]; It now stands in the Agora of Athens (Greece). [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Ares]; It first stood at Pallene. [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Ares]; At Pallene it was dedicated to Athena Pallenis. [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Ares]; It was moved to the Agora under Augustus. [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Ares]; Around 230 fragments of the temple were found. [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Ares]; The fragments were found reused in later structures across the Agora. [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Ares]; The fragments are of marble. [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Ares]"}]'::jsonb),
    ('15ecd8c5-1887-4162-8b42-d2315b15f65a'::uuid, 'card_description', 'A cylindrical Roman funerary monument near Córdoba built in Republican-era style. Tombs like this lined the roads leading out of Roman cities during the early centuries AD.', 'In the Jardines de la Victoria stands the Roman Mausoleum of Córdoba, built under Tiberius for an unknown patrician, beside a columbarium for his kin. It was discovered in 1993.', 'teaser-card-s022:15ecd8c5-1887-4162-8b42-d2315b15f65a:card_description', 'teaser-card-s022 (teaser-card): teaser card, 177 characters, checked PASS, web-verified VERIFIED', 'd4c15f00bcd5fdde2aea9db4d61c49c37ffb7dd4680fc958821ff455cf8043e4|e52f25ad5f44b865316dcf7b54296e101f57887e5d9d5c4cf1adc3a3940809de|e52f25ad5f44b865316dcf7b54296e101f57887e5d9d5c4cf1adc3a3940809de', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-003", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "In the Jardines de la Victoria stands the Roman Mausoleum of Córdoba, built under Tiberius for an unknown patrician, beside a columbarium for his kin. It was discovered in 1993."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-003 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "the mausoleum stands in the Jardines de la Victoria [S1]; it was built under Tiberius [S4]; it was built for a patrician [S4]; the patrician is unknown [S4]; beside it is a columbarium for the patrician''s relatives [S5]; it was discovered in 1993 [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-008 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "The Roman Mausoleum of Córdoba is a Roman funerary monument (mausoleum). [SUPPORTED: https://en.wikipedia.org/wiki/Roman_mausoleum_of_C%C3%B3rdoba]; It stands in the Jardines de la Victoria, Córdoba, Spain. [SUPPORTED: https://en.wikipedia.org/wiki/Roman_mausoleum_of_C%C3%B3rdoba]; It was built under Tiberius. [SUPPORTED: https://en.wikipedia.org/wiki/Roman_mausoleum_of_C%C3%B3rdoba]; It was built for an unknown patrician. [SUPPORTED: https://en.wikipedia.org/wiki/Roman_mausoleum_of_C%C3%B3rdoba]; Beside it stands a columbarium. [SUPPORTED: https://en.wikipedia.org/wiki/Roman_mausoleum_of_C%C3%B3rdoba]; The columbarium was for the patrician''s kin (ancestors and relatives). [SUPPORTED: https://en.wikipedia.org/wiki/Roman_mausoleum_of_C%C3%B3rdoba]; It was discovered in 1993. [SUPPORTED: https://en.wikipedia.org/wiki/Roman_mausoleum_of_C%C3%B3rdoba]"}]'::jsonb),
    ('168431d1-ad6c-4a18-9798-2d43d361c5b1'::uuid, 'card_description', 'The clay and stone tombs of the complex have wooden roofs and are painted in red, yellow, black, and white colors.', 'Perched in a high rock cleft of Peru''s northern Andean cloud forests, the Chachapoya tombs of Los Pinchudos, of clay and stone under wooden roofs, are painted red, yellow, black and white.', 'teaser-card-s022:168431d1-ad6c-4a18-9798-2d43d361c5b1:card_description', 'teaser-card-s022 (teaser-card): teaser card, 188 characters, checked PASS, web-verified VERIFIED', 'a3cfbbfae3881dff30024ead3097f75bdf2455227775100bace91d76a3bbf46d|f87b8b82740f13023f92bf9a918a8b3d9756abf1267528b4a4a1a4d129074106|f87b8b82740f13023f92bf9a918a8b3d9756abf1267528b4a4a1a4d129074106', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-003", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Perched in a high rock cleft of Peru''s northern Andean cloud forests, the Chachapoya tombs of Los Pinchudos, of clay and stone under wooden roofs, are painted red, yellow, black and white."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-003 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "the tombs are perched in a high rock cleft [S1]; they are in Peru''s northern Andean cloud forests [S1]; they are Chachapoya tombs [S1]; the tombs are of clay and stone [S2]; the tombs have wooden roofs [S2]; the tombs are painted red, yellow, black and white [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-008 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Los Pinchudos is a Chachapoya tomb complex. [SUPPORTED: https://en.wikipedia.org/wiki/Los_Pinchudos]; It is perched in a high rock cleft. [SUPPORTED: https://en.wikipedia.org/wiki/Los_Pinchudos]; It lies in one of the northern Andean cloud forests of Peru. [SUPPORTED: https://en.wikipedia.org/wiki/Los_Pinchudos]; The tombs are of clay and stone. [SUPPORTED: https://en.wikipedia.org/wiki/Los_Pinchudos]; The tombs have wooden roofs. [SUPPORTED: https://en.wikipedia.org/wiki/Los_Pinchudos]; The tombs are painted red, yellow, black and white. [SUPPORTED: https://en.wikipedia.org/wiki/Los_Pinchudos]"}]'::jsonb),
    ('169edf74-fc91-4850-aa2a-7d5328c13c02'::uuid, 'card_description', 'The archaeological site of Intikancha was declared a National Cultural Heritage by Resolución Directoral Nacional No. 79.', 'About 4,400 metres high in the Andes of Peru, the mountain Intikancha bears an archaeological site of the same name, declared a National Cultural Heritage, south of Pukarani.', 'teaser-card-s022:169edf74-fc91-4850-aa2a-7d5328c13c02:card_description', 'teaser-card-s022 (teaser-card): teaser card, 174 characters, checked PASS, web-verified VERIFIED', '1ccdd79050e9ad6495a2e888164c77121773a3edda3fff175f0207087bbf976e|73ad7c76403ddf1d7a0fd100c1999201056e27d7d3a7fa31be5119aaacbff51d|73ad7c76403ddf1d7a0fd100c1999201056e27d7d3a7fa31be5119aaacbff51d', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-003", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "About 4,400 metres high in the Andes of Peru, the mountain Intikancha bears an archaeological site of the same name, declared a National Cultural Heritage, south of Pukarani."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-003 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Intikancha is a mountain in the Andes of Peru [S1]; it is about 4,400 metres high [S1]; it has an archaeological site of the same name [S1]; the site was declared a National Cultural Heritage [S3]; it lies south of Pukarani [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-008 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Intikancha is a mountain. [SUPPORTED: https://en.wikipedia.org/wiki/Intikancha_(Puno)]; The mountain bears an archaeological site of the same name. [SUPPORTED: https://en.wikipedia.org/wiki/Intikancha_(Puno)]; It is in the Andes of Peru. [SUPPORTED: https://en.wikipedia.org/wiki/Intikancha_(Puno)]; It is about 4,400 metres high. [SUPPORTED: https://en.wikipedia.org/wiki/Intikancha_(Puno)]; The archaeological site was declared a National Cultural Heritage. [SUPPORTED: https://en.wikipedia.org/wiki/Intikancha_(Puno)]; It lies south of Pukarani. [SUPPORTED: https://en.wikipedia.org/wiki/Intikancha_(Puno)]"}]'::jsonb),
    ('17b9fc46-bc88-42a8-9606-7d7bc0dac9d1'::uuid, 'card_description', 'A Roman signal tower built on high ground above the Stanegate road in the early 2nd century AD. It was later absorbed into Hadrian''s Wall, with a 2-metre fragment still standing.', 'On high ground above the Roman Stanegate road, Pike Hill Signal Tower signalled to Gillalees Beacon and Barrock Fell. Built before the nearby walls, it later became part of Hadrian''s Wall.', 'teaser-card-s022:17b9fc46-bc88-42a8-9606-7d7bc0dac9d1:card_description', 'teaser-card-s022 (teaser-card): teaser card, 188 characters, checked PASS, web-verified VERIFIED', 'ca400afc1f83e72725357c59083d545c6bdd558400b4a6887227a42f98da0fb3|a16d199d4ed1c3f8f73c35383d44ee3a49e7f1e022f9743593564a766186137c|a16d199d4ed1c3f8f73c35383d44ee3a49e7f1e022f9743593564a766186137c', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-003", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "On high ground above the Roman Stanegate road, Pike Hill Signal Tower signalled to Gillalees Beacon and Barrock Fell. Built before the nearby walls, it later became part of Hadrian''s Wall."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-003 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "the tower stood on high ground above the Roman Stanegate road [S1]; it signalled to Gillalees Beacon and Barrock Fell [S4]; it was built before the nearby walls [S5]; it later became part of Hadrian''s Wall [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-009 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Pike Hill Signal Tower is a Roman signal tower (signal station) in England [SUPPORTED: https://en.wikipedia.org/wiki/Pike_Hill_Signal_Tower]; It stands on high ground above the Roman Stanegate road [SUPPORTED: https://en.wikipedia.org/wiki/Pike_Hill_Signal_Tower]; The tower signalled to Gillalees Beacon and Barrock Fell [SUPPORTED: https://en.wikipedia.org/wiki/Pike_Hill_Signal_Tower]; It was built before the nearby (turf and stone) walls [SUPPORTED: https://en.wikipedia.org/wiki/Pike_Hill_Signal_Tower]; It later became part of Hadrian''s Wall [SUPPORTED: https://en.wikipedia.org/wiki/Pike_Hill_Signal_Tower]"}]'::jsonb),
    ('17c73394-bfd9-4c62-99d4-4b062994f8bb'::uuid, 'card_description', 'The second-largest town in Roman Syrmia, after Sirmium, connected by a road to Singidunum. Only a small fraction of the ancient city has been preserved above ground.', 'Bassianae was a Roman town, the second largest in Syrmia after Sirmium, on the road to Singidunum. Digs in 1935 found its walls, towers, coins, sculptures and mosaics.', 'teaser-card-s022:17c73394-bfd9-4c62-99d4-4b062994f8bb:card_description', 'teaser-card-s022 (teaser-card): teaser card, 167 characters, checked PASS, web-verified VERIFIED', '194a4657f9b6aa886fc484f6fa537eace87c340021a9be927f62b26ffef90563|29073e8f883266636bd015350033b0069eacf6f7852797c502e9deb780f98b3c|29073e8f883266636bd015350033b0069eacf6f7852797c502e9deb780f98b3c', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-003", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Bassianae was a Roman town, the second largest in Syrmia after Sirmium, on the road to Singidunum. Digs in 1935 found its walls, towers, coins, sculptures and mosaics."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-003 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Bassianae was a Roman town [S1]; it was the second largest town in Syrmia after Sirmium [S3]; it lay on the road to Singidunum [S4]; excavations in 1935 found walls, towers, coins, sculptures and mosaics [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-009 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Bassianae was a Roman town (in Syrmia, Serbia) [SUPPORTED: https://en.wikipedia.org/wiki/Bassianae]; It was the second largest town in Syrmia, after Sirmium [SUPPORTED: https://en.wikipedia.org/wiki/Bassianae]; It lay on the road to Singidunum [SUPPORTED: https://en.wikipedia.org/wiki/Bassianae]; Excavations in 1935 found its walls, towers, coins, sculptures and mosaics [SUPPORTED: https://en.wikipedia.org/wiki/Bassianae]"}]'::jsonb),
    ('1877a303-0731-4ad3-9814-2b852ff93242'::uuid, 'card_description', 'An Iron Age drystone tower with 4-metre-thick walls and no mortar. Brochs like this are unique to the Highlands — over 500 were built, but none exist anywhere else on Earth.', 'On a small rocky knoll on Skye, the drystone walls of Dun Beag Broch, about 4 metres thick at the base, hide a small chamber, a long narrow gallery and a stone stair.', 'teaser-card-s022:1877a303-0731-4ad3-9814-2b852ff93242:card_description', 'teaser-card-s022 (teaser-card): teaser card, 166 characters, checked PASS, web-verified VERIFIED', '34195e7a48f74bdf01193f02190b08c6cb58a96f6274dd82bb73f579bf0f1a2f|a0ed255d82f75389b937cf5e217052a0cf7587702a3f1e3b2ad29f7b09499ada|a0ed255d82f75389b937cf5e217052a0cf7587702a3f1e3b2ad29f7b09499ada', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-003", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "On a small rocky knoll on Skye, the drystone walls of Dun Beag Broch, about 4 metres thick at the base, hide a small chamber, a long narrow gallery and a stone stair."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-003 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "the broch is on a small rocky knoll [S2]; it is on Skye [S1]; its walls are drystone [S3]; the walls are about 4 metres thick at the base [S3]; the walls contain access to a small chamber, a long narrow gallery and a stone stair [S5, S6]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-009 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Dun Beag is a broch (an Iron Age drystone tower) [SUPPORTED: https://en.wikipedia.org/wiki/Dun_Beag]; It is on the island of Skye [SUPPORTED: https://en.wikipedia.org/wiki/Dun_Beag]; It stands on a small rocky knoll [SUPPORTED: https://en.wikipedia.org/wiki/Dun_Beag]; It is built of drystone walls [SUPPORTED: https://en.wikipedia.org/wiki/Dun_Beag]; The walls are about 4 metres thick at the base [SUPPORTED: https://en.wikipedia.org/wiki/Dun_Beag]; The wall hides a small chamber [SUPPORTED: https://en.wikipedia.org/wiki/Dun_Beag]; The wall hides a long narrow gallery [SUPPORTED: https://en.wikipedia.org/wiki/Dun_Beag]; The wall hides a stone stair [SUPPORTED: https://en.wikipedia.org/wiki/Dun_Beag]"}]'::jsonb),
    ('18c1589b-3ebd-4267-8567-effd7e549792'::uuid, 'card_description', 'A Bronze Age barrow near Stonehenge that produced some of Britain''s most spectacular grave goods, including worked gold objects. It marks a burial of the Wessex elite culture.', 'Around 1 kilometre from Stonehenge, Bush Barrow held a male skeleton buried circa 1950 BC with a lozenge-shaped sheet of gold, bronze daggers, a bronze axe and a stone macehead.', 'teaser-card-s022:18c1589b-3ebd-4267-8567-effd7e549792:card_description', 'teaser-card-s022 (teaser-card): teaser card, 177 characters, checked PASS, web-verified VERIFIED', 'e05f477cf37dbb2e29e6ab2504e27a2f267bed39d94e4d5a2d206fa4ad9ee799|2d4715b62093d354b619f0c8613c087b52ee63f9e42f06b99ad9ab3383c42ad3|2d4715b62093d354b619f0c8613c087b52ee63f9e42f06b99ad9ab3383c42ad3', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-003", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Around 1 kilometre from Stonehenge, Bush Barrow held a male skeleton buried circa 1950 BC with a lozenge-shaped sheet of gold, bronze daggers, a bronze axe and a stone macehead."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-003 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Bush Barrow lies around 1 kilometre from Stonehenge [S3]; it held a male skeleton [S5]; the burial dates to circa 1950 BC [S6]; the grave goods include a lozenge-shaped sheet of gold [S6]; the grave goods include bronze daggers [S6]; the grave goods include a bronze axe [S6]; the grave goods include a stone macehead [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-009 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Bush Barrow is a Bronze Age burial mound (barrow) in the Normanton Down Barrows cemetery near Stonehenge, England [SUPPORTED: https://en.wikipedia.org/wiki/Bush_Barrow]; It lies around 1 kilometre from Stonehenge [SUPPORTED: https://en.wikipedia.org/wiki/Bush_Barrow]; The barrow held a male skeleton [SUPPORTED: https://en.wikipedia.org/wiki/Bush_Barrow]; The burial dates to circa 1950 BC [SUPPORTED: https://en.wikipedia.org/wiki/Bush_Barrow]; The grave goods included a lozenge-shaped sheet of gold [SUPPORTED: https://en.wikipedia.org/wiki/Bush_Barrow]; The grave goods included bronze daggers [SUPPORTED: https://en.wikipedia.org/wiki/Bush_Barrow]; The grave goods included a bronze axe [SUPPORTED: https://en.wikipedia.org/wiki/Bush_Barrow]; The grave goods included a stone macehead [SUPPORTED: https://en.wikipedia.org/wiki/Bush_Barrow]"}]'::jsonb),
    ('192076c0-4d8f-4217-a193-ecfffb6a5a50'::uuid, 'card_description', 'A small circular embanked enclosure, or "round," common to the Iron Age and post-Roman period. Part of the stone rampart still stands 1.6 metres high.', 'On a ridge above the Lamorna valley, Castallack Round keeps part of a rampart of large stones and slabs. The tithe map of 1840 shows a colonnade of stones leading to an inner enclosure.', 'teaser-card-s022:192076c0-4d8f-4217-a193-ecfffb6a5a50:card_description', 'teaser-card-s022 (teaser-card): teaser card, 185 characters, checked PASS, web-verified VERIFIED', 'da0d0f9bd09c2edd8215e7ef5184c37650024ff98a30410564f741fa049c7745|ac5aa682f2271f643829d5b54d066b7e7cdaca2ac25f8907973b51251d307c95|ac5aa682f2271f643829d5b54d066b7e7cdaca2ac25f8907973b51251d307c95', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-003", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "On a ridge above the Lamorna valley, Castallack Round keeps part of a rampart of large stones and slabs. The tithe map of 1840 shows a colonnade of stones leading to an inner enclosure."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-003 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "the round lies on a ridge above the Lamorna valley [S3]; part of its rampart survives [S4]; the rampart is of large stones and slabs [S4]; the tithe map of 1840 shows a colonnade of stones [S6]; the colonnade led to an inner enclosure [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-009 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Castallack Round is a prehistoric enclosure (a Cornish round) in Cornwall, England [SUPPORTED: https://en.wikipedia.org/wiki/Castallack_Round]; A round is a small circular embanked enclosure [SUPPORTED: https://en.wikipedia.org/wiki/Castallack_Round]; It lies on a ridge above the Lamorna valley [SUPPORTED: https://en.wikipedia.org/wiki/Castallack_Round]; Part of a rampart of large stones and slabs survives [SUPPORTED: https://en.wikipedia.org/wiki/Castallack_Round]; The tithe map of 1840 shows a colonnade of stones leading to an inner enclosure [SUPPORTED: https://en.wikipedia.org/wiki/Castallack_Round]"}]'::jsonb),
    ('19df2778-fb6e-4298-be94-c98d979a5f9a'::uuid, 'card_description', 'The largest Roman town in northern Britain and a provincial capital. Two emperors died here: Septimius Severus in 211 AD and Constantius Chlorus in 306 AD.', 'Above the River Ouse, the Ninth Legion built a fortress in 71 AD. It grew into Eboracum, a cosmopolitan port where two Roman emperors died, Septimius Severus and Constantius Chlorus.', 'teaser-card-s022:19df2778-fb6e-4298-be94-c98d979a5f9a:card_description', 'teaser-card-s022 (teaser-card): teaser card, 182 characters, checked PASS, web-verified VERIFIED', '285e14d64dd32445026cc1b675c36512f0ceb5a85a336e18c7fe031fdb7b9bbb|9e298238bbe60e3fde6c78041d2dd5a94676400e98d06ebc8dfa86005655a61b|9e298238bbe60e3fde6c78041d2dd5a94676400e98d06ebc8dfa86005655a61b', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-004", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Above the River Ouse, the Ninth Legion built a fortress in 71 AD. It grew into Eboracum, a cosmopolitan port where two Roman emperors died, Septimius Severus and Constantius Chlorus."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-004 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "the fortress stood above the River Ouse [S5]; the Ninth Legion built a fortress [S5]; the fortress was built in 71 AD [S5]; the fort grew into the city of Eboracum [S1]; Eboracum was cosmopolitan [S8]; Eboracum was a port [S8]; two Roman emperors died in Eboracum [S4]; the emperors were Septimius Severus and Constantius Chlorus [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-verify-010 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Eboracum was a Roman legionary fortress (castrum), later the city of York (central claim) [SUPPORTED: https://en.wikipedia.org/wiki/Eboracum]; The fortress stood above the River Ouse [SUPPORTED: https://en.wikipedia.org/wiki/Eboracum]; The Ninth Legion built the fortress [SUPPORTED: https://en.wikipedia.org/wiki/Eboracum]; The fortress was built in 71 AD [SUPPORTED: https://en.wikipedia.org/wiki/Eboracum]; The fortress grew into a civil settlement and city (it grew into Eboracum) [SUPPORTED: https://en.wikipedia.org/wiki/Eboracum]; Eboracum was a port [SUPPORTED: https://en.wikipedia.org/wiki/Eboracum]; Eboracum was cosmopolitan [SUPPORTED: https://en.wikipedia.org/wiki/Eboracum]; Two Roman emperors died at Eboracum [SUPPORTED: https://en.wikipedia.org/wiki/Eboracum]; Septimius Severus died at Eboracum [SUPPORTED: https://en.wikipedia.org/wiki/Eboracum]; Constantius Chlorus (Constantius I) died at Eboracum [SUPPORTED: https://en.wikipedia.org/wiki/Eboracum]"}]'::jsonb),
    ('1a2c2dc7-7003-4025-a8ce-f3401a10134f'::uuid, 'card_description', 'A site some consider the burial place of Eve, with an estimated tomb length of 130 m. It was sealed with concrete in 1975 to discourage pilgrimage.', 'In Jeddah lies the Tomb of Eve, which some Muslims consider the burial place of Eve. Writers of the 13th century knew it; in 1928 it was destroyed, and in 1975 sealed with concrete.', 'teaser-card-s022:1a2c2dc7-7003-4025-a8ce-f3401a10134f:card_description', 'teaser-card-s022 (teaser-card): teaser card, 181 characters, checked PASS, web-verified VERIFIED', '3891e493229e87f2be1b42e9c7e3874e3c3c1cf458d67549cfaff7c04c3cfc73|c7072160653a9f57d87dbb17fc418cdf3a2022d38c1a6a2738dde756d6d74da9|c7072160653a9f57d87dbb17fc418cdf3a2022d38c1a6a2738dde756d6d74da9', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-004", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "In Jeddah lies the Tomb of Eve, which some Muslims consider the burial place of Eve. Writers of the 13th century knew it; in 1928 it was destroyed, and in 1975 sealed with concrete."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-004 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "the Tomb of Eve is in Jeddah [S1]; some Muslims consider it the burial place of Eve [S2]; writers of the 13th century knew of it [S6]; it was destroyed in 1928 [S3]; it was sealed with concrete in 1975 [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-verify-010 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "The Tomb of Eve is a tomb/archaeological site in Jeddah (Saudi Arabia) (central claim) [SUPPORTED: https://en.wikipedia.org/wiki/Tomb_of_Eve]; Some Muslims consider it the burial place of Eve [SUPPORTED: https://en.wikipedia.org/wiki/Tomb_of_Eve]; Writers of the 13th century knew it [SUPPORTED: https://en.wikipedia.org/wiki/Tomb_of_Eve]; It was destroyed in 1928 [SUPPORTED: https://en.wikipedia.org/wiki/Tomb_of_Eve]; In 1975 it was sealed with concrete [SUPPORTED: https://en.wikipedia.org/wiki/Tomb_of_Eve]"}]'::jsonb),
    ('1ac1779a-749a-4726-a671-d49a3d1b16e2'::uuid, 'card_description', 'Vescia was an ancient city of the Ausones which was part of the so-called Auruncan Pentapolis and was destroyed by the Romans in 340 BC.', 'Vescia, a city of the Ausones, was destroyed in the Second Samnite War in 314 BC. Two Latin inscriptions that mention it were found in Castelforte and now rest in the Minturno museum.', 'teaser-card-s022:1ac1779a-749a-4726-a671-d49a3d1b16e2:card_description', 'teaser-card-s022 (teaser-card): teaser card, 183 characters, checked PASS, web-verified VERIFIED', 'e752a52dad3c0b5b510f99fbda8042dd9041ac95dca7e3e60da86b86f7a4c1f8|bb0d2b6ad88d52d6ce32026defc37c9a8494bfa7d5a2c4e32f8e8abab51d3c84|bb0d2b6ad88d52d6ce32026defc37c9a8494bfa7d5a2c4e32f8e8abab51d3c84', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-rewrite-v-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Vescia, a city of the Ausones, was destroyed in the Second Samnite War in 314 BC. Two Latin inscriptions that mention it were found in Castelforte and now rest in the Minturno museum."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-v-001 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Vescia was a city of the Ausones [S1]; Vescia was destroyed in the Second Samnite War [W1]; it was destroyed in 314 BC [W1]; two Latin inscriptions that mention Vescia exist [S2]; the inscriptions were found in Castelforte [S2]; the inscriptions are now in the Minturno museum [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify2-001 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Vescia was an ancient city of the Ausones [SUPPORTED: https://en.wikipedia.org/wiki/Vescia]; Vescia was destroyed in the Second Samnite War in 314 BC [SUPPORTED: https://en.wikipedia.org/wiki/Second_Samnite_War]; Vescia''s fall belongs to the Second Samnite War (it had sided with the Samnites after Lautulae) [SUPPORTED, no proving quote: https://en.wikipedia.org/wiki/Aurunci]; Two Latin inscriptions mention Vescia [SUPPORTED: https://en.wikipedia.org/wiki/Vescia]; The inscriptions were found in Castelforte [SUPPORTED: https://en.wikipedia.org/wiki/Vescia]; The inscriptions are now in the Minturno museum [SUPPORTED: https://en.wikipedia.org/wiki/Vescia]"}, {"source": "web fact W1", "url": "https://it.wikipedia.org/wiki/Vescia_(citt%C3%A0)", "quote": "Venne distrutta durante la seconda guerra sannitica nel 314 a.C."}]'::jsonb),
    ('1b48aaf6-bd3f-4ec5-81d3-8e308de6e308'::uuid, 'card_description', 'This 3500–2800 BC dolmen was destroyed in the 17th or 18th century, its stones scattered across fields. Moved 500 meters south and reconstructed in 1977 in its current location near Bergen.', 'Its stones lay scattered on the fields. Excavated in 1977 and rebuilt, the Dohnsen dolmen is a passage grave where the dead lay with jewellery, earthenware jars and everyday implements.', 'teaser-card-s022:1b48aaf6-bd3f-4ec5-81d3-8e308de6e308:card_description', 'teaser-card-s022 (teaser-card): teaser card, 185 characters, checked PASS, web-verified VERIFIED', '3e37bbfa94a18aa3e58e1119ac8e92c79233518b405c71a58101eb942d6c7f44|34d7a5ce921f3f6e7c90d64b8e1da5103aff67a3f9026bd7abcaf3206b8657c1|34d7a5ce921f3f6e7c90d64b8e1da5103aff67a3f9026bd7abcaf3206b8657c1', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-004", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Its stones lay scattered on the fields. Excavated in 1977 and rebuilt, the Dohnsen dolmen is a passage grave where the dead lay with jewellery, earthenware jars and everyday implements."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-004 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "the dolmen''s stones lay scattered on the fields [S3]; it was excavated in 1977 [S2]; it was rebuilt (reconstructed) [S2]; the dolmen is at Dohnsen [S1]; it is a passage grave [S6]; the dead were laid in it with jewellery [S8]; the dead were laid with earthenware jars [S8]; the dead were laid with everyday implements [S8]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-verify-010 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "The Dohnsen-Siddernhausen dolmen is a megalithic tomb (dolmen/Grosssteingrab) between the villages of Dohnsen and Siddernhausen near Bergen, Germany (central claim) [SUPPORTED: https://en.wikipedia.org/wiki/Dohnsen-Siddernhausen_Dolmen]; Its stones lay scattered on the fields [SUPPORTED: https://en.wikipedia.org/wiki/Dohnsen-Siddernhausen_Dolmen]; It was excavated in 1977 [SUPPORTED: https://en.wikipedia.org/wiki/Dohnsen-Siddernhausen_Dolmen]; It was rebuilt (reconstructed) at its present location [SUPPORTED: https://en.wikipedia.org/wiki/Dohnsen-Siddernhausen_Dolmen]; The dolmen is a passage grave [SUPPORTED: https://en.wikipedia.org/wiki/Dohnsen-Siddernhausen_Dolmen]; The dead were buried in it (it was a burial place) [SUPPORTED: https://en.wikipedia.org/wiki/Dohnsen-Siddernhausen_Dolmen]; The dead lay in it with jewellery [SUPPORTED: https://en.wikipedia.org/wiki/Dohnsen-Siddernhausen_Dolmen]; The dead lay in it with earthenware jars [SUPPORTED: https://en.wikipedia.org/wiki/Dohnsen-Siddernhausen_Dolmen]; The dead lay in it with everyday implements [SUPPORTED: https://en.wikipedia.org/wiki/Dohnsen-Siddernhausen_Dolmen]"}]'::jsonb),
    ('1b51e95a-6d3b-4cd1-b3ed-da5f4ab8a501'::uuid, 'card_description', 'The earliest mention of the Wrekin occurs in a charter of 855, as entered in a late 11th-century Worcester cartulary, spelled Wreocensetun.', 'Rising above the Shropshire Plain to 407 metres, the Wrekin first appears in a charter of 855, while early Welsh poems name a place Dinlle Wrecon: the fort of Wrecon.', 'teaser-card-s022:1b51e95a-6d3b-4cd1-b3ed-da5f4ab8a501:card_description', 'teaser-card-s022 (teaser-card): teaser card, 166 characters, checked PASS, web-verified VERIFIED', '47a0e3b7f3521837f6b0477bfeedeb639e95b3d0afe6e522232491ac2b2a3181|7a2294d4c233f2c55c4735bea246f5892b1dd57c19fa082dc6fb7e250ab0305a|7a2294d4c233f2c55c4735bea246f5892b1dd57c19fa082dc6fb7e250ab0305a', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-004", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Rising above the Shropshire Plain to 407 metres, the Wrekin first appears in a charter of 855, while early Welsh poems name a place Dinlle Wrecon: the fort of Wrecon."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-004 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "the Wrekin rises above the Shropshire Plain [S3]; it rises to 407 metres [S3]; the Wrekin first appears (earliest mention) in a charter [S4]; the charter dates from 855 [S4]; early Welsh poems name a place Dinlle Wrecon [S5]; Dinlle Wrecon means the fort of Wrecon [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-verify-010 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "The Wrekin is a hill in Shropshire, England, with an Iron Age hill fort on its summit (central claim) [SUPPORTED: https://en.wikipedia.org/wiki/The_Wrekin]; The Wrekin carries an Iron Age hill fort on its summit [SUPPORTED: https://en.wikipedia.org/wiki/The_Wrekin]; It rises above the Shropshire Plain [SUPPORTED: https://en.wikipedia.org/wiki/The_Wrekin]; Its height is 407 metres [SUPPORTED: https://en.wikipedia.org/wiki/The_Wrekin]; The Wrekin first appears (earliest mention) in a charter of 855 [SUPPORTED: https://en.wikipedia.org/wiki/The_Wrekin]; Early Welsh poems name a place Dinlle Wrecon [SUPPORTED: https://en.wikipedia.org/wiki/The_Wrekin]; Dinlle Wrecon means the fort of Wrecon [SUPPORTED: https://en.wikipedia.org/wiki/The_Wrekin]"}]'::jsonb),
    ('1c3a15dd-4add-4c8b-84ef-3e638ce46b1b'::uuid, 'card_description', 'A New Kingdom temple to Khonsu at Karnak, built by Ramesses III. Ptolemy III later added a grand gateway—all that survives of his contribution.', 'Where the avenue of sphinxes ends at Karnak, the Temple of Khonsu stands almost complete, built by Ramesses III, its reused blocks showing unmatched and inverted decorations.', 'teaser-card-s022:1c3a15dd-4add-4c8b-84ef-3e638ce46b1b:card_description', 'teaser-card-s022 (teaser-card): teaser card, 174 characters, checked PASS, web-verified VERIFIED', 'da2936b04c0420a90a75cfedbd8a0708e74c005cb4d5a9583433b2c5ad8379d6|e41f2524e66b8d7013f138d59bb3ef649765fe3d1b919e6bbd704585435a75c5|e41f2524e66b8d7013f138d59bb3ef649765fe3d1b919e6bbd704585435a75c5', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-004", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Where the avenue of sphinxes ends at Karnak, the Temple of Khonsu stands almost complete, built by Ramesses III, its reused blocks showing unmatched and inverted decorations."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-004 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "the temple lies where the avenue of sphinxes ends [S4]; the temple is at Karnak [S2]; the temple is almost complete [S3]; it was built by Ramesses III [S3]; it has reused blocks [S7]; the blocks show unmatched and inverted decorations [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-011 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "The Temple of Khonsu is a temple (central claim: the kind of place) [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Khonsu]; It is at Karnak (Egypt) [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Khonsu]; The avenue of sphinxes ends at the temple''s gateway [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Khonsu]; The temple stands almost complete [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Khonsu]; It was built by Ramesses III [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Khonsu]; Reused blocks with unmatched and inverted decorations can be seen in it [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Khonsu]"}]'::jsonb),
    ('1c4dc9a8-49e5-451f-9b50-af0f1d7ed3f6'::uuid, 'card_description', 'A 16th-century BC royal cemetery with six shaft graves yielding gold death masks, weapons, and jewelry. Originally outside the citadel walls, later enclosed within them.', 'South of the Lion Gate lies Grave Circle A, a royal cemetery of the 16th century BC: six shaft graves, nineteen bodies, gold death masks, full sets of weapons, gold and silver cups.', 'teaser-card-s022:1c4dc9a8-49e5-451f-9b50-af0f1d7ed3f6:card_description', 'teaser-card-s022 (teaser-card): teaser card, 181 characters, checked PASS, web-verified VERIFIED', '065e18bd07b34bde4e763934759687b82039d65f42fa3c12e81d9ce475f7cacd|af83e024e4ce1d3eb465950d26adf6f846f6853bb4eff0a7560d66d9702de8ad|af83e024e4ce1d3eb465950d26adf6f846f6853bb4eff0a7560d66d9702de8ad', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-004", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "South of the Lion Gate lies Grave Circle A, a royal cemetery of the 16th century BC: six shaft graves, nineteen bodies, gold death masks, full sets of weapons, gold and silver cups."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-004 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Grave Circle A lies south of the Lion Gate [S1]; it is a royal cemetery [S1]; it dates to the 16th century BC [S1]; it contains six shaft graves [S3]; nineteen bodies were found in it [S6]; gold death masks were found [S4]; full sets of weapons were found [S4]; gold and silver cups were found [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-011 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Grave Circle A is a cemetery (burial complex) at Mycenae (central claim: the kind of place) [SUPPORTED: https://en.wikipedia.org/wiki/Grave_Circle_A,_Mycenae]; It lies south of the Lion Gate [SUPPORTED: https://en.wikipedia.org/wiki/Grave_Circle_A,_Mycenae]; It is a royal cemetery [SUPPORTED: https://en.wikipedia.org/wiki/Grave_Circle_A,_Mycenae]; The cemetery dates to the 16th century BC [SUPPORTED: https://en.wikipedia.org/wiki/Grave_Circle_A,_Mycenae]; It contains six shaft graves [SUPPORTED: https://en.wikipedia.org/wiki/Grave_Circle_A,_Mycenae]; Nineteen bodies were buried there [SUPPORTED: https://en.wikipedia.org/wiki/Grave_Circle_A,_Mycenae]; Gold death masks were found there [SUPPORTED: https://en.wikipedia.org/wiki/Grave_Circle_A,_Mycenae]; Full sets of weapons were found there [SUPPORTED: https://en.wikipedia.org/wiki/Grave_Circle_A,_Mycenae]; Gold and silver cups were found there [SUPPORTED: https://en.wikipedia.org/wiki/Grave_Circle_A,_Mycenae]"}]'::jsonb),
    ('1d3438fb-1fb7-47e7-bb93-486169e4f3f4'::uuid, 'card_description', 'An Inca-era site from 1438-1530 AD. Structures like these formed the administrative backbone of an empire that governed 12 million people without a written language.', 'North of Cusco, near Qenko, lies Amaru Marka Wasi, also called Templo de la Luna, possibly once the residence of Amaru Yupanqui, eldest son of Pachakutiq Inka Yupanki.', 'teaser-card-s022:1d3438fb-1fb7-47e7-bb93-486169e4f3f4:card_description', 'teaser-card-s022 (teaser-card): teaser card, 167 characters, checked PASS, web-verified VERIFIED', '3ce8bd4466a2b11abc597f33e50be435ec68c16f130c625208d3b3bc1f4a9223|b6816b1b61c64c1adb2a394bdffa19eef36d2fb10904de98663fa610642bef9b|b6816b1b61c64c1adb2a394bdffa19eef36d2fb10904de98663fa610642bef9b', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-004", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "North of Cusco, near Qenko, lies Amaru Marka Wasi, also called Templo de la Luna, possibly once the residence of Amaru Yupanqui, eldest son of Pachakutiq Inka Yupanki."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-004 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Amaru Marka Wasi lies north of Cusco [S2]; it lies near Qenko [S3]; it is also called Templo de la Luna [S1]; it was possibly once the residence of Amaru Yupanqui [S4]; Amaru Yupanqui was the eldest son of Pachakutiq Inka Yupanki [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-011 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Amaru Marka Wasi is an archaeological site in Peru (central claim: the kind of place) [SUPPORTED: https://en.wikipedia.org/wiki/Amaru_Marka_Wasi]; It is also called Templo de la Luna [SUPPORTED: https://en.wikipedia.org/wiki/Amaru_Marka_Wasi]; It lies north of Cusco [SUPPORTED: https://en.wikipedia.org/wiki/Amaru_Marka_Wasi]; It lies near Qenko [SUPPORTED: https://en.wikipedia.org/wiki/Amaru_Marka_Wasi]; It was possibly once the residence of Amaru Yupanqui [SUPPORTED: https://en.wikipedia.org/wiki/Amaru_Marka_Wasi]; Amaru Yupanqui was the eldest son of Pachakutiq Inka Yupanki [SUPPORTED: https://en.wikipedia.org/wiki/Amaru_Marka_Wasi]"}]'::jsonb),
    ('1db67c2f-5523-4e2c-a953-2824a7cb25ff'::uuid, 'card_description', 'Timber trackway from 2900–2500 BC, found in 2004 in a raised peat bog in the Humberhead Levels. Among the oldest ancient timber trackways known, preserved by centuries of waterlogged peat.', 'In October 2004 a local man walking the moors found worked wooden poles: the Hatfield Neolithic Trackway, one of the oldest known timber trackways in England, dating to around 2900–2500 BC.', 'teaser-card-s022:1db67c2f-5523-4e2c-a953-2824a7cb25ff:card_description', 'teaser-card-s022 (teaser-card): teaser card, 189 characters, checked PASS, web-verified VERIFIED', 'd30a65f207c2481f7c841eb337608e195e2bc987dd7aa5c0e678265dc7faa49a|89d0feb205eab5ecfd9559a256d89341f39de45dfd0b1cd7334238fa7cd5efd2|89d0feb205eab5ecfd9559a256d89341f39de45dfd0b1cd7334238fa7cd5efd2', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-004", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "In October 2004 a local man walking the moors found worked wooden poles: the Hatfield Neolithic Trackway, one of the oldest known timber trackways in England, dating to around 2900–2500 BC."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-004 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "the find was made in October 2004 [S4]; a local man found it [S4]; he was walking across the moors (the site on Hatfield and Thorne Moors) [S2, S4]; he found worked wooden poles [S4]; the find was the Hatfield Neolithic Trackway [S1, S4]; it is one of the oldest known timber trackways in England [S1]; it dates to around 2900-2500 BC [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-011 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "The Hatfield Neolithic Trackway is a timber trackway (central claim: the kind of place) [SUPPORTED: https://en.wikipedia.org/wiki/Hatfield_Neolithic_Trackway]; It is in England [SUPPORTED: https://en.wikipedia.org/wiki/Hatfield_Neolithic_Trackway]; It is one of the oldest known timber trackways in England [SUPPORTED: https://en.wikipedia.org/wiki/Hatfield_Neolithic_Trackway]; It lies on the moors (Hatfield and Thorne Moors) [SUPPORTED: https://en.wikipedia.org/wiki/Hatfield_Neolithic_Trackway]; It was found in October 2004 [SUPPORTED: https://en.wikipedia.org/wiki/Hatfield_Neolithic_Trackway]; What was found were worked wooden poles [SUPPORTED: https://en.wikipedia.org/wiki/Hatfield_Neolithic_Trackway]; It was found by a local man [SUPPORTED: https://en.wikipedia.org/wiki/Hatfield_Neolithic_Trackway]; The finder was walking at the site when he found it [SUPPORTED: https://en.wikipedia.org/wiki/Hatfield_Neolithic_Trackway]; The trackway dates to around 2900-2500 BC [SUPPORTED: https://en.wikipedia.org/wiki/Hatfield_Neolithic_Trackway]"}]'::jsonb),
    ('1de7069f-5fdd-48f3-b48c-45b926248224'::uuid, 'card_description', 'When the site was first excavated in the 19th century it was reported that parts of the villa were very well preserved.', 'Cut into a hillside on four heavily buttressed terraces, Great Witcombe Roman Villa defied its uneven ground: a large dwelling near Gloucester with at least one substantial bath house.', 'teaser-card-s022:1de7069f-5fdd-48f3-b48c-45b926248224:card_description', 'teaser-card-s022 (teaser-card): teaser card, 184 characters, checked PASS, web-verified VERIFIED', 'c05a1330507f939269acd1514e37027eaf406435a2b95be0ee9e6b5dca7b6a19|f1249ab596764726f7ee10383cb6101f987bf7551942dfb57bb1acf8d42e2169|f1249ab596764726f7ee10383cb6101f987bf7551942dfb57bb1acf8d42e2169', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-004", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Cut into a hillside on four heavily buttressed terraces, Great Witcombe Roman Villa defied its uneven ground: a large dwelling near Gloucester with at least one substantial bath house."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-004 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "the villa is cut into a hillside [S2, S5]; it is built on four terraces [S5]; the terraces are heavily buttressed [S5]; the villa coped with (defied) its uneven, difficult ground [S4, S5]; it is a large dwelling [S4]; it is near Gloucester [S2]; it had at least one substantial bath house [S7]; it is a Roman villa [S1]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-011 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Great Witcombe Roman Villa is a Roman villa (central claim: the kind of place) [SUPPORTED: https://en.wikipedia.org/wiki/Great_Witcombe_Roman_Villa]; It is near Gloucester [SUPPORTED: https://en.wikipedia.org/wiki/Great_Witcombe_Roman_Villa]; It is cut into a hillside [SUPPORTED: https://en.wikipedia.org/wiki/Great_Witcombe_Roman_Villa]; It stands on four terraces [SUPPORTED: https://en.wikipedia.org/wiki/Great_Witcombe_Roman_Villa]; The terraces are heavily buttressed [SUPPORTED: https://en.wikipedia.org/wiki/Great_Witcombe_Roman_Villa]; The ground was uneven, seemingly unsuitable for the villa, yet it was built there [SUPPORTED: https://en.wikipedia.org/wiki/Great_Witcombe_Roman_Villa]; It was a large dwelling [SUPPORTED: https://en.wikipedia.org/wiki/Great_Witcombe_Roman_Villa]; It had at least one bath house [SUPPORTED: https://en.wikipedia.org/wiki/Great_Witcombe_Roman_Villa]; The bath house was substantial [SUPPORTED: https://en.wikipedia.org/wiki/Great_Witcombe_Roman_Villa]"}]'::jsonb),
    ('1e492f5e-7913-49a5-8d9c-3f9ee581361a'::uuid, 'card_description', 'Perched at 185 meters on Woodbury Common, this Devon fort commands views of the Exe Estuary from a ridgeline 12.9 km southeast of Exeter. Earthwork defenses remain visible across the summit.', 'On a high point of Woodbury Common, approximately 185 metres above sea level, the Iron Age hillfort of Woodbury Castle commands views up and down the Exe Estuary and across Lyme Bay.', 'teaser-card-s022:1e492f5e-7913-49a5-8d9c-3f9ee581361a:card_description', 'teaser-card-s022 (teaser-card): teaser card, 182 characters, checked PASS, web-verified VERIFIED', '7893df84fb8f6fd65e001d0fd9cb8c0df3bb2d73d655192c34723c50dad24b8f|bd736c01ef2c95e5bcffc28070526c4bf68fb3c7265bd11b64cc58ea7612c961|bd736c01ef2c95e5bcffc28070526c4bf68fb3c7265bd11b64cc58ea7612c961', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-004", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "On a high point of Woodbury Common, approximately 185 metres above sea level, the Iron Age hillfort of Woodbury Castle commands views up and down the Exe Estuary and across Lyme Bay."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-004 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Woodbury Castle is on a high point of Woodbury Common [S2]; it is at approximately 185 metres above sea level [S2]; it is an Iron Age hillfort [S1]; it commands views up and down the Exe Estuary [S2]; it commands views across Lyme Bay [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-012 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Woodbury Castle is an Iron Age hillfort (the central claim: a hillfort, in Devon, England) [SUPPORTED: https://en.wikipedia.org/wiki/Woodbury_Castle]; It stands on a high point of Woodbury Common [SUPPORTED: https://en.wikipedia.org/wiki/Woodbury_Castle]; It lies approximately 185 metres above sea level [SUPPORTED: https://en.wikipedia.org/wiki/Woodbury_Castle]; It commands views up and down the Exe Estuary [SUPPORTED: https://en.wikipedia.org/wiki/Woodbury_Castle]; It commands views across Lyme Bay [SUPPORTED: https://en.wikipedia.org/wiki/Woodbury_Castle]"}]'::jsonb),
    ('1e9f3df5-ebe4-465a-8b98-28772e417358'::uuid, 'card_description', NULL, 'Captured by the Romans in 335 BC, Cales became a colony of 2,500 citizens on the Via Latina, grown prosperous on fertile land and black glazed pottery exported even to Etruria.', 'teaser-card-s022:1e9f3df5-ebe4-465a-8b98-28772e417358:card_description', 'teaser-card-s022 (teaser-card): teaser card, 176 characters, checked PASS, web-verified VERIFIED', '8257429e1023ca42ab798ea2c885f4372cfe3511509b3f6a8ddfb3dbb45f2ba1|4c81ee2d4f9d6924d4aaecf4784adf37f54905dd240129c4209d3abc00ec03c6|4c81ee2d4f9d6924d4aaecf4784adf37f54905dd240129c4209d3abc00ec03c6', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-004", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Captured by the Romans in 335 BC, Cales became a colony of 2,500 citizens on the Via Latina, grown prosperous on fertile land and black glazed pottery exported even to Etruria."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-004 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Cales was captured by the Romans [S2]; the capture was in 335 BC [S2]; Cales became a colony [S2]; the colony had 2,500 citizens [S2]; Cales lay on the Via Latina [S1]; Cales grew prosperous [S7]; its prosperity came from fertile land [S7]; its prosperity came from black glazed pottery [S7]; the pottery was exported even to Etruria [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-012 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Cales was an ancient city (in Campania, southern Italy) - the central claim: a city/colony site in Italy [SUPPORTED: https://en.wikipedia.org/wiki/Cales]; Cales lay on the Via Latina [SUPPORTED: https://en.wikipedia.org/wiki/Cales]; The Romans captured Cales in 335 BC [SUPPORTED: https://en.wikipedia.org/wiki/Cales]; Cales became a Roman colony [SUPPORTED: https://en.wikipedia.org/wiki/Cales]; The colony had 2,500 citizens [SUPPORTED: https://en.wikipedia.org/wiki/Cales]; Cales became prosperous [SUPPORTED: https://en.wikipedia.org/wiki/Cales]; Cales grew prosperous on its fertile land [SUPPORTED: https://en.wikipedia.org/wiki/Cales]; Cales manufactured black glazed pottery that made it prosperous [SUPPORTED: https://en.wikipedia.org/wiki/Cales]; The black glazed pottery was exported even to Etruria [SUPPORTED: https://en.wikipedia.org/wiki/Cales]"}]'::jsonb),
    ('1f5cb852-dcc8-440d-9931-c5968dff6cc0'::uuid, 'card_description', 'A 19-metre Neolithic mound from around 2400 BC, second in height only to nearby Silbury Hill. It was later used as a castle motte, hiding its prehistoric origins for centuries.', 'Standing 19 metres tall, Marlborough Mound is second in height only to nearby Silbury Hill. It dates from around 2400 BC, the Neolithic period, and its original purpose is unknown.', 'teaser-card-s022:1f5cb852-dcc8-440d-9931-c5968dff6cc0:card_description', 'teaser-card-s022 (teaser-card): teaser card, 180 characters, checked PASS, web-verified VERIFIED', '23c50e61fa3f6c0336a564710a37773e47c17463df4104113b244fc6c0058850|76e06e1b8951c94f4c0cd2972680b162e6f05fbc68340c1848c51cfa3ca33e8a|76e06e1b8951c94f4c0cd2972680b162e6f05fbc68340c1848c51cfa3ca33e8a', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-004", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Standing 19 metres tall, Marlborough Mound is second in height only to nearby Silbury Hill. It dates from around 2400 BC, the Neolithic period, and its original purpose is unknown."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-004 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Marlborough Mound stands 19 metres tall [S2]; it is second in height only to Silbury Hill (among such monuments) [S2]; Silbury Hill is nearby [S2]; it dates from around 2400 BC [S5]; it belongs to the Neolithic period [S1, S5]; its original purpose is unknown [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-012 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Marlborough Mound is a Neolithic mound/monument in Marlborough, Wiltshire, England (the central claim: a monumental earth mound) [SUPPORTED: https://en.wikipedia.org/wiki/Marlborough_Mound]; Marlborough Mound stands 19 metres tall [SUPPORTED: https://en.wikipedia.org/wiki/Marlborough_Mound]; It is second in height only to the nearby Silbury Hill [SUPPORTED: https://en.wikipedia.org/wiki/Marlborough_Mound]; It dates from around 2400 BC [SUPPORTED: https://en.wikipedia.org/wiki/Marlborough_Mound]; It dates from the Neolithic period [SUPPORTED: https://en.wikipedia.org/wiki/Marlborough_Mound]; Its original purpose is unknown [SUPPORTED: https://en.wikipedia.org/wiki/Marlborough_Mound]"}]'::jsonb),
    ('203fbf02-196b-4853-8504-d35a34085345'::uuid, 'card_description', 'A cylindrical drum topped by a cone, built for a Numidian king between 300 and 200 BC near Batna. This mausoleum near Aurasius Mons is among the oldest royal funerary monuments in North Africa.', 'Near Batna rises Madghacen, a royal mausoleum of the Berber Numidian Kingdom: a large tumulus of well-cut ashlar with sixty Doric columns, an Egyptian-style cornice and a stepped cone.', 'teaser-card-s022:203fbf02-196b-4853-8504-d35a34085345:card_description', 'teaser-card-s022 (teaser-card): teaser card, 184 characters, checked PASS, web-verified VERIFIED', 'fe2e2902fc27d716b7fdb1b075bac9defe88da4c7ca419f34bc4d58b75e46897|4c308c748844c4d6855976023a6daf236e0d1004f39edd47208f47af95a2e9c7|4c308c748844c4d6855976023a6daf236e0d1004f39edd47208f47af95a2e9c7', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-004", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Near Batna rises Madghacen, a royal mausoleum of the Berber Numidian Kingdom: a large tumulus of well-cut ashlar with sixty Doric columns, an Egyptian-style cornice and a stepped cone."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-004 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Madghacen is near Batna [S1]; it is a royal mausoleum [S2]; it was built by the Berber Numidian Kingdom [S2]; it is a large tumulus [S6]; it is built of well-cut ashlar [S6]; it has sixty Doric columns [S6]; it has an Egyptian-style cornice [S6]; its upper part is a stepped cone [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-012 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Madghacen (Medracen) is a royal mausoleum / funerary monument (the central claim: a royal tomb) [SUPPORTED: https://en.wikipedia.org/wiki/Medracen]; It is located near Batna (Algeria) [SUPPORTED: https://en.wikipedia.org/wiki/Medracen]; It is a mausoleum of the Berber Numidian Kingdom [SUPPORTED: https://en.wikipedia.org/wiki/Medracen]; It is a large tumulus [SUPPORTED: https://en.wikipedia.org/wiki/Medracen]; It is built of well-cut ashlar [SUPPORTED: https://en.wikipedia.org/wiki/Medracen]; It has sixty Doric columns [SUPPORTED: https://en.wikipedia.org/wiki/Medracen]; It has an Egyptian-style cornice [SUPPORTED: https://en.wikipedia.org/wiki/Medracen]; Its upper part is a stepped cone [SUPPORTED: https://en.wikipedia.org/wiki/Medracen]"}]'::jsonb),
    ('2121c097-4bc4-4763-9534-ba57efa1437d'::uuid, 'card_description', 'A 350,000-year-old site with Acheulean stone tools found alongside elephant and other megafauna remains. Whether early humans hunted or scavenged here is still debated.', 'At Torralba and Ambrona, levels at least about 350,000 years old hold the remains of nearly fifty elephants per site, and traces of humans who hunted or, more likely, scavenged carrion.', 'teaser-card-s022:2121c097-4bc4-4763-9534-ba57efa1437d:card_description', 'teaser-card-s022 (teaser-card): teaser card, 185 characters, checked PASS, web-verified VERIFIED', '64fff0f20fc620b1a7e9ba9688255522ba2bf5e27b099786e0f2e3fb1d9decaf|ed1e9c03cdc3a020a29cd4ea7c98f3dc1a252753444e010c557df576907e00b1|ed1e9c03cdc3a020a29cd4ea7c98f3dc1a252753444e010c557df576907e00b1', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-004", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "At Torralba and Ambrona, levels at least about 350,000 years old hold the remains of nearly fifty elephants per site, and traces of humans who hunted or, more likely, scavenged carrion."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-004 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "the site is Torralba and Ambrona [S1]; its levels are at least about 350,000 years old [S1]; the levels hold remains of nearly fifty elephants per site [S3]; there are traces of humans at the sites [S4]; the humans hunted or, more likely, scavenged carrion [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-012 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Torralba and Ambrona are two paleontological and archaeological sites (fossil-bearing levels with human traces) in Spain - the central claim [SUPPORTED: https://en.wikipedia.org/wiki/Torralba_and_Ambrona]; The levels are at least about 350,000 years old [SUPPORTED: https://en.wikipedia.org/wiki/Torralba_and_Ambrona]; The levels hold remains of elephants [SUPPORTED: https://en.wikipedia.org/wiki/Torralba_and_Ambrona]; The remains amount to nearly fifty elephants at each of the two sites [SUPPORTED: https://en.wikipedia.org/wiki/Torralba_and_Ambrona]; There are traces of humans at the sites [SUPPORTED: https://en.wikipedia.org/wiki/Torralba_and_Ambrona]; The humans may have hunted the elephants (hunting station) [SUPPORTED: https://en.wikipedia.org/wiki/Torralba_and_Ambrona]; More likely the humans scavenged carrion [SUPPORTED: https://en.wikipedia.org/wiki/Torralba_and_Ambrona]"}]'::jsonb),
    ('2141f6e0-ab5c-4108-9f2e-8110f1585f43'::uuid, 'card_description', 'A 2nd-century AD Iron Age fortification encircling 1,700 square meters on a hilltop. One side drops 70 meters into a ravine called the Devil''s Valley.', 'Above the Devil''s Valley, the Troldborg Ring guards a spring behind its circular rampart, likely a refuge in violent times. Its ash tells of massive fires whose source is unclear.', 'teaser-card-s022:2141f6e0-ab5c-4108-9f2e-8110f1585f43:card_description', 'teaser-card-s022 (teaser-card): teaser card, 179 characters, checked PASS, web-verified VERIFIED', 'ed211ab9985194ca51fb34b65c4dfd7e842dc6781c439ac03de3163c131ed7ba|e7e5299a5cd84edddca3d4c4301747952be7856ee1b3cdc07cadf0e7e21d8aca|e7e5299a5cd84edddca3d4c4301747952be7856ee1b3cdc07cadf0e7e21d8aca', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-005", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Above the Devil''s Valley, the Troldborg Ring guards a spring behind its circular rampart, likely a refuge in violent times. Its ash tells of massive fires whose source is unclear."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-005 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "the site lies above the Devil''s Valley [S2, S3, S5]; the Troldborg Ring is at a spring [S2]; it has a circular rampart [S4]; it was likely a refuge in violent times [S7]; ash at the site points to massive fires [S8]; the source of those fires is unclear [S8]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-013 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "The Troldborg Ring is a fortification (a ring fort) in Denmark, above the Devil''s Valley [SUPPORTED: https://en.wikipedia.org/wiki/Troldborg_Ring]; It lies above (overlooking) the Devil''s Valley, a steep ravine [SUPPORTED: https://en.wikipedia.org/wiki/Troldborg_Ring]; It guards a spring: the site is located at a natural spring on a high point [SUPPORTED: https://en.wikipedia.org/wiki/Troldborg_Ring]; The spring/site lies behind a circular rampart [SUPPORTED: https://en.wikipedia.org/wiki/Troldborg_Ring]; It was likely a refuge in violent times [SUPPORTED: https://en.wikipedia.org/wiki/Troldborg_Ring]; Ash from massive fires was found at the site [SUPPORTED: https://en.wikipedia.org/wiki/Troldborg_Ring]; The source of the fires is unclear [SUPPORTED: https://en.wikipedia.org/wiki/Troldborg_Ring]"}]'::jsonb),
    ('21b2278e-c3f2-4723-ae40-fa8a6161e3fb'::uuid, 'card_description', 'Stonehenge was constructed in several phases, beginning about 3100 BC and continuing until about 1600 BC.', 'Amid several hundred burial mounds, Stonehenge rings bluestones and trilithons with sarsens of around 25 tons. Its great sarsen circle was placed between 2600 BC and 2400 BC.', 'teaser-card-s022:21b2278e-c3f2-4723-ae40-fa8a6161e3fb:card_description', 'teaser-card-s022 (teaser-card): teaser card, 174 characters, checked PASS, web-verified VERIFIED', '89d0956a6bf89afd0fb2f267c740f950aa438a1c03b372792b618dc505852314|61f6f54efce8c43a43b58f8e5371d4f35f97f9fb229f6392374e4d51dec7dc36|61f6f54efce8c43a43b58f8e5371d4f35f97f9fb229f6392374e4d51dec7dc36', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-005", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Amid several hundred burial mounds, Stonehenge rings bluestones and trilithons with sarsens of around 25 tons. Its great sarsen circle was placed between 2600 BC and 2400 BC."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-005 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Stonehenge stands amid several hundred burial mounds [S6]; an outer ring of sarsens encloses the bluestones and the trilithons [S2, S3, S4]; the sarsens weigh around 25 tons [S2]; the great sarsen circle was placed between 2600 BC and 2400 BC [S8]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-013 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Stonehenge is a prehistoric megalithic monument (a ring of standing stones) in England [SUPPORTED: https://en.wikipedia.org/wiki/Stonehenge]; It lies amid several hundred burial mounds [SUPPORTED: https://en.wikipedia.org/wiki/Stonehenge]; An outer ring of sarsens encircles the monument [SUPPORTED: https://en.wikipedia.org/wiki/Stonehenge]; Inside the sarsen ring is a ring of bluestones [SUPPORTED: https://en.wikipedia.org/wiki/Stonehenge]; It has trilithons inside the circle [SUPPORTED: https://en.wikipedia.org/wiki/Stonehenge]; The sarsens weigh around 25 tons [SUPPORTED: https://en.wikipedia.org/wiki/Stonehenge]; The great sarsen circle was placed between 2600 BC and 2400 BC [SUPPORTED: https://en.wikipedia.org/wiki/Stonehenge]"}]'::jsonb),
    ('21f76b39-07bd-40cc-8506-116019eac196'::uuid, 'card_description', 'A 2nd-century BC mausoleum standing 21 metres tall, divided into three tiers atop a five-step pedestal. Only three examples of this Numidian royal architectural form survive anywhere.', 'The Libyco-Punic Mausoleum of Dougga rises 21 m over a five-step pedestal, from false openings to Ionic columns to a pyramid: royal architecture of Numidia from the second century BC.', 'teaser-card-s022:21f76b39-07bd-40cc-8506-116019eac196:card_description', 'teaser-card-s022 (teaser-card): teaser card, 183 characters, checked PASS, web-verified VERIFIED', 'fcf062cfcda73c6ede629feee60f5514f83b5ccdefff300ca679067fed7f7d26|4065f2392abb90f7cbbc95db281482e499f97937d5d108d3f92c4458f7b81cb0|4065f2392abb90f7cbbc95db281482e499f97937d5d108d3f92c4458f7b81cb0', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-005", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "The Libyco-Punic Mausoleum of Dougga rises 21 m over a five-step pedestal, from false openings to Ionic columns to a pyramid: royal architecture of Numidia from the second century BC."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-005 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "the mausoleum is 21 m high [S3]; it stands on a five-step pedestal [S3]; it has false openings [S5]; it has Ionic columns [S7]; it is capped by a pyramid [S8]; the levels rise from the false openings to the Ionic columns to the pyramid [S4, S5, S6, S7, S8]; it is royal architecture of Numidia [S2]; it dates to the second century BC [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-013 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "The Libyco-Punic Mausoleum is an ancient mausoleum (tomb) at Dougga, Tunisia [SUPPORTED: https://en.wikipedia.org/wiki/Libyco-Punic_Mausoleum_of_Dougga]; It is 21 m high [SUPPORTED: https://en.wikipedia.org/wiki/Libyco-Punic_Mausoleum_of_Dougga]; It rises over a five-step pedestal [SUPPORTED: https://en.wikipedia.org/wiki/Libyco-Punic_Mausoleum_of_Dougga]; The lowest level (podium) has false openings [SUPPORTED: https://en.wikipedia.org/wiki/Libyco-Punic_Mausoleum_of_Dougga]; The second level has Ionic columns [SUPPORTED: https://en.wikipedia.org/wiki/Libyco-Punic_Mausoleum_of_Dougga]; The top of the mausoleum is a pyramid [SUPPORTED: https://en.wikipedia.org/wiki/Libyco-Punic_Mausoleum_of_Dougga]; It is royal architecture of Numidia [SUPPORTED: https://en.wikipedia.org/wiki/Libyco-Punic_Mausoleum_of_Dougga]; It dates to the second century BC [SUPPORTED: https://en.wikipedia.org/wiki/Libyco-Punic_Mausoleum_of_Dougga]"}]'::jsonb),
    ('22a7c5e7-a5dd-46b3-a168-ab73f7cf77d4'::uuid, 'card_description', 'Chama is a small Late-Classic Maya highland site some fifty kilometers north-west of San Pedro Carchá.', 'In the Chixoy River valley lies Chama, a small Maya highland site whose vases wear black-and-white chevron bands and often show humanized animals, deities and mythological scenes.', 'teaser-card-s022:22a7c5e7-a5dd-46b3-a168-ab73f7cf77d4:card_description', 'teaser-card-s022 (teaser-card): teaser card, 179 characters, checked PASS, web-verified VERIFIED', 'c93b74f2ad8027072f8319c545b63e92edc164f61478b74ebad0e218f4bba991|1d97673315a24d2ec19322b67cc0c5c3e637e3b0fcda01aebd1f13666491cd28|1d97673315a24d2ec19322b67cc0c5c3e637e3b0fcda01aebd1f13666491cd28', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-005", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "In the Chixoy River valley lies Chama, a small Maya highland site whose vases wear black-and-white chevron bands and often show humanized animals, deities and mythological scenes."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-005 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Chama lies in the Chixoy River valley [S1]; Chama is a small Maya highland site [S1]; its vases carry black-and-white chevron bands [S4, S5]; its vases often show humanized animals, deities and mythological scenes [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-013 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Chama is a small Maya highland site in Guatemala [SUPPORTED: https://en.wikipedia.org/wiki/Chama_(Maya_site)]; It lies in the Chixoy River valley [SUPPORTED: https://en.wikipedia.org/wiki/Chama_(Maya_site)]; Its vases have black-and-white chevron bands [SUPPORTED: https://en.wikipedia.org/wiki/Chama_(Maya_site)]; The vases often show humanized animals, deities and mythological scenes [SUPPORTED: https://en.wikipedia.org/wiki/Chama_(Maya_site)]"}]'::jsonb),
    ('23da7867-1a59-4764-959a-ac94d81ef769'::uuid, 'card_description', 'Set on a 15-metre hill near Bagenkop harbour and dating to 3300–3200 BC, this Funnelbeaker passage grave has a chamber and a separate lateral passageway — a form more common in Germany.', 'On a hill on Langeland, the Hulbjerg Passage Grave hid flint daggers, amber beads and the bones of 36 adults and 17 children in a separate section of its stone chamber.', 'teaser-card-s022:23da7867-1a59-4764-959a-ac94d81ef769:card_description', 'teaser-card-s022 (teaser-card): teaser card, 168 characters, checked PASS, web-verified VERIFIED', '1684ac7ae3088a42e805397ea48cc474865c975dbf2a51bc4c317a1b66c0f6ab|4a05d86c697908b923ea12d850e929c5108ff45f300581eafa23d2bc98c46f6f|4a05d86c697908b923ea12d850e929c5108ff45f300581eafa23d2bc98c46f6f', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-005", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "On a hill on Langeland, the Hulbjerg Passage Grave hid flint daggers, amber beads and the bones of 36 adults and 17 children in a separate section of its stone chamber."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-005 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "the grave is on a hill [S1]; it is on Langeland [S1]; its chamber is built of stone [S5]; the chamber has a separate section [S6, S8]; flint daggers were found in that section [S8]; amber beads were found in that section [S8]; bones of 36 adults and 17 children were found in that section [S8]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-013 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "The Hulbjerg Passage Grave is a passage grave on the Danish island of Langeland [SUPPORTED: https://en.wikipedia.org/wiki/Hulbjerg_Passage_Grave]; It stands on a hill [SUPPORTED: https://en.wikipedia.org/wiki/Hulbjerg_Passage_Grave]; It has a stone chamber [SUPPORTED: https://en.wikipedia.org/wiki/Hulbjerg_Passage_Grave]; The chamber has a separate section [SUPPORTED: https://en.wikipedia.org/wiki/Hulbjerg_Passage_Grave]; Flint daggers were found in the separate section of the chamber [SUPPORTED: https://en.wikipedia.org/wiki/Hulbjerg_Passage_Grave]; Amber beads were found in the separate section [SUPPORTED: https://en.wikipedia.org/wiki/Hulbjerg_Passage_Grave]; Bones of 36 adults and 17 children were found [SUPPORTED: https://en.wikipedia.org/wiki/Hulbjerg_Passage_Grave]"}]'::jsonb),
    ('24b5da43-0a0d-45b4-b23e-7ca3fa4cd41a'::uuid, 'card_description', 'A Roman town that started as a fort in 80 AD, was abandoned, then rebuilt as a walled town. The walls enclosed it until the 4th century — a 300-year urban lifecycle.', 'Now Little Chester on the edge of Derby, Derventio Coritanorum held a Roman fort from about AD 80, while 600m to the east a vicus made pottery and worked iron on the Sawley Road.', 'teaser-card-s022:24b5da43-0a0d-45b4-b23e-7ca3fa4cd41a:card_description', 'teaser-card-s022 (teaser-card): teaser card, 178 characters, checked PASS, web-verified VERIFIED', '5bd7f9cb9ef61f7d7477e1eb93eeeb0b0941738791be761a4814b470203530b8|afc4bd83e1053cd55e5a68fcf61ec73623e5b983018e2ac8f590d76d08710132|afc4bd83e1053cd55e5a68fcf61ec73623e5b983018e2ac8f590d76d08710132', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-005", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Now Little Chester on the edge of Derby, Derventio Coritanorum held a Roman fort from about AD 80, while 600m to the east a vicus made pottery and worked iron on the Sawley Road."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-005 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "the place is now Little Chester [S2]; it is on the edge of Derby [S2]; Derventio held a Roman fort from about AD 80 [S4]; a vicus lay 600m to the east of the fort [S6]; the vicus made pottery and worked iron [S6]; the vicus was on the Sawley Road [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-014 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Derventio Coritanorum was a Roman settlement (small town with a fort), now Little Chester [SUPPORTED: https://en.wikipedia.org/wiki/Derventio_Coritanorum]; Little Chester lies on the edge of Derby [SUPPORTED: https://en.wikipedia.org/wiki/Derventio_Coritanorum]; The site held a Roman fort [SUPPORTED: https://en.wikipedia.org/wiki/Derventio_Coritanorum]; The fort dates from about AD 80 [SUPPORTED: https://en.wikipedia.org/wiki/Derventio_Coritanorum]; A vicus lay 600m to the east of the fort [SUPPORTED: https://en.wikipedia.org/wiki/Derventio_Coritanorum]; The vicus lay on the Sawley Road [SUPPORTED: https://en.wikipedia.org/wiki/Derventio_Coritanorum]; The vicus made pottery [SUPPORTED: https://en.wikipedia.org/wiki/Derventio_Coritanorum]; The vicus worked iron [SUPPORTED: https://en.wikipedia.org/wiki/Derventio_Coritanorum]"}]'::jsonb),
    ('250f2312-e906-4021-aaca-984096199937'::uuid, 'card_description', 'Over 80 Neolithic tombs clustered in a single forest — the largest concentration of megalithic graves in Central Europe. The Funnelbeaker people built them between 3500 and 3000 BC.', 'Over about 5 by 5 kilometres of forest, the Megalithic Tombs in Haldensleben Forest number more than 80, the largest concentration in central Europe, their chambers aligned east-west.', 'teaser-card-s022:250f2312-e906-4021-aaca-984096199937:card_description', 'teaser-card-s022 (teaser-card): teaser card, 183 characters, checked PASS, web-verified VERIFIED', 'c09cf1edb8561d46e782c10d1f94d06adae265b477c6eeb4d5109cfde05a2c8d|18a860835ed9f0756524dacf2339b8706c5b1b705111400064d232b1a6085b94|18a860835ed9f0756524dacf2339b8706c5b1b705111400064d232b1a6085b94', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-005", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Over about 5 by 5 kilometres of forest, the Megalithic Tombs in Haldensleben Forest number more than 80, the largest concentration in central Europe, their chambers aligned east-west."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-005 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "the tombs lie in a forest [S2]; they spread over an area of about 5 by 5 kilometres [S3]; there are more than 80 tombs [S1, S3]; they are the largest concentration of megalithic tombs in central Europe [S2]; their chambers are aligned east-west [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-014 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "The Megalithic Tombs in Haldensleben Forest are a group of megalithic tombs (Neolithic graves) in the forest near Haldensleben, Germany [SUPPORTED: https://en.wikipedia.org/wiki/Megalithic_tombs_in_Haldensleben_Forest]; The tombs lie over an area of about 5 by 5 kilometres [SUPPORTED: https://en.wikipedia.org/wiki/Megalithic_tombs_in_Haldensleben_Forest]; There are more than 80 tombs [SUPPORTED: https://en.wikipedia.org/wiki/Megalithic_tombs_in_Haldensleben_Forest]; It is the largest concentration of megalithic tombs in central Europe [SUPPORTED: https://en.wikipedia.org/wiki/Megalithic_tombs_in_Haldensleben_Forest]; The burial chambers are aligned east-west [SUPPORTED: https://en.wikipedia.org/wiki/Megalithic_tombs_in_Haldensleben_Forest]"}]'::jsonb),
    ('26b5802c-5fbf-4f3d-b872-7201bf027518'::uuid, 'card_description', 'Occupied from about 500 BC to 950 AD with six triadic temple complexes and two ballcourts. Its carved stelae record centuries of dynastic wars and alliances in the Petén Basin.', 'Along the Mopan and Holmul rivers, the Maya city of Naranjo spreads six triadic complexes, two ballcourts and two palace compounds. Parts of its hieroglyphic stairway now rest in London.', 'teaser-card-s022:26b5802c-5fbf-4f3d-b872-7201bf027518:card_description', 'teaser-card-s022 (teaser-card): teaser card, 186 characters, checked PASS, web-verified VERIFIED', 'ab8df1f21095f1246912b7c8c9be159a5d5e5e3ace2e2775ee653d48073ba0cc|7f0c8dadb556f0a989fa4ebac75a186420de30d43835b489aed49b6d767e3ced|7f0c8dadb556f0a989fa4ebac75a186420de30d43835b489aed49b6d767e3ced', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-005", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Along the Mopan and Holmul rivers, the Maya city of Naranjo spreads six triadic complexes, two ballcourts and two palace compounds. Parts of its hieroglyphic stairway now rest in London."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-005 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Naranjo lies along the Mopan and Holmul rivers [S3]; Naranjo is a Maya city [S1]; it has six triadic complexes [S5]; it has two ballcourts [S5]; it has two palace compounds [S5]; it has a hieroglyphic stairway [S7]; parts of that stairway are now in London [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-014 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Naranjo is a Maya city [SUPPORTED: https://en.wikipedia.org/wiki/Naranjo]; Naranjo is in Guatemala [SUPPORTED: https://en.wikipedia.org/wiki/Naranjo]; The city lies along the Mopan and Holmul rivers [SUPPORTED: https://en.wikipedia.org/wiki/Naranjo]; Its epicenter has six triadic complexes [SUPPORTED: https://en.wikipedia.org/wiki/Naranjo]; Its epicenter has two ballcourts [SUPPORTED: https://en.wikipedia.org/wiki/Naranjo]; Its epicenter has two palace compounds [SUPPORTED: https://en.wikipedia.org/wiki/Naranjo]; Naranjo has a hieroglyphic stairway [SUPPORTED: https://en.wikipedia.org/wiki/Naranjo]; Parts of Naranjo''s hieroglyphic stairway are now in London (British Museum) [SUPPORTED, no proving quote: https://en.wikipedia.org/wiki/Naranjo]"}]'::jsonb),
    ('2726f1bb-9af6-4f23-af79-fc0f789a5ddc'::uuid, 'card_description', 'Built in stone around 124 AD, this auxiliary fort on Hadrian''s Wall housed up to 800 infantry. Its communal latrines — stone benches over a flushing sewer — survive in remarkable condition.', NULL, 'teaser-card-s022:2726f1bb-9af6-4f23-af79-fc0f789a5ddc:card_description', 'teaser-card-s022 (card-clear-unproven-after-verify): card cleared (unproven-after-verify)', '||718dfe9f3b5cec0f3307e1beed135b677b1887ad8ce8d26875c4fe63c2fa205c', '[{"source": "lane WB run wb-ws-2026-09-27-05: unproven-after-verify", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "The web check could not prove: Housesteads Roman Fort is a Roman fort on Hadrian''s Wall in Northumberland, England; The web check could not prove: Housesteads Roman Fort is an auxiliary fort on Hadrian''s Wall in England"}]'::jsonb),
    ('274ff0f7-d0f7-4f66-8c73-43cf53c895e9'::uuid, 'card_description', 'The mortuary temple of Ramesses III, with massive reliefs of his victory over the Sea Peoples around 1178 BC. These carvings are the primary record of one of antiquity''s most mysterious invasions.', 'Near the foot of the Theban Hills, across the Nile from Luxor, Medinet Habu keeps the temple of Ramesses III and its list of pharaohs, lived in from pharaonic times to a Coptic settlement.', 'teaser-card-s022:274ff0f7-d0f7-4f66-8c73-43cf53c895e9:card_description', 'teaser-card-s022 (teaser-card): teaser card, 188 characters, checked PASS, web-verified VERIFIED', '1e2a86737a4943fd6b0e6ed165ecd945b130467fd368b39c26e0247c7a179239|4093a7159a7d8436b9dee6b543e46f25279399fb1d2dec93dd8ec38a67022e7a|4093a7159a7d8436b9dee6b543e46f25279399fb1d2dec93dd8ec38a67022e7a', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-005", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Near the foot of the Theban Hills, across the Nile from Luxor, Medinet Habu keeps the temple of Ramesses III and its list of pharaohs, lived in from pharaonic times to a Coptic settlement."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-005 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Medinet Habu is near the foot of the Theban Hills [S1]; it lies across the Nile from Luxor [S1]; it has the temple of Ramesses III [S3]; the temple contains a list of pharaohs [S3]; it was occupied from pharaonic times until a Coptic settlement [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-014 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Medinet Habu is an archaeological locality (with temples) in Egypt [SUPPORTED: https://en.wikipedia.org/wiki/Medinet_Habu]; Medinet Habu lies near the foot of the Theban Hills [SUPPORTED: https://en.wikipedia.org/wiki/Medinet_Habu]; Medinet Habu lies across the Nile from Luxor [SUPPORTED: https://en.wikipedia.org/wiki/Medinet_Habu]; Medinet Habu has the temple of Ramesses III [SUPPORTED: https://en.wikipedia.org/wiki/Medinet_Habu]; The temple of Ramesses III at Medinet Habu contains a list of pharaohs [SUPPORTED: https://en.wikipedia.org/wiki/Medinet_Habu]; The site was inhabited from pharaonic times [SUPPORTED: https://en.wikipedia.org/wiki/Medinet_Habu]; The settlement continued until a Coptic settlement (Coptic center called Jeme) [SUPPORTED: https://en.wikipedia.org/wiki/Medinet_Habu]"}]'::jsonb),
    ('277be4f6-02bc-4dd4-b1a2-1898e529faf9'::uuid, 'card_description', 'Gournia is the site of a Minoan palace complex in the Lasithi regional unit on the island of Crete.', 'Named for its many stone troughs, its original name unknown, Gournia on Crete is a Minoan town of sixty houses, a cemetery and roads around a central building called the palace.', 'teaser-card-s022:277be4f6-02bc-4dd4-b1a2-1898e529faf9:card_description', 'teaser-card-s022 (teaser-card): teaser card, 177 characters, checked PASS, web-verified VERIFIED', 'd69d2a80e66a058e319bb1ef9cabf3020dcbb5257b16d101cdb61e5126e2c7c2|9cf8f9be0c7ad15a64cd0b9e75cffca1e85f487aeb7e37e0494e380a1e6d1174|9cf8f9be0c7ad15a64cd0b9e75cffca1e85f487aeb7e37e0494e380a1e6d1174', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-005", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Named for its many stone troughs, its original name unknown, Gournia on Crete is a Minoan town of sixty houses, a cemetery and roads around a central building called the palace."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-005 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "its name comes from its many stone troughs [S2]; its original name is unknown [S2]; Gournia is on Crete [S1]; it is a Minoan town [S3, S4]; it has sixty houses [S4]; it has a cemetery [S4]; it has roads [S4]; the town is arranged around a central building [S4, S5]; that building was called the palace [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-verify-015 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Gournia is a settlement (a town), not a fort, tomb or temple - the central claim [SUPPORTED: https://en.wikipedia.org/wiki/Gournia]; Gournia is on Crete (Greece) [SUPPORTED: https://en.wikipedia.org/wiki/Gournia]; Gournia is Minoan (a Minoan town) [SUPPORTED: https://en.wikipedia.org/wiki/Gournia]; The modern name Gournia comes from the many stone troughs at the site [SUPPORTED: https://en.wikipedia.org/wiki/Gournia]; The original name of the site is unknown [SUPPORTED: https://en.wikipedia.org/wiki/Gournia]; The town had sixty houses [SUPPORTED: https://en.wikipedia.org/wiki/Gournia]; The site has a cemetery [SUPPORTED: https://en.wikipedia.org/wiki/Gournia]; The site has roads (a road system) connecting the town [SUPPORTED: https://en.wikipedia.org/wiki/Gournia]; The town has a central building that the excavator called the palace [SUPPORTED: https://en.wikipedia.org/wiki/Gournia]; The town is centred around the palace complex [SUPPORTED: https://en.wikipedia.org/wiki/Gournia]"}]'::jsonb),
    ('27df72a6-018c-4870-ba5b-c719dca6c570'::uuid, 'card_description', 'A reconstructed Roman villa with buildings spread over a full estate. It shows how a working Roman farm operated, from kitchens to bathhouses.', 'The Roman Villa Borg stands rebuilt on its Roman foundation walls, as it probably looked in the 2nd to 3rd century. Beneath lie traces of Iron Age and Beaker culture settlements.', 'teaser-card-s022:27df72a6-018c-4870-ba5b-c719dca6c570:card_description', 'teaser-card-s022 (teaser-card): teaser card, 178 characters, checked PASS, web-verified VERIFIED', 'b922011b8d01eeb7c16ad28c26179116ff3524756f15e28696f3d1475a0ffa23|8fedf770cf8a1e80f981a99778c3bd6019a36e93304ee2e5047b8968e8f5ad3f|8fedf770cf8a1e80f981a99778c3bd6019a36e93304ee2e5047b8968e8f5ad3f', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-005", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "The Roman Villa Borg stands rebuilt on its Roman foundation walls, as it probably looked in the 2nd to 3rd century. Beneath lie traces of Iron Age and Beaker culture settlements."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-005 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "the Roman Villa Borg is rebuilt [S1, S8]; the rebuilt villa stands on its Roman foundation walls [S8]; it shows how it probably looked in the 2nd to 3rd century [S8]; traces of Iron Age settlement lie beneath it [S4, S5]; traces of Beaker culture settlements lie beneath it [S4, S5]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-015 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Roman Villa Borg is a Roman villa (villa rustica), reconstructed, in Germany - the central claim [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Villa_Borg]; The villa stands rebuilt on its Roman foundation walls [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Villa_Borg]; The reconstruction shows the probable appearance of the villa in the 2nd to 3rd century [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Villa_Borg]; Beneath the villa lie traces of Iron Age settlements [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Villa_Borg]; Beneath the villa lie traces of Beaker culture settlements [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Villa_Borg]; The Iron Age and Beaker traces lie beneath (below) the Roman villa [SUPPORTED: https://en.wikipedia.org/wiki/Roman_Villa_Borg]"}]'::jsonb),
    ('2851ba0a-1403-47b9-a605-deb3735046ca'::uuid, 'card_description', 'Small fort of unknown date at 413 metres on the slopes of Tal-y-Fan in Conwy County, never excavated. The name means "Small Fort" -- beyond position and outline, little is recorded.', 'On the eastern slopes of Tal-y-Fan, approximately 413 metres up, Caer Bach, the Small Fort, keeps its past close: a hillfort of indeterminate age that has seen minimal investigation.', 'teaser-card-s022:2851ba0a-1403-47b9-a605-deb3735046ca:card_description', 'teaser-card-s022 (teaser-card): teaser card, 182 characters, checked PASS, web-verified VERIFIED', '8dd3421de152e8f6a8076180f56be9b5027e83c69a41600de07dedbfce6b3019|caffb470746d089b8aed7f02681e584f916acfeed7fcc94128f53e2d12c20224|caffb470746d089b8aed7f02681e584f916acfeed7fcc94128f53e2d12c20224', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-005", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "On the eastern slopes of Tal-y-Fan, approximately 413 metres up, Caer Bach, the Small Fort, keeps its past close: a hillfort of indeterminate age that has seen minimal investigation."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-005 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Caer Bach is on the eastern slopes of Tal-y-Fan [S3]; it is at approximately 413 metres [S3]; its name means the Small Fort [S2]; little is known of its past [S4]; it is a hillfort [S1]; its age is indeterminate [S1]; it has seen minimal investigation [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-015 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Caer Bach is a hillfort (in Wales) - the central claim [SUPPORTED: https://en.wikipedia.org/wiki/Caer_Bach]; Caer Bach lies in Wales [SUPPORTED: https://en.wikipedia.org/wiki/Caer_Bach]; It lies on the eastern slopes of Tal-y-Fan [SUPPORTED: https://en.wikipedia.org/wiki/Caer_Bach]; It lies at an altitude of approximately 413 metres [SUPPORTED: https://en.wikipedia.org/wiki/Caer_Bach]; Caer Bach means the Small Fort [SUPPORTED: https://en.wikipedia.org/wiki/Caer_Bach]; The hillfort is of indeterminate age [SUPPORTED: https://en.wikipedia.org/wiki/Caer_Bach]; The hillfort is of indeterminate age (stated directly) [SUPPORTED: https://en.wikipedia.org/wiki/Caer_Bach]; The site has seen minimal investigation, so little is known of its past [SUPPORTED: https://en.wikipedia.org/wiki/Caer_Bach]"}]'::jsonb),
    ('285a2a92-7213-48ca-b4d9-fd157697e096'::uuid, 'card_description', 'Beneath this Roman bathhouse town lay a Michelsberg ditch from 4400 BC — a rare find in the Low Countries. The 1997 Schelsberg dig produced almost no regional parallels for this period.', 'Heerlen''s history properly starts with Coriovallum, a Roman military settlement where two main roads crossed. Roman villas were excavated around it; in its centre, a bathhouse found in 1940.', 'teaser-card-s022:285a2a92-7213-48ca-b4d9-fd157697e096:card_description', 'teaser-card-s022 (teaser-card): teaser card, 190 characters, checked PASS, web-verified VERIFIED', '1c3fe33fe6d3b17792457a4d21586c6c000a7ebdf7d1be95e9f90e0fa97faea8|244b5635f2a2eee74a3e314ed00b936fde688cfc22ff1c0167f042054c0a4a50|244b5635f2a2eee74a3e314ed00b936fde688cfc22ff1c0167f042054c0a4a50', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-005", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Heerlen''s history properly starts with Coriovallum, a Roman military settlement where two main roads crossed. Roman villas were excavated around it; in its centre, a bathhouse found in 1940."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-005 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Heerlen''s history properly starts with the Roman settlement of Coriovallum [S3, S4]; Coriovallum was a Roman military settlement [S4]; it stood where two main roads crossed [S4]; Roman villas were excavated in its surroundings [S5]; a bathhouse lies in the centre of Heerlen [S6]; the bathhouse was found in 1940 [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-015 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Heerlen is a city in the Netherlands, with Roman origins in Coriovallum - the central claim [SUPPORTED: https://en.wikipedia.org/wiki/Heerlen]; Heerlen''s history properly starts with the arrival of the Romans (Coriovallum) [SUPPORTED: https://en.wikipedia.org/wiki/Heerlen]; The Romans founded a military settlement named Coriovallum [SUPPORTED: https://en.wikipedia.org/wiki/Heerlen]; Coriovallum lay where two main roads crossed [SUPPORTED: https://en.wikipedia.org/wiki/Heerlen]; Roman villas were excavated in and around Heerlen [SUPPORTED: https://en.wikipedia.org/wiki/Heerlen]; A Roman bathhouse (the Thermae complex) lies in the centre of Heerlen [SUPPORTED: https://en.wikipedia.org/wiki/Heerlen]; The bathhouse was found (discovered) in 1940 [SUPPORTED: https://en.wikipedia.org/wiki/Heerlen]"}]'::jsonb),
    ('28d08d27-d959-42d0-922c-8e91c795d432'::uuid, 'card_description', 'The gravesite was discovered in an olive grove near the ancient Palace of Nestor, within the Bronze Age city of Pylos.', 'In an olive grove near the Palace of Nestor, the Griffin Warrior Tomb held an intact skeleton and over 3500 items, among them the Pylos Combat Agate and four signet gold rings.', 'teaser-card-s022:28d08d27-d959-42d0-922c-8e91c795d432:card_description', 'teaser-card-s022 (teaser-card): teaser card, 176 characters, checked PASS, web-verified VERIFIED', 'afb480d7b2788b4785d19e3f5cbc1e6311281de75a1d9053e8a0293278d8819b|591abbcfd6f298c61afed8a048e17b134730cc666f25db8ac9d971fe360261af|591abbcfd6f298c61afed8a048e17b134730cc666f25db8ac9d971fe360261af', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-005", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "In an olive grove near the Palace of Nestor, the Griffin Warrior Tomb held an intact skeleton and over 3500 items, among them the Pylos Combat Agate and four signet gold rings."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-005 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "the tomb is in an olive grove [S6]; it is near the Palace of Nestor [S6]; it held an intact skeleton [S4]; over 3500 items were recovered from it [S5]; they include the Pylos Combat Agate [S5]; they include four signet gold rings [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-015 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "The Griffin Warrior Tomb is a tomb (a Bronze Age shaft tomb) in Greece near Pylos - the central claim [SUPPORTED: https://en.wikipedia.org/wiki/Griffin_Warrior_Tomb]; The tomb lies in an olive grove [SUPPORTED: https://en.wikipedia.org/wiki/Griffin_Warrior_Tomb]; The tomb lies near the Palace of Nestor [SUPPORTED: https://en.wikipedia.org/wiki/Griffin_Warrior_Tomb]; The tomb held an intact skeleton [SUPPORTED: https://en.wikipedia.org/wiki/Griffin_Warrior_Tomb]; The tomb held over 3500 items [SUPPORTED: https://en.wikipedia.org/wiki/Griffin_Warrior_Tomb]; Among the items is the Pylos Combat Agate [SUPPORTED: https://en.wikipedia.org/wiki/Griffin_Warrior_Tomb]; Among the items are four signet gold rings [SUPPORTED: https://en.wikipedia.org/wiki/Griffin_Warrior_Tomb]"}]'::jsonb),
    ('291542d5-8a09-4599-bd7a-715f45e432a1'::uuid, 'card_description', 'Bronze Age rock carvings showing men raising axes and spears, footprints, and overlapping figures. The carvings were added over generations, each artist carving atop earlier work.', 'Near Strömstad, overlapping Bronze Age carvings cover a rock face: the Massleberg 1 Rock Art, with men raising axes, a sun cross, deer, ships and the unusual image of a man carrying a ship.', 'teaser-card-s022:291542d5-8a09-4599-bd7a-715f45e432a1:card_description', 'teaser-card-s022 (teaser-card): teaser card, 189 characters, checked PASS, web-verified VERIFIED', '66bda8850e023869ffad8fc12f4d31e39daeee03efaa5bedc4917e0057afd316|d3ee56be2b7050ba7d9e38c57671099f9b4e6c89547b27337a0f1c6a21cc5212|d3ee56be2b7050ba7d9e38c57671099f9b4e6c89547b27337a0f1c6a21cc5212', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-006", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Near Strömstad, overlapping Bronze Age carvings cover a rock face: the Massleberg 1 Rock Art, with men raising axes, a sun cross, deer, ships and the unusual image of a man carrying a ship."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-006 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "the site is near Strömstad [S1]; the carvings are on a rock face [S2]; the carvings partially overlap [S2]; the carvings date from the Bronze Age [S2]; the carvings depict men raising axes [S3]; the carvings depict a sun cross [S3]; the carvings depict deer [S3]; the carvings depict ships [S3]; there is an unusual image of a man carrying a ship [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-016 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "The site is a rock-art site: carvings on a rock face [SUPPORTED: https://en.wikipedia.org/wiki/Massleberg_1_rock_art]; The site lies near Strömstad [SUPPORTED: https://en.wikipedia.org/wiki/Massleberg_1_rock_art]; The site is in Sweden [SUPPORTED: https://en.wikipedia.org/wiki/Massleberg_1_rock_art]; Several carvings overlap one another [SUPPORTED: https://en.wikipedia.org/wiki/Massleberg_1_rock_art]; The carvings date to the Bronze Age [SUPPORTED: https://en.wikipedia.org/wiki/Massleberg_1_rock_art]; The carvings include men raising axes [SUPPORTED: https://en.wikipedia.org/wiki/Massleberg_1_rock_art]; The carvings include a sun cross [SUPPORTED: https://en.wikipedia.org/wiki/Massleberg_1_rock_art]; The carvings include deer [SUPPORTED: https://en.wikipedia.org/wiki/Massleberg_1_rock_art]; The carvings include ships [SUPPORTED: https://en.wikipedia.org/wiki/Massleberg_1_rock_art]; The carvings include a man carrying a ship [SUPPORTED: https://en.wikipedia.org/wiki/Massleberg_1_rock_art]; The image of a man carrying a ship is unusual [SUPPORTED: https://en.wikipedia.org/wiki/Massleberg_1_rock_art]"}]'::jsonb),
    ('297e5e17-96b1-4df9-88ac-638b1231a654'::uuid, 'card_description', 'A Roman city in the province of Noricum, where temples to Jupiter Dolichenus and Mithras served the garrison. Its name survives as a Catholic titular see.', 'On the Zollfeld in Carinthia stood Virunum, a Roman city founded under Emperor Claudius as the capital of Noricum, on the main route from the Adriatic to the Danube.', 'teaser-card-s022:297e5e17-96b1-4df9-88ac-638b1231a654:card_description', 'teaser-card-s022 (teaser-card): teaser card, 165 characters, checked PASS, web-verified VERIFIED', 'f5ce21597eb9f07e2ed7d2ce4102193cdefa103847f3c5ff22b00213330fcfde|b0c7df3d89b10de24cfd2f6c3889b9f5b1e5fbaedf4140b9a59b02024eb37abd|b0c7df3d89b10de24cfd2f6c3889b9f5b1e5fbaedf4140b9a59b02024eb37abd', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-006", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "On the Zollfeld in Carinthia stood Virunum, a Roman city founded under Emperor Claudius as the capital of Noricum, on the main route from the Adriatic to the Danube."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-006 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Virunum stood on the Zollfeld [S1]; the Zollfeld is in Carinthia [S1]; Virunum was a Roman city [S1]; it was founded under Emperor Claudius [S2]; it was founded as the capital of Noricum [S2]; it lay on the main route from the Adriatic to the Danube [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-016 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Virunum was a Roman city [SUPPORTED: https://en.wikipedia.org/wiki/Virunum]; Virunum lay in the province of Noricum [SUPPORTED: https://en.wikipedia.org/wiki/Virunum]; Virunum lay on the Zollfeld [SUPPORTED: https://en.wikipedia.org/wiki/Virunum]; The Zollfeld is in Carinthia [SUPPORTED: https://en.wikipedia.org/wiki/Virunum]; Virunum was founded under Emperor Claudius [SUPPORTED: https://en.wikipedia.org/wiki/Virunum]; Virunum was the capital of Noricum [SUPPORTED: https://en.wikipedia.org/wiki/Virunum]; Virunum lay on the main route from the Adriatic to the Danube [SUPPORTED: https://en.wikipedia.org/wiki/Virunum]; The city no longer stands (it declined and was abandoned) [SUPPORTED: https://en.wikipedia.org/wiki/Virunum]"}]'::jsonb),
    ('2981f5c9-7aa0-4ed2-bb1a-b5bb43ab1b75'::uuid, 'card_description', 'Ruins of a Roman bridge built around 90 AD to carry Dere Street over the River Tees. The river has since shifted 90 metres, leaving the bridge stranded in a field.', 'Gravel quarrying in 1972 uncovered massive masonry blocks by the River Tees: Piercebridge Roman Bridge, which once carried Dere Street across the river, guarded by a Roman fort.', 'teaser-card-s022:2981f5c9-7aa0-4ed2-bb1a-b5bb43ab1b75:card_description', 'teaser-card-s022 (teaser-card): teaser card, 177 characters, checked PASS, web-verified VERIFIED', 'bf3a3c3b248616c2fd8313f1cebaf5e0f0f13ef931337aa761a0723a23f30b1b|e878f9e860c704f11e62c0cb624da9bae4feebc5d8e2cde94c36fdd04720267b|e878f9e860c704f11e62c0cb624da9bae4feebc5d8e2cde94c36fdd04720267b', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-006", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Gravel quarrying in 1972 uncovered massive masonry blocks by the River Tees: Piercebridge Roman Bridge, which once carried Dere Street across the river, guarded by a Roman fort."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-006 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "the remains were uncovered during gravel quarrying [S6]; the remains were uncovered in 1972 [S6]; the remains are massive masonry blocks [S5]; the bridge is by (over) the River Tees [S1]; the bridge carried Dere Street across the river [S2]; the bridge was guarded by a Roman fort [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-016 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "The site is the ruin of a Roman bridge over the River Tees in northern England [SUPPORTED: https://en.wikipedia.org/wiki/Piercebridge_Roman_Bridge]; The structure is a bridge (majority archaeological opinion; one dissenting reading as a navigation dam) [SUPPORTED: https://en.wikipedia.org/wiki/Piercebridge_Roman_Bridge]; The remains were uncovered in 1972 during gravel quarrying [SUPPORTED: https://en.wikipedia.org/wiki/Piercebridge_Roman_Bridge]; The remains are massive masonry blocks [SUPPORTED: https://en.wikipedia.org/wiki/Piercebridge_Roman_Bridge]; The bridge carried Dere Street across the river [SUPPORTED: https://en.wikipedia.org/wiki/Piercebridge_Roman_Bridge]; A Roman fort guarded the bridge [SUPPORTED: https://en.wikipedia.org/wiki/Piercebridge_Roman_Bridge]"}]'::jsonb),
    ('2a4f816f-71bb-43b5-be29-9239c432fc4f'::uuid, 'card_description', 'Two ruined circles on Bodmin Moor, just 2.5 metres apart, each 23 metres across. Both have an exceptionally large stone to the southeast — the same deliberate placement in each ring.', 'On Bodmin Moor, between King Arthur''s Downs and Emblance Downs, lie the Emblance Downs Stone Circles: two ruined rings 2.5 metres apart, each with an exceptionally large stone.', 'teaser-card-s022:2a4f816f-71bb-43b5-be29-9239c432fc4f:card_description', 'teaser-card-s022 (teaser-card): teaser card, 176 characters, checked PASS, web-verified VERIFIED', '5c33098eaad3dbd545fac97a2251644d953204370a869126109d34d1c0744e0a|eb98c6813dc1b1b3f01386022d4a3aaa98a2494760a1ea62afbd9b37b572cfd9|eb98c6813dc1b1b3f01386022d4a3aaa98a2494760a1ea62afbd9b37b572cfd9', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-006", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "On Bodmin Moor, between King Arthur''s Downs and Emblance Downs, lie the Emblance Downs Stone Circles: two ruined rings 2.5 metres apart, each with an exceptionally large stone."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-006 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "the circles are on Bodmin Moor [S1]; they lie between King Arthur''s Downs and Emblance Downs [S2]; there are two rings [S1, S2]; the rings are ruined [S2]; the rings are 2.5 metres apart [S3]; each ring has an exceptionally large stone [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-016 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "The site is a pair of stone circles [SUPPORTED: https://en.wikipedia.org/wiki/Emblance_Downs_stone_circles]; The site lies on Bodmin Moor [SUPPORTED: https://en.wikipedia.org/wiki/Emblance_Downs_stone_circles]; The circles lie between King Arthur''s Downs and Emblance Downs [SUPPORTED: https://en.wikipedia.org/wiki/Emblance_Downs_stone_circles]; There are two rings [SUPPORTED: https://en.wikipedia.org/wiki/Emblance_Downs_stone_circles]; Both rings are ruined [SUPPORTED: https://en.wikipedia.org/wiki/Emblance_Downs_stone_circles]; The two rings are 2.5 metres apart [SUPPORTED: https://en.wikipedia.org/wiki/Emblance_Downs_stone_circles]; Each ring has a large stone [SUPPORTED: https://en.wikipedia.org/wiki/Emblance_Downs_stone_circles]; The large stone in each ring is exceptionally large [SUPPORTED: https://en.wikipedia.org/wiki/Emblance_Downs_stone_circles]"}]'::jsonb),
    ('2a956522-6ffd-4ab1-be5c-dc17990dfa79'::uuid, 'card_description', 'Early Formative pyramid complex, 2000–1500 BC. The main temple measures 350 by 300 metres and stands 35 metres tall — one of the largest architectural structures in the ancient Americas of its era.', 'On the left bank of the Sechín River rises Sechin Alto, its pyramidal Templo 35m high, fronted by five plazas, some with sunken circular courts, in a ceremonial complex from 2000-1500 BC.', 'teaser-card-s022:2a956522-6ffd-4ab1-be5c-dc17990dfa79:card_description', 'teaser-card-s022 (teaser-card): teaser card, 187 characters, checked PASS, web-verified VERIFIED', '347bb4b19bf9b850a2f78a3ebe1c05ad1681342f14bfefbaf920eb7c588a434c|93a3c96d56c7b57806fcc32b4b4cc5e5f7b1d6b86b8114d63a0c282b0db8fda0|93a3c96d56c7b57806fcc32b4b4cc5e5f7b1d6b86b8114d63a0c282b0db8fda0', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-006", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "On the left bank of the Sechín River rises Sechin Alto, its pyramidal Templo 35m high, fronted by five plazas, some with sunken circular courts, in a ceremonial complex from 2000-1500 BC."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-006 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Sechin Alto is on the left bank of the Sechín River [S2]; its main structure, the Templo, is pyramidal [S4]; the Templo is 35m high [S5]; five plazas extend in front of the Templo [S7]; some plazas have sunken circular courts [S7]; the complex is ceremonial [S7]; the complex dates from 2000-1500 BC [S1]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-016 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Sechin Alto is a large architectural complex in Peru [SUPPORTED: https://en.wikipedia.org/wiki/Sechin_Alto]; It lies on the left bank of the Sechín River [SUPPORTED: https://en.wikipedia.org/wiki/Sechin_Alto]; Its main structure, the Templo, is pyramidal [SUPPORTED: https://en.wikipedia.org/wiki/Sechin_Alto]; The Templo is 35 m high [SUPPORTED: https://en.wikipedia.org/wiki/Sechin_Alto]; Five plazas front the Templo, some with sunken circular courts [SUPPORTED: https://en.wikipedia.org/wiki/Sechin_Alto]; The complex is ceremonial [SUPPORTED: https://en.wikipedia.org/wiki/Sechin_Alto]; The complex dates to 2000-1500 BC [SUPPORTED: https://en.wikipedia.org/wiki/Sechin_Alto]"}]'::jsonb),
    ('2bdc9938-668f-4a33-a86f-8497b7f73e21'::uuid, 'card_description', 'Carbon-14 dating of a bone stuck in a crack in a wall decorated with hand stencils revealed close to 27,000 years BP, indicating that the cave was frequented in the Gravettian period.', 'In the Pyrenees, the Caves of Gargas hold numerous negative hand stencils in cave art about 27,000 years old, while engravings of horses, bison, aurochs, ibex and mammoth hide elsewhere.', 'teaser-card-s022:2bdc9938-668f-4a33-a86f-8497b7f73e21:card_description', 'teaser-card-s022 (teaser-card): teaser card, 186 characters, checked PASS, web-verified VERIFIED', '782f90e0ade1c57d236c7186b99e3aef927422652b9c54d1d4ed9b5d44d4dc14|d7bec053d965a0d69b5b2ac7cc2144289fd0bc34e459be7b69daefa76b4fc755|d7bec053d965a0d69b5b2ac7cc2144289fd0bc34e459be7b69daefa76b4fc755', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-006", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "In the Pyrenees, the Caves of Gargas hold numerous negative hand stencils in cave art about 27,000 years old, while engravings of horses, bison, aurochs, ibex and mammoth hide elsewhere."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-006 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "the Caves of Gargas are in the Pyrenees [S1]; the caves hold numerous negative hand stencils [S3]; the cave art is about 27,000 years old [S1]; there are engravings of horses, bison, aurochs, ibex and mammoth [S4]; the engravings are in other parts of the caves [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-017 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "The Caves of Gargas are a cave site with prehistoric cave art, in the Pyrenees of France [SUPPORTED: https://en.wikipedia.org/wiki/Caves_of_Gargas]; The caves hold numerous negative hand stencils [SUPPORTED: https://en.wikipedia.org/wiki/Caves_of_Gargas]; The hand stencil cave art is about 27,000 years old [SUPPORTED: https://en.wikipedia.org/wiki/Caves_of_Gargas]; Engravings of horses, bison, aurochs, ibex and mammoth are present in the caves [SUPPORTED: https://en.wikipedia.org/wiki/Caves_of_Gargas]; The animal engravings are found elsewhere in the caves, apart from the hand stencils [SUPPORTED: https://en.wikipedia.org/wiki/Caves_of_Gargas]"}]'::jsonb),
    ('2bfc5712-1232-4ed7-a57b-d674ef25b6f9'::uuid, 'card_description', 'An Iron Age univallate hillfort that straddles a parish boundary. A scarp inside the fort marks the ancient boundary — the parish line may predate recorded history.', 'On a prominent hilltop overlooking the valley of the River Avon, the Iron Age hillfort of Clearbury Ring keeps its well-preserved rampart. A Paleolithic hand axe was found here.', 'teaser-card-s022:2bfc5712-1232-4ed7-a57b-d674ef25b6f9:card_description', 'teaser-card-s022 (teaser-card): teaser card, 177 characters, checked PASS, web-verified VERIFIED', '3e3b075010dedc33f4ab919e8599aec151b1cc0501f8d0ff3324554de6b8caad|719c0e3fadd08825159405d42f6313a7efa1361938c3b553a492278e7f31f4fe|719c0e3fadd08825159405d42f6313a7efa1361938c3b553a492278e7f31f4fe', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-006", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "On a prominent hilltop overlooking the valley of the River Avon, the Iron Age hillfort of Clearbury Ring keeps its well-preserved rampart. A Paleolithic hand axe was found here."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-006 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "the fort is on a prominent hilltop [S2]; the hilltop overlooks the valley of the River Avon [S2]; Clearbury Ring is an Iron Age hillfort [S1]; its rampart is well preserved [S3]; a Paleolithic hand axe was found here [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-017 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Clearbury Ring is a hillfort [SUPPORTED: https://en.wikipedia.org/wiki/Clearbury_Ring]; The hillfort dates to the Iron Age [SUPPORTED: https://en.wikipedia.org/wiki/Clearbury_Ring]; It stands on a prominent hilltop [SUPPORTED: https://en.wikipedia.org/wiki/Clearbury_Ring]; The hilltop overlooks the valley of the River Avon [SUPPORTED: https://en.wikipedia.org/wiki/Clearbury_Ring]; Its rampart is well preserved [SUPPORTED: https://en.wikipedia.org/wiki/Clearbury_Ring]; A Paleolithic hand axe was found at the site [SUPPORTED: https://en.wikipedia.org/wiki/Clearbury_Ring]"}]'::jsonb),
    ('2cb52ee9-dbd0-4437-8c4d-4fafeda01936'::uuid, 'card_description', '9th century BC–10th century AD site with both Olmec and Maya features. Takʼalik Abʼajʼs 6.5 km² core holds 70 monumental structures, a dozen plazas, 2 ballcourts, and over 239 known monuments.', 'Takalik Abaj National Park holds the remains of some 70 monumental structures around a dozen plazas, a city from the first blossoming of Maya culture by about 400 BC.', 'teaser-card-s022:2cb52ee9-dbd0-4437-8c4d-4fafeda01936:card_description', 'teaser-card-s022 (teaser-card): teaser card, 166 characters, checked PASS, web-verified VERIFIED', '196d0ae6fdc6778c9e7be69622df47d50cad233b592251a11fc24627dab08450|c27ed73bb4657c917f4ca91120b26d9530b72881b0d7929f914e32e12ad72fa2|c27ed73bb4657c917f4ca91120b26d9530b72881b0d7929f914e32e12ad72fa2', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-006", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Takalik Abaj National Park holds the remains of some 70 monumental structures around a dozen plazas, a city from the first blossoming of Maya culture by about 400 BC."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-006 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "the site holds the remains of some 70 monumental structures [S5]; the structures are positioned around a dozen plazas [S5]; Takalik Abaj was a city [S2]; it represents the first blossoming of Maya culture [S1]; that blossoming had occurred by about 400 BC [S1]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-017 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Takalik Abaj is a pre-Columbian archaeological site (ancient city) in Guatemala [SUPPORTED: https://en.wikipedia.org/wiki/Tak%27alik_Ab%27aj]; The site has been declared a national park [SUPPORTED: https://en.wikipedia.org/wiki/Tak%27alik_Ab%27aj]; The core of the site includes the remains of some 70 monumental structures [SUPPORTED: https://en.wikipedia.org/wiki/Tak%27alik_Ab%27aj]; The 70 monumental structures are positioned around a dozen plazas [SUPPORTED: https://en.wikipedia.org/wiki/Tak%27alik_Ab%27aj]; Takalik Abaj represents the first blossoming of Maya culture, which had occurred by about 400 BC [SUPPORTED: https://en.wikipedia.org/wiki/Tak%27alik_Ab%27aj]"}]'::jsonb),
    ('2df3baac-05ae-4af8-9e6e-d6b709fa78f3'::uuid, 'card_description', 'A bivallate hillfort with double bank and ditch on two sides and a single bank on the others. It encloses 4.4 hectares within a private wooded estate.', 'South of the village of Chieveley in Berkshire, the bivallate Iron Age hillfort of Bussock Camp encloses approximately 11 acres, its entrance to the north believed to be original.', 'teaser-card-s022:2df3baac-05ae-4af8-9e6e-d6b709fa78f3:card_description', 'teaser-card-s022 (teaser-card): teaser card, 179 characters, checked PASS, web-verified VERIFIED', '6de51ba4d860c24a4882a721a9fb784342373387dccb42ac6b2d4eebbbae560e|472487cf9ebebeb83ab802f58e581ff30be40b7f26c90b23498c8706f1375c9c|472487cf9ebebeb83ab802f58e581ff30be40b7f26c90b23498c8706f1375c9c', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-006", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "South of the village of Chieveley in Berkshire, the bivallate Iron Age hillfort of Bussock Camp encloses approximately 11 acres, its entrance to the north believed to be original."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-006 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "the site is south of the village of Chieveley [S3]; the site is in Berkshire [S1]; Bussock Camp is a bivallate hillfort [S1]; it is Iron Age [S1]; it encloses approximately 11 acres [S2]; its entrance is to the north [S2]; the entrance is believed to be original [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-017 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Bussock Camp is a hillfort [SUPPORTED: https://en.wikipedia.org/wiki/Bussock_Camp]; The hillfort dates to the Iron Age [SUPPORTED: https://en.wikipedia.org/wiki/Bussock_Camp]; The hillfort is bivallate (double bank and ditch) [SUPPORTED: https://en.wikipedia.org/wiki/Bussock_Camp]; It lies south of the village of Chieveley [SUPPORTED: https://en.wikipedia.org/wiki/Bussock_Camp]; It is in Berkshire [SUPPORTED: https://en.wikipedia.org/wiki/Bussock_Camp]; The site encloses approximately 11 acres [SUPPORTED: https://en.wikipedia.org/wiki/Bussock_Camp]; Its entrance is to the north of the site [SUPPORTED: https://en.wikipedia.org/wiki/Bussock_Camp]; The northern entrance is believed to be original [SUPPORTED: https://en.wikipedia.org/wiki/Bussock_Camp]"}]'::jsonb),
    ('2e2617fe-2aa6-48ba-b8f1-4b3725e25e8d'::uuid, 'card_description', 'Cliff-top broch on Mainland Orkney, 20 metres above sea. External diameter 17 metres; walls 3.5 to 5 metres thick -- the double-skin dry-stone construction typical of the form.', 'On a cliff-top promontory 20 metres above the sea, the Broch of Borwick keeps walls 3.5 to 5 metres thick. Its finds included combs, a small whale vertebra cup and a stone gaming piece.', 'teaser-card-s022:2e2617fe-2aa6-48ba-b8f1-4b3725e25e8d:card_description', 'teaser-card-s022 (teaser-card): teaser card, 185 characters, checked PASS, web-verified VERIFIED', 'e5ed322be2ab38313cf7449a1d9ba35b174bbfc7adbf1aa9fa4760f5070eb309|23413a78e4d443b41b4595ed3ee5d9909ca521574cbce74d3fc74e6a8a0c54f5|23413a78e4d443b41b4595ed3ee5d9909ca521574cbce74d3fc74e6a8a0c54f5', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-006", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "On a cliff-top promontory 20 metres above the sea, the Broch of Borwick keeps walls 3.5 to 5 metres thick. Its finds included combs, a small whale vertebra cup and a stone gaming piece."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-006 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "the broch is on a cliff-top promontory [S2]; the promontory is 20 metres above the sea [S2]; its walls are 3.5 to 5 metres thick [S4]; finds included combs [S7]; finds included a small whale vertebra cup [S7]; finds included a stone gaming piece [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-017 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "The Broch of Borwick is an Iron Age broch in Orkney, Scotland [SUPPORTED: https://en.wikipedia.org/wiki/Broch_of_Borwick]; It stands on a cliff-top promontory 20 metres above the sea [SUPPORTED: https://en.wikipedia.org/wiki/Broch_of_Borwick]; Its walls are 3.5 to 5 metres thick [SUPPORTED: https://en.wikipedia.org/wiki/Broch_of_Borwick]; Finds included combs [SUPPORTED: https://en.wikipedia.org/wiki/Broch_of_Borwick]; Finds included a small whale vertebra cup [SUPPORTED: https://en.wikipedia.org/wiki/Broch_of_Borwick]; Finds included a stone gaming piece [SUPPORTED: https://en.wikipedia.org/wiki/Broch_of_Borwick]"}]'::jsonb),
    ('2e974e22-9f31-4d6c-a258-0195f444f533'::uuid, 'card_description', 'A circular ditch surrounding the Heel Stone at Stonehenge, about 1.2 metres deep. Whether the ditch and the stone were planned together or built separately is still unknown.', 'The Heelstone Ditch rings the Heel Stone at Stonehenge, but whether the two were meant together is not known. Against it lies Stonehole 97, whose missing stone is called Heelstone''s twin.', 'teaser-card-s022:2e974e22-9f31-4d6c-a258-0195f444f533:card_description', 'teaser-card-s022 (teaser-card): teaser card, 187 characters, checked PASS, web-verified VERIFIED', '58125a684aa744390fe2e04dbb1bc5e04397f4b434256c2911a10c5852719f35|41c67c3a1dfcce4147ab96f398c9a227a1d386989b8bfe0b18bdf4665a71a396|41c67c3a1dfcce4147ab96f398c9a227a1d386989b8bfe0b18bdf4665a71a396', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-006", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "The Heelstone Ditch rings the Heel Stone at Stonehenge, but whether the two were meant together is not known. Against it lies Stonehole 97, whose missing stone is called Heelstone''s twin."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-006 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "the ditch surrounds the Heel Stone [S1]; the Heel Stone is at Stonehenge [S1]; it is not known whether the ditch and the stone were meant to relate to each other [S2]; Stonehole 97 lies against the ditch [S5]; the stone of Stonehole 97 is missing [S5]; that missing stone is called Heelstone''s twin [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-018 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Heelstone Ditch is a ditch (a roughly circular feature) at Stonehenge [SUPPORTED: https://en.wikipedia.org/wiki/Heelstone_Ditch]; The ditch rings (surrounds) the Heel Stone [SUPPORTED: https://en.wikipedia.org/wiki/Heel_Stone]; It is not known whether the ditch and the Heel Stone were meant together (an intended relationship) [SUPPORTED: https://en.wikipedia.org/wiki/Heelstone_Ditch]; Stonehole 97 lies against the Heelstone Ditch [SUPPORTED: https://en.wikipedia.org/wiki/Heelstone_Ditch]; Stonehole 97 has a missing stone [SUPPORTED: https://en.wikipedia.org/wiki/Heelstone_Ditch]; The missing stone of Stonehole 97 is called Heelstone''s twin [SUPPORTED: https://en.wikipedia.org/wiki/Heelstone_Ditch]; Stonehenge, with the Heel Stone, is in England (Wiltshire) [SUPPORTED: https://en.wikipedia.org/wiki/Heel_Stone]"}]'::jsonb),
    ('2f0e58ba-3b2f-4f39-828f-b5d4935121b3'::uuid, 'card_description', NULL, 'Cut into a massive basalt outcrop in the forests on the outskirts of Mumbai, the Kanheri Caves hide halls lined with intricately carved Buddhist sculptures, reliefs, pillars and stupas.', 'teaser-card-s022:2f0e58ba-3b2f-4f39-828f-b5d4935121b3:card_description', 'teaser-card-s022 (teaser-card): teaser card, 185 characters, checked PASS, web-verified VERIFIED', 'e10b9bd938d6f424cc1d3aa7f20651b525b7bf5237f078b231dbe284e8cbd91d|10fece67e5ae3d69621975d2d6cc1d7cc608d6625c2a77f6db348a62c185fa54|10fece67e5ae3d69621975d2d6cc1d7cc608d6625c2a77f6db348a62c185fa54', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-006", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Cut into a massive basalt outcrop in the forests on the outskirts of Mumbai, the Kanheri Caves hide halls lined with intricately carved Buddhist sculptures, reliefs, pillars and stupas."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-006 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "the caves are cut into a massive basalt outcrop [S1]; they are in forests [S1]; they are on the outskirts of Mumbai [S1]; they contain halls [S6]; the halls are lined with intricately carved Buddhist sculptures, reliefs, pillars and stupas [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-018 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "The Kanheri Caves are a group of Buddhist caves and rock-cut monuments (the site is a cave complex) [SUPPORTED: https://en.wikipedia.org/wiki/Kanheri_Caves]; The caves are cut into a massive basalt outcrop [SUPPORTED: https://en.wikipedia.org/wiki/Kanheri_Caves]; The caves lie in forests on the outskirts of Mumbai (India) [SUPPORTED: https://en.wikipedia.org/wiki/Kanheri_Caves]; The caves contain Buddhist sculptures and reliefs [SUPPORTED: https://en.wikipedia.org/wiki/Kanheri_Caves]; The (larger) cave halls are lined with intricately carved Buddhist sculptures, reliefs, pillars and stupas [SUPPORTED: https://en.wikipedia.org/wiki/Kanheri_Caves]"}]'::jsonb),
    ('2f93c277-9023-4fbd-9b56-dc2c4f18c1f6'::uuid, 'card_description', 'A natural chalk hill with a bare patch where legend says Saint George killed the dragon. No grass grows on that spot — supposedly poisoned by the dragon''s blood.', 'Below the Uffington White Horse rises Dragon Hill, its top artificially flattened. Legend says Saint George slew the dragon here, and on a bare patch of chalk no grass will grow.', 'teaser-card-s022:2f93c277-9023-4fbd-9b56-dc2c4f18c1f6:card_description', 'teaser-card-s022 (teaser-card): teaser card, 178 characters, checked PASS, web-verified VERIFIED', '6dafab35b69f945a7d6f72eba6099cdaa97f7658ee786b31e613b0fab1cd540a|7403bf60f44ce6dc44a5529897241c92d76c01ae3fc835217680a95cf4198ab7|7403bf60f44ce6dc44a5529897241c92d76c01ae3fc835217680a95cf4198ab7', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-006", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Below the Uffington White Horse rises Dragon Hill, its top artificially flattened. Legend says Saint George slew the dragon here, and on a bare patch of chalk no grass will grow."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-006 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Dragon Hill is below the Uffington White Horse [S1]; its top is artificially flattened [S2]; legend says Saint George slew the dragon here [S3]; there is a bare patch of chalk on which no grass will grow [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-018 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Dragon Hill is a hill (a small hillock) in the Uffington area of England [SUPPORTED: https://en.wikipedia.org/wiki/Dragon_Hill,_Uffington]; Dragon Hill lies below the Uffington White Horse [SUPPORTED: https://en.wikipedia.org/wiki/Dragon_Hill,_Uffington]; The top of Dragon Hill is artificially flattened [SUPPORTED: https://en.wikipedia.org/wiki/Dragon_Hill,_Uffington]; Legend says Saint George slew the dragon at Dragon Hill [SUPPORTED, no proving quote: https://en.wikipedia.org/wiki/Dragon_Hill,_Uffington]; On Dragon Hill there is a bare patch of chalk on which no grass will grow (purported to be where the dragon''s blood spilled) [SUPPORTED: https://en.wikipedia.org/wiki/Dragon_Hill,_Uffington]"}]'::jsonb),
    ('30cf4488-c74c-42d8-8e21-a017ca0bf921'::uuid, 'card_description', 'A city with many megalithic sites, including the "Four Highland Guards." It sits at the feet of Mount Dempo, a volcano and the highest peak in its province.', 'At the feet of Mount Dempo, on a fertile highland plain ringed by mountains, ancient stone megaliths surround the town of Pagar Alam on all sides, the remnants of a Bronze Age culture.', 'teaser-card-s022:30cf4488-c74c-42d8-8e21-a017ca0bf921:card_description', 'teaser-card-s022 (teaser-card): teaser card, 184 characters, checked PASS, web-verified VERIFIED', '6241ef530379cfe9be33cba10510402ec508e1777efeedec57f77a6f26f5ce18|7a2af29d0f517f97cdb379f2c6f15578fabd1c9c723793776f5ef84a7d3ce080|7a2af29d0f517f97cdb379f2c6f15578fabd1c9c723793776f5ef84a7d3ce080', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-006", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "At the feet of Mount Dempo, on a fertile highland plain ringed by mountains, ancient stone megaliths surround the town of Pagar Alam on all sides, the remnants of a Bronze Age culture."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-006 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Pagar Alam is at the feet of Mount Dempo [S1]; it is on a fertile highland plain [S2]; the plain is surrounded by mountains [S2]; Pagar Alam is a town [S3]; ancient stone megaliths surround the town on all sides [S3]; the megaliths are remnants of a Bronze Age culture [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-018 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Pagar Alam is a town/city in South Sumatra, Indonesia, around which ancient stone megaliths stand (a megalithic landscape around a town) [SUPPORTED: https://en.wikipedia.org/wiki/Pagar_Alam]; Pagar Alam lies at the feet of Mount Dempo [SUPPORTED: https://en.wikipedia.org/wiki/Pagar_Alam]; The town lies on a fertile highland plain [SUPPORTED: https://en.wikipedia.org/wiki/Pagar_Alam]; The highland plain is ringed (surrounded) by mountains [SUPPORTED: https://en.wikipedia.org/wiki/Pagar_Alam]; Ancient stone megaliths are found there [SUPPORTED: https://en.wikipedia.org/wiki/Pagar_Alam]; The megaliths surround the town of Pagar Alam on all sides [SUPPORTED: https://en.wikipedia.org/wiki/Pagar_Alam]; The megaliths are the remnants of a Bronze Age culture (caveat: an archaeological paper on the Pasemah region says the megaliths are ''generally associated with the Bronze Age'' but that their chronology has not been determined) [SUPPORTED: https://en.wikipedia.org/wiki/Pagar_Alam]"}]'::jsonb),
    ('30f619e1-3e2d-4b40-9c9b-49eda0590995'::uuid, 'card_description', '2050-1750 BC pre-Inuit site at the head of Jørgen Brønlund Fjord in northern Greenland, discovered 1948 by Eigil Knuth. One of the largest sites in Peary Land, with Independence I culture features.', 'Near the head of a fjord in northern Greenland, the beach terraces of Deltaterrasserne hold a pre-Inuit campsite, where bone needles with round and rectangular eyeholes were found.', 'teaser-card-s022:30f619e1-3e2d-4b40-9c9b-49eda0590995:card_description', 'teaser-card-s022 (teaser-card): teaser card, 180 characters, checked PASS, web-verified VERIFIED', '72c533b352cb800d7c2a3d2a8a14b6b74f5c47ea6b9dfd4ed1dad07e1de95273|97eb78cde659e735df5afb2d63e1852f057bd80e303dc4d5f830aacb99e4290e|97eb78cde659e735df5afb2d63e1852f057bd80e303dc4d5f830aacb99e4290e', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-006", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Near the head of a fjord in northern Greenland, the beach terraces of Deltaterrasserne hold a pre-Inuit campsite, where bone needles with round and rectangular eyeholes were found."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-006 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "the site is near the head of a fjord [S1]; the site is in northern Greenland [S1]; the site lies on beach terraces [S5]; it is a pre-Inuit site [S1]; it is a campsite [S5]; bone needles were found there [S7]; some needles had round eyeholes and some rectangular eyeholes [S8]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-018 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Deltaterrasserne is a pre-Inuit archaeological (occupation) site in northern Greenland [SUPPORTED: https://en.wikipedia.org/wiki/Deltaterrasserne]; The site lies near the head of a fjord (Jørgen Brønlund Fjord) in northern Greenland (Peary Land) [SUPPORTED: https://en.wikipedia.org/wiki/Deltaterrasserne]; The site consists of beach terraces [SUPPORTED: https://en.wikipedia.org/wiki/Deltaterrasserne]; The site holds a (pre-Inuit) campsite [SUPPORTED: https://en.wikipedia.org/wiki/Deltaterrasserne]; Bone needles were found at the site [SUPPORTED: https://en.wikipedia.org/wiki/Deltaterrasserne]; Some of the bone needles had rectangular eyeholes [SUPPORTED: https://en.wikipedia.org/wiki/Deltaterrasserne]; Other bone needles had round eyeholes [SUPPORTED: https://en.wikipedia.org/wiki/Deltaterrasserne]"}]'::jsonb),
    ('31490608-0d55-49b1-843b-b983ed37ae64'::uuid, 'card_description', 'A Bronze Age hilltop site with stone cists and burial mounds dating from 3300–500 BC. The beacon summit was a ritual focus for millennia.', 'On the hilltop of Sancreed Beacon, in Cornwall''s Penwith peninsula, lie stone cists and Bronze Age burial mounds, while the western slope keeps the remains of a Bronze Age hut.', 'teaser-card-s022:31490608-0d55-49b1-843b-b983ed37ae64:card_description', 'teaser-card-s022 (teaser-card): teaser card, 176 characters, checked PASS, web-verified VERIFIED', 'd0108ffaae36b9c4f5083046a79fc0836d3eb4f6fa21a30b017c10415cc86b96|ec3494cb1c28f8d648ef26f280723e6ae012e4f529ae782bced212c2dd81491d|ec3494cb1c28f8d648ef26f280723e6ae012e4f529ae782bced212c2dd81491d', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-007", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "On the hilltop of Sancreed Beacon, in Cornwall''s Penwith peninsula, lie stone cists and Bronze Age burial mounds, while the western slope keeps the remains of a Bronze Age hut."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-007 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "the remains lie on the hilltop of Sancreed Beacon [S2]; Sancreed Beacon is in Cornwall''s Penwith peninsula [S1]; stone cists lie on the hilltop [S2]; Bronze Age burial mounds lie on the hilltop [S2]; the western slope has the remains of a Bronze Age hut [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-verify-019 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Sancreed Beacon is a Bronze Age archaeological site [SUPPORTED: https://en.wikipedia.org/wiki/Sancreed_Beacon]; Sancreed Beacon lies in the Penwith peninsula of Cornwall [SUPPORTED: https://en.wikipedia.org/wiki/Sancreed_Beacon]; Stone cists lie on top of the hill [SUPPORTED: https://en.wikipedia.org/wiki/Sancreed_Beacon]; Bronze Age burial mounds lie on the hilltop [SUPPORTED: https://en.wikipedia.org/wiki/Sancreed_Beacon]; The western slope keeps the remains of a Bronze Age hut [SUPPORTED: https://en.wikipedia.org/wiki/Sancreed_Beacon]"}]'::jsonb),
    ('31860bc4-476a-49bc-9f97-e25220063d19'::uuid, 'card_description', 'A Paleolithic cave first occupied around 23,500 BC. In the Middle Ages it was reused — ancient humans and medieval people sheltered in the same cavern.', 'Satsurblia Cave, a karst cave in Imereti, held flax fibers, pottery and perforated pendants of stalagmite and polished bone. Its human occupation broke off during the Last Glacial Maximum.', 'teaser-card-s022:31860bc4-476a-49bc-9f97-e25220063d19:card_description', 'teaser-card-s022 (teaser-card): teaser card, 188 characters, checked PASS, web-verified VERIFIED', '7cfa11ce56ec4d5ea591769fa053c2a8ea604280bd520467790d6600d1895c05|64e8fe3a931612575b204330953e1c8cda583c371c1a0d2165ffe5a69916fe13|64e8fe3a931612575b204330953e1c8cda583c371c1a0d2165ffe5a69916fe13', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-007", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Satsurblia Cave, a karst cave in Imereti, held flax fibers, pottery and perforated pendants of stalagmite and polished bone. Its human occupation broke off during the Last Glacial Maximum."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-007 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Satsurblia Cave is a karst cave [S2]; it is in Imereti [S1]; flax fibers were found in the cave [S6]; pottery was found in the cave [S6]; perforated pendants of stalagmite and polished (bovid) bone were found [S7]; human occupation of the cave had a break coinciding with the Last Glacial Maximum [S3, S4, S5]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-verify-019 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Satsurblia Cave is a karst cave [SUPPORTED: https://en.wikipedia.org/wiki/Satsurblia_Cave]; Satsurblia Cave lies in Imereti, Georgia [SUPPORTED: https://en.wikipedia.org/wiki/Satsurblia_Cave]; The cave held flax fibers [SUPPORTED: https://en.wikipedia.org/wiki/Satsurblia_Cave]; The cave held pottery [SUPPORTED: https://en.wikipedia.org/wiki/Satsurblia_Cave]; The cave held perforated pendants of stalagmite and polished bone [SUPPORTED: https://en.wikipedia.org/wiki/Satsurblia_Cave]; Human occupation of the cave broke off (a hiatus) during the Last Glacial Maximum [SUPPORTED: https://en.wikipedia.org/wiki/Satsurblia_Cave]"}]'::jsonb),
    ('339e7c39-0bd9-49c4-8e91-5dfe48c8e140'::uuid, 'card_description', 'Fortified staging post on Watling Street -- today the A5 road -- where travellers paused between larger Roman towns. The town straddles the boundaries of Norton and Whilton in Northamptonshire.', 'On the Roman road later called Watling Street, Bannaventa was a small fortified town where travellers would find a safe, warm rest, buy provisions and stable their horses overnight.', 'teaser-card-s022:339e7c39-0bd9-49c4-8e91-5dfe48c8e140:card_description', 'teaser-card-s022 (teaser-card): teaser card, 181 characters, checked PASS, web-verified VERIFIED', 'f68b15e1d56f761a5c9bdeea610beafe1b1eaa9407c23a044f696630c1cdd270|78b70d0b3c5299cdf1456e1360ec474eed8e8b879630a459ecb8bdbf6a87848d|78b70d0b3c5299cdf1456e1360ec474eed8e8b879630a459ecb8bdbf6a87848d', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-007", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "On the Roman road later called Watling Street, Bannaventa was a small fortified town where travellers would find a safe, warm rest, buy provisions and stable their horses overnight."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-007 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Bannaventa was on the Roman road later called Watling Street [S1]; Bannaventa was a small fortified town [S3]; travellers stopped there (a staging post) [S4]; it would provide travellers a safe, warm resting place [S5]; provisions for the journey could be bought there [S5]; horses could be stabled there overnight [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-verify-019 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Bannaventa was a fortified town [SUPPORTED: https://en.wikipedia.org/wiki/Bannaventa]; Bannaventa lay on the Roman road later called Watling Street [SUPPORTED: https://en.wikipedia.org/wiki/Bannaventa]; Bannaventa was a small town [SUPPORTED: https://en.wikipedia.org/wiki/Bannaventa]; Travellers would find a safe, warm rest in the fortified town [SUPPORTED: https://en.wikipedia.org/wiki/Bannaventa]; Travellers could buy provisions there [SUPPORTED: https://en.wikipedia.org/wiki/Bannaventa]; Horses could be stabled overnight there [SUPPORTED: https://en.wikipedia.org/wiki/Bannaventa]"}]'::jsonb),
    ('33dcafa5-a28f-40c6-a1a3-32d01501c6f2'::uuid, 'card_description', 'Rock painting site at ~3,991 m on the slope of Pukara, north of Cerro de Pasco. At extreme altitude, these paintings preserve the visual language of highland communities who made art in thin air.', 'In Quechua its name means white cave: Yuraq Mach''ay, a site of rock paintings, lies 3,991 metres up on the slope of Pukara, north of the city of Cerro de Pasco in the Pasco Region.', 'teaser-card-s022:33dcafa5-a28f-40c6-a1a3-32d01501c6f2:card_description', 'teaser-card-s022 (teaser-card): teaser card, 180 characters, checked PASS, web-verified VERIFIED', '43d7b255314ecce71f0e51708be2d1525356096d54ef7cdf4ed98e15564c3a27|d3a778ddc96cad17d9abeafbd20713f83f32b42e7254b54723648616d5bd5733|d3a778ddc96cad17d9abeafbd20713f83f32b42e7254b54723648616d5bd5733', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-007", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "In Quechua its name means white cave: Yuraq Mach''ay, a site of rock paintings, lies 3,991 metres up on the slope of Pukara, north of the city of Cerro de Pasco in the Pasco Region."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-007 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "in Quechua the name Yuraq Mach''ay means white cave [S1]; it is a site of rock paintings [S1]; it lies at 3,991 metres [S3]; it is on the slope of Pukara [S3]; it is north of the city of Cerro de Pasco [S3]; it is in the Pasco Region [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-verify-019 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Yuraq Mach''ay is an archaeological site with rock paintings [SUPPORTED: https://en.wikipedia.org/wiki/Yuraq_Mach%27ay]; In Quechua the name means white cave [SUPPORTED: https://en.wikipedia.org/wiki/Yuraq_Mach%27ay]; The site lies at 3,991 metres [SUPPORTED: https://en.wikipedia.org/wiki/Yuraq_Mach%27ay]; The site lies on the slope of Pukara [SUPPORTED: https://en.wikipedia.org/wiki/Yuraq_Mach%27ay]; The site lies north of the city of Cerro de Pasco [SUPPORTED: https://en.wikipedia.org/wiki/Yuraq_Mach%27ay]; The site lies in the Pasco Region (Peru) [SUPPORTED: https://en.wikipedia.org/wiki/Yuraq_Mach%27ay]"}]'::jsonb),
    ('35671923-e17a-4e2b-9333-bf31063c375b'::uuid, 'card_description', 'A summit earthwork atop the Raddon Hills at 235 m elevation. Its strategic position made it a natural lookout point in the Iron Age landscape.', 'On Raddon Top, the highest point of the Raddon Hills in Mid Devon, digs in 1994 revealed an Iron Age hillfort with timber ramparts and a much earlier Neolithic causewayed enclosure.', 'teaser-card-s022:35671923-e17a-4e2b-9333-bf31063c375b:card_description', 'teaser-card-s022 (teaser-card): teaser card, 181 characters, checked PASS, web-verified VERIFIED', '365aaf18fcbb881e0de6409b9119a0ab7a8a2c96528a339c92a157ed22ac69ba|cb0970f347f8bf7fdc335f470725b94f1f1dfb20fecf5400a75f001812b7a0ff|cb0970f347f8bf7fdc335f470725b94f1f1dfb20fecf5400a75f001812b7a0ff', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-007", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "On Raddon Top, the highest point of the Raddon Hills in Mid Devon, digs in 1994 revealed an Iron Age hillfort with timber ramparts and a much earlier Neolithic causewayed enclosure."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-007 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Raddon Top is the highest point of the Raddon Hills [S1]; it is in Mid Devon [S1]; excavations took place in 1994 [S3]; the excavations revealed an Iron Age hillfort with timber ramparts [S3]; the same excavations revealed a much earlier Neolithic causewayed enclosure [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-verify-019 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Raddon Top is the highest point of the Raddon Hills [SUPPORTED: https://en.wikipedia.org/wiki/Raddon_Top]; The Raddon Hills are in Mid Devon [SUPPORTED: https://en.wikipedia.org/wiki/Raddon_Top]; Excavations in 1994 revealed an Iron Age hillfort [SUPPORTED: https://en.wikipedia.org/wiki/Raddon_Top]; The Iron Age hillfort had timber ramparts [SUPPORTED: https://en.wikipedia.org/wiki/Raddon_Top]; The same excavations uncovered a Neolithic causewayed enclosure [SUPPORTED: https://en.wikipedia.org/wiki/Raddon_Top]; The Neolithic causewayed enclosure is much earlier than the Iron Age hillfort [SUPPORTED: https://en.wikipedia.org/wiki/Raddon_Top]"}]'::jsonb),
    ('356a2f8e-8174-48e6-ae7f-8c53b9ae6124'::uuid, 'card_description', '2nd century AD Roman villa discovered in 1941 at a stone quarry. A 1961 dig found a mosaic floor measuring 11 by 7 metres; a 1983 excavation turned up earlier Iron Age remains beneath.', 'In 1941, at Cockle Pits stone quarry, two geometric mosaics came to light at Brantingham Roman Villa. The larger, prepared for removal, was stolen and has never been recovered.', 'teaser-card-s022:356a2f8e-8174-48e6-ae7f-8c53b9ae6124:card_description', 'teaser-card-s022 (teaser-card): teaser card, 176 characters, checked PASS, web-verified VERIFIED', 'f6a3bd4122dc64d657c85b39906c4c71f3ba4f5ccfa98c30c02971bc8650d12d|8663b6fdaf53f6f82d80d51091f6ca5a1c08f9910a0a64b078f5cab9624750a3|8663b6fdaf53f6f82d80d51091f6ca5a1c08f9910a0a64b078f5cab9624750a3', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-007", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "In 1941, at Cockle Pits stone quarry, two geometric mosaics came to light at Brantingham Roman Villa. The larger, prepared for removal, was stolen and has never been recovered."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-007 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "in 1941 two mosaics were uncovered at the site [S3, S6]; the find was at Cockle Pits stone quarry [S3]; the two mosaics were geometric [S3]; the site is Brantingham Roman Villa [S1, S3]; the larger mosaic had been prepared for removal [S8]; the larger mosaic was stolen [S8]; it has never been recovered [S8]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-020 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Brantingham Roman Villa is a Roman villa (a scheduled monument) in England [SUPPORTED: https://en.wikipedia.org/wiki/Brantingham_Roman_villa]; The mosaics came to light in 1941 [SUPPORTED: https://en.wikipedia.org/wiki/Brantingham_Roman_villa]; They came to light at Cockle Pits stone quarry [SUPPORTED: https://en.wikipedia.org/wiki/Brantingham_Roman_villa]; Two mosaics were found at the villa [SUPPORTED: https://en.wikipedia.org/wiki/Brantingham_Roman_villa]; Both mosaics were geometric [SUPPORTED: https://en.wikipedia.org/wiki/Brantingham_Roman_villa]; The larger of the two mosaics had been prepared for removal [SUPPORTED: https://en.wikipedia.org/wiki/Brantingham_Roman_villa]; The larger mosaic was stolen [SUPPORTED: https://en.wikipedia.org/wiki/Brantingham_Roman_villa]; The stolen mosaic has never been recovered [SUPPORTED: https://en.wikipedia.org/wiki/Brantingham_Roman_villa]"}]'::jsonb),
    ('3635030a-59d7-4fcf-84b2-e22a000e6b7d'::uuid, 'card_description', 'In 1841 John L. Stephens was the first to document parts of the Mayapan site with two important illustrations.', 'Inside a stone wall 9.1 km long with twelve gates, Mayapan held more than 4,000 structures. A major Maya capital in the Yucatán, it was abandoned sometime in the 15th century.', 'teaser-card-s022:3635030a-59d7-4fcf-84b2-e22a000e6b7d:card_description', 'teaser-card-s022 (teaser-card): teaser card, 175 characters, checked PASS, web-verified VERIFIED', '8b5b9276a627c26153c1cbceaa6477e132493b98827b807996a680e7e02ba733|652ede45f1877fa0ebe35235ff53f760edb78ac25309c4e2886a76d0b5986965|652ede45f1877fa0ebe35235ff53f760edb78ac25309c4e2886a76d0b5986965', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-007", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Inside a stone wall 9.1 km long with twelve gates, Mayapan held more than 4,000 structures. A major Maya capital in the Yucatán, it was abandoned sometime in the 15th century."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-007 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Mayapan has a stone wall [S3]; the wall is 9.1 km long [S4]; the wall has twelve gates [S3]; more than 4,000 structures stand within the walls [S2]; Mayapan was a Maya site [S1]; it was a major capital in the Yucatán [S7]; it was abandoned sometime in the 15th century [S8]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-020 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Mayapan is a major Maya capital in the Yucatán (Mexico) [SUPPORTED: https://en.wikipedia.org/wiki/Mayapan]; Mayapan is a Pre-Columbian Maya site in the state of Yucatán, Mexico [SUPPORTED: https://en.wikipedia.org/wiki/Mayapan]; Mayapan was a major capital in the Yucatán [SUPPORTED: https://en.wikipedia.org/wiki/Mayapan]; The city was enclosed by a stone wall 9.1 km long [SUPPORTED: https://en.wikipedia.org/wiki/Mayapan]; The stone wall has twelve gates [SUPPORTED: https://en.wikipedia.org/wiki/Mayapan]; Mayapan held more than 4,000 structures inside the wall [SUPPORTED: https://en.wikipedia.org/wiki/Mayapan]; Mayapan was abandoned sometime in the 15th century [SUPPORTED: https://en.wikipedia.org/wiki/Mayapan]"}]'::jsonb),
    ('3696e872-ce24-42c2-b632-fe7b034171df'::uuid, 'card_description', NULL, 'Once filled with dirt and rubble, Karahan Tepe preserved its T-topped columns carved into bedrock. Dating to between 10,000 and 9500 BC, it may be the earliest known human village.', 'teaser-card-s022:3696e872-ce24-42c2-b632-fe7b034171df:card_description', 'teaser-card-s022 (teaser-card): teaser card, 180 characters, checked PASS, web-verified VERIFIED', '4b236cbe3c0a2ef744553d061c60580470039415c8c4265c1fd8cb6344fb403f|c0b72d4a454a5970f4d07199af7ff403789dee9dae3b2de9eb92fb5d26628b59|c0b72d4a454a5970f4d07199af7ff403789dee9dae3b2de9eb92fb5d26628b59', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-007", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Once filled with dirt and rubble, Karahan Tepe preserved its T-topped columns carved into bedrock. Dating to between 10,000 and 9500 BC, it may be the earliest known human village."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-007 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Karahan Tepe was at some point filled with dirt and rubble [S4]; this preserved its T-topped columns [S4]; the columns are carved into bedrock [S4]; the site dates to between 10,000 and 9500 BC [S3]; it may be the earliest known human village (hedged) [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-020 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Karahan Tepe is a Pre-Pottery Neolithic archaeological site (a prehistoric settlement) in Şanlıurfa, Türkiye [SUPPORTED: https://en.wikipedia.org/wiki/Karahan_Tepe]; The site was once filled with dirt and rubble [SUPPORTED: https://en.wikipedia.org/wiki/Karahan_Tepe]; Karahan Tepe preserved T-topped columns carved into bedrock [SUPPORTED: https://en.wikipedia.org/wiki/Karahan_Tepe]; The site dates to between 10,000 and 9500 BC [SUPPORTED: https://en.wikipedia.org/wiki/Karahan_Tepe]; It may be the earliest known human village [SUPPORTED: https://en.wikipedia.org/wiki/Karahan_Tepe]"}]'::jsonb),
    ('36b645fb-d402-4609-a842-623f8dc0f0e3'::uuid, 'card_description', 'Built for two brothers around 250 BC, this Macedonian tomb held a century of family burials. Its painted walls preserve Hellenistic art in vivid color.', 'Under an earthen tumulus in Mieza lies the Tomb of Lyson and Kallikles, built around 250 BC for two brothers: two vaulted chambers, with weapons and armour painted above the doorways.', 'teaser-card-s022:36b645fb-d402-4609-a842-623f8dc0f0e3:card_description', 'teaser-card-s022 (teaser-card): teaser card, 183 characters, checked PASS, web-verified VERIFIED', '226de0816e44edc83965467bbc8c3ab4aa2858c98856e328ca9f1c5b5d1924ee|d15ca63bb97841a4e472177d86cb6ee0f06c6792d1bf023d41329bac7adf0e02|d15ca63bb97841a4e472177d86cb6ee0f06c6792d1bf023d41329bac7adf0e02', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-007", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Under an earthen tumulus in Mieza lies the Tomb of Lyson and Kallikles, built around 250 BC for two brothers: two vaulted chambers, with weapons and armour painted above the doorways."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-007 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "the tomb is covered by an earthen tumulus [S3]; it is in Mieza [S1]; it was built around 250 BC [S2]; it was built for two brothers (Lyson and Kallikles) [S2]; it has two vaulted chambers [S3]; weapons and armour are painted above the doorways [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-020 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "The Tomb of Lyson and Kallikles is an ancient Macedonian tomb in Mieza [SUPPORTED: https://en.wikipedia.org/wiki/Tomb_of_Lyson_and_Kallikles]; Mieza (Lefkadia, near Naousa, Imathia) is in Greece [SUPPORTED: https://en.wikipedia.org/wiki/Mieza_(Macedonia)]; The tomb lies under an earthen tumulus [SUPPORTED: https://en.wikipedia.org/wiki/Tomb_of_Lyson_and_Kallikles]; The tomb was built around 250 BC [SUPPORTED: https://en.wikipedia.org/wiki/Tomb_of_Lyson_and_Kallikles]; The tomb was built for two brothers, Lyson and Kallikles [SUPPORTED: https://en.wikipedia.org/wiki/Tomb_of_Lyson_and_Kallikles]; The tomb has two vaulted chambers [SUPPORTED: https://en.wikipedia.org/wiki/Tomb_of_Lyson_and_Kallikles]; Weapons and armour are painted above the doorways [SUPPORTED: https://en.wikipedia.org/wiki/Tomb_of_Lyson_and_Kallikles]"}]'::jsonb),
    ('373ccffa-991d-4455-b116-19957b288a28'::uuid, 'card_description', 'Two 1st-century Roman marching camps flanking Dere Street, the military road from York into Scotland. Troops camped here during campaigns against northern tribes.', 'Beside Dere Street, a Roman road running into Scotland, the Featherwood Roman Camps lie about 500 metres apart, two Roman camps that are now scheduled monuments.', 'teaser-card-s022:373ccffa-991d-4455-b116-19957b288a28:card_description', 'teaser-card-s022 (teaser-card): teaser card, 161 characters, checked PASS, web-verified VERIFIED', '40ed240b0110a3bc75db9815db340e05c395a91fc6e7545820da8b68fe3c781e|2b7875459ae24e5724ff8b3aef46066abb89696b366ae449cb911944db0c0aae|2b7875459ae24e5724ff8b3aef46066abb89696b366ae449cb911944db0c0aae', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-rewrite-v-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Beside Dere Street, a Roman road running into Scotland, the Featherwood Roman Camps lie about 500 metres apart, two Roman camps that are now scheduled monuments."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-v-001 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "the camps are beside Dere Street [S3]; Dere Street is a Roman road running into Scotland [S3]; the two camps lie about 500 metres apart [S3]; they are Roman camps, two of them [S2]; the camps are scheduled monuments [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify2-002 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "The site is two Roman camps [SUPPORTED: https://en.wikipedia.org/wiki/Featherwood_Roman_Camps]; The camps are scheduled monuments [SUPPORTED: https://en.wikipedia.org/wiki/Featherwood_Roman_Camps]; The camps lie about 500 metres apart [SUPPORTED: https://en.wikipedia.org/wiki/Featherwood_Roman_Camps]; The camps lie beside Dere Street [SUPPORTED: https://en.wikipedia.org/wiki/Featherwood_Roman_Camps]; Dere Street is a Roman road running into Scotland [SUPPORTED: https://en.wikipedia.org/wiki/Featherwood_Roman_Camps]"}]'::jsonb);

